LC.course={"slug":"learnmandarin","domain":"learnmandarin.zyeemzia.com","title":"Learn Mandarin","native":"轻松学中文","tagline":"Easy Mandarin Chinese for English speakers: pinyin, tones, characters and real conversations.","lang":"Mandarin Chinese","langNative":"中文","voice":"zh-CN","htmlLang":"zh-Hans","cjk":true,"mark":"中","greeting":"你好！","greetingMeaning":"Hello! (nǐ hǎo)","alphabetTitle":"Pinyin & Tones","alphabetShort":"Pinyin","alphabetIntro":"Initials, finals and the four tones: the sound system of Mandarin. Tap any sound to hear it in a real character.","rootsLabel":"Radicals","hanzi":true,"wish":{"t":"恭喜你！","mean":"Congratulations! (gōngxǐ nǐ)"},"pdf":"Learn-Mandarin-Book.pdf","accent":"#b3261e","fontsCss":"family=Noto+Sans+SC:wght@400;500;700&family=Figtree:wght@400;500;600;700&family=Reem+Kufi:wght@600;700","targetFont":"\"Noto Sans SC\", \"PingFang SC\", \"Microsoft YaHei\", sans-serif"};
LC.alphabet={"groups":[{"id":"initials","label":"Initials","note":"The consonant that starts a syllable. Mandarin has 21, plus y and w as spelling helpers."},{"id":"finals","label":"Finals","note":"Everything after the initial: simple vowels, vowel glides and finals ending in n or ng."},{"id":"tones","label":"Tones","note":"The pitch of the voice. Four main tones plus a light neutral tone change the meaning of a syllable."}],"items":[{"id":"b","ch":"b","name":"b","say":"爸","tr":"bà","group":"initials","sound":"Like the p in \"spin\": lips together, then open with no puff of air. To English ears it sounds close to b.","example":{"t":"爸爸","tr":"bàba","mean":"dad"},"tip":"Hold a tissue in front of your lips: for b it should hardly move."},{"id":"p","ch":"p","name":"p","say":"怕","tr":"pà","group":"initials","sound":"Like the p in \"pie\", with a strong puff of air.","example":{"t":"朋友","tr":"péngyou","mean":"friend"},"tip":"For p the tissue should flutter. b and p differ by the puff, not by the voice."},{"id":"m","ch":"m","name":"m","say":"妈","tr":"mā","group":"initials","sound":"Just like English m in \"mum\".","example":{"t":"妈妈","tr":"māma","mean":"mum"}},{"id":"f","ch":"f","name":"f","say":"发","tr":"fā","group":"initials","sound":"Just like English f in \"fun\".","example":{"t":"米饭","tr":"mǐfàn","mean":"cooked rice"}},{"id":"d","ch":"d","name":"d","say":"大","tr":"dà","group":"initials","sound":"Like the t in \"stop\": tongue tip behind the top teeth, no puff of air. Sounds close to English d.","example":{"t":"弟弟","tr":"dìdi","mean":"younger brother"}},{"id":"t","ch":"t","name":"t","say":"他","tr":"tā","group":"initials","sound":"Like the t in \"top\", with a strong puff of air.","example":{"t":"天气","tr":"tiānqì","mean":"weather"}},{"id":"n","ch":"n","name":"n","say":"那","tr":"nà","group":"initials","sound":"Just like English n in \"no\".","example":{"t":"你","tr":"nǐ","mean":"you"}},{"id":"l","ch":"l","name":"l","say":"拉","tr":"lā","group":"initials","sound":"Just like English l in \"let\".","example":{"t":"老师","tr":"lǎoshī","mean":"teacher"}},{"id":"g","ch":"g","name":"g","say":"哥","tr":"gē","group":"initials","sound":"Like the k in \"skin\": no puff of air. Sounds close to the g in \"go\".","example":{"t":"哥哥","tr":"gēge","mean":"older brother"}},{"id":"k","ch":"k","name":"k","say":"可","tr":"kě","group":"initials","sound":"Like the k in \"kite\", with a strong puff of air.","example":{"t":"咖啡","tr":"kāfēi","mean":"coffee"}},{"id":"h","ch":"h","name":"h","say":"喝","tr":"hē","group":"initials","sound":"Rougher than English h: the air rubs at the back of the mouth, a little like a soft \"ch\" in Scottish \"loch\".","example":{"t":"好","tr":"hǎo","mean":"good"}},{"id":"j","ch":"j","name":"j","say":"鸡","tr":"jī","group":"initials","sound":"Like the j in \"jeep\", but keep the tongue tip down behind your lower teeth and smile. No puff of air.","example":{"t":"家","tr":"jiā","mean":"home, family"},"tip":"j, q and x only ever come before i or ü."},{"id":"q","ch":"q","name":"q","say":"七","tr":"qī","group":"initials","sound":"Like the ch in \"cheese\", but with the tongue tip down behind your lower teeth, plus a puff of air.","example":{"t":"钱","tr":"qián","mean":"money"},"tip":"q is never \"kw\"! 七 qī sounds like \"chee\"."},{"id":"x","ch":"x","name":"x","say":"西","tr":"xī","group":"initials","sound":"Between s and sh: tongue tip down behind the lower teeth, lips in a smile, like \"sh\" in \"sheep\" said while smiling.","example":{"t":"谢谢","tr":"xièxie","mean":"thank you"},"tip":"x is never \"ks\"! 西 xī sounds like \"shee\"."},{"id":"zh","ch":"zh","name":"zh","say":"知","tr":"zhī","group":"initials","sound":"Like the j in \"judge\", but with the tongue tip curled back to touch the roof of the mouth. No puff of air.","example":{"t":"中国","tr":"Zhōngguó","mean":"China"}},{"id":"ch","ch":"ch","name":"ch","say":"吃","tr":"chī","group":"initials","sound":"Like the ch in \"church\", with the tongue tip curled back and a puff of air.","example":{"t":"茶","tr":"chá","mean":"tea"}},{"id":"sh","ch":"sh","name":"sh","say":"十","tr":"shí","group":"initials","sound":"Like the sh in \"shirt\", with the tongue tip curled back.","example":{"t":"书","tr":"shū","mean":"book"}},{"id":"r","ch":"r","name":"r","say":"日","tr":"rì","group":"initials","sound":"Curl the tongue back as for sh and add your voice: somewhere between the r in \"run\" and the s in \"pleasure\".","example":{"t":"人","tr":"rén","mean":"person"}},{"id":"z","ch":"z","name":"z","say":"字","tr":"zì","group":"initials","sound":"Like the ds in \"kids\". No puff of air.","example":{"t":"再见","tr":"zàijiàn","mean":"goodbye"}},{"id":"c","ch":"c","name":"c","say":"词","tr":"cí","group":"initials","sound":"Like the ts in \"cats\", with a strong puff of air.","example":{"t":"菜","tr":"cài","mean":"dish, vegetable"},"tip":"c is never k! 菜 cài sounds like \"tsai\"."},{"id":"s","ch":"s","name":"s","say":"四","tr":"sì","group":"initials","sound":"Just like the s in \"sun\".","example":{"t":"三","tr":"sān","mean":"three"}},{"id":"y","ch":"y","name":"y","say":"牙","tr":"yá","group":"initials","sound":"Like the y in \"yes\". In pinyin, y is really a spelling for i or ü at the start of a syllable.","example":{"t":"医生","tr":"yīshēng","mean":"doctor"}},{"id":"w","ch":"w","name":"w","say":"我","tr":"wǒ","group":"initials","sound":"Like the w in \"we\". In pinyin, w is really a spelling for u at the start of a syllable.","example":{"t":"晚上","tr":"wǎnshang","mean":"evening"}},{"id":"a","ch":"a","name":"a","say":"啊","tr":"ā","group":"finals","sound":"Like the a in \"father\", with the mouth wide open.","example":{"t":"大","tr":"dà","mean":"big"}},{"id":"o","ch":"o","name":"o","say":"哦","tr":"ò","group":"finals","sound":"Like \"aw\" with rounded lips. After b p m f a tiny \"w\" slips in: bo sounds like \"bwaw\".","example":{"t":"伯伯","tr":"bóbo","mean":"uncle (dad's older brother)"}},{"id":"e","ch":"e","name":"e","say":"饿","tr":"è","group":"finals","sound":"Not like English e! Say the \"u\" of \"duh\" further back in the throat, lips relaxed and spread.","example":{"t":"喝","tr":"hē","mean":"to drink"}},{"id":"i","ch":"i","name":"i","say":"一","tr":"yī","group":"finals","sound":"Like the ee in \"see\". After z c s zh ch sh r it is not \"ee\" but a buzz (see Unit 1).","example":{"t":"米","tr":"mǐ","mean":"rice (grain)"}},{"id":"u","ch":"u","name":"u","say":"五","tr":"wǔ","group":"finals","sound":"Like the oo in \"food\", with lips well rounded.","example":{"t":"书","tr":"shū","mean":"book"}},{"id":"u-umlaut","ch":"ü","name":"ü","say":"鱼","tr":"yú","group":"finals","sound":"Say \"ee\", then round your lips as for \"oo\" without moving your tongue. Like French u or German ü.","example":{"t":"女","tr":"nǚ","mean":"woman, female"},"tip":"Smile-and-kiss: tongue says \"ee\", lips say \"oo\"."},{"id":"er","ch":"er","name":"er","say":"二","tr":"èr","group":"finals","sound":"Like \"are\" in American English, with the tongue tip curled back.","example":{"t":"儿子","tr":"érzi","mean":"son"}},{"id":"ai","ch":"ai","name":"ai","say":"爱","tr":"ài","group":"finals","sound":"Like \"eye\".","example":{"t":"白","tr":"bái","mean":"white"}},{"id":"ei","ch":"ei","name":"ei","say":"飞","tr":"fēi","group":"finals","sound":"Like the \"ay\" in \"say\".","example":{"t":"黑","tr":"hēi","mean":"black"}},{"id":"ao","ch":"ao","name":"ao","say":"好","tr":"hǎo","group":"finals","sound":"Like the \"ow\" in \"cow\".","example":{"t":"猫","tr":"māo","mean":"cat"}},{"id":"ou","ch":"ou","name":"ou","say":"欧","tr":"ōu","group":"finals","sound":"Like the \"o\" in \"go\".","example":{"t":"狗","tr":"gǒu","mean":"dog"}},{"id":"an","ch":"an","name":"an","say":"安","tr":"ān","group":"finals","sound":"Like \"ahn\": the a of \"father\" plus a clear n.","example":{"t":"饭","tr":"fàn","mean":"meal"}},{"id":"en","ch":"en","name":"en","say":"门","tr":"mén","group":"finals","sound":"Like the \"un\" in \"under\" plus n, or the \"en\" in \"taken\".","example":{"t":"很","tr":"hěn","mean":"very"}},{"id":"ang","ch":"ang","name":"ang","say":"忙","tr":"máng","group":"finals","sound":"Like \"ahng\": the a of \"father\" plus the ng of \"sing\".","example":{"t":"汤","tr":"tāng","mean":"soup"}},{"id":"eng","ch":"eng","name":"eng","say":"冷","tr":"lěng","group":"finals","sound":"Like the \"ung\" in \"lung\".","example":{"t":"灯","tr":"dēng","mean":"lamp, light"}},{"id":"ong","ch":"ong","name":"ong","say":"东","tr":"dōng","group":"finals","sound":"Between the \"ong\" of \"song\" and \"oong\", with rounded lips.","example":{"t":"红","tr":"hóng","mean":"red"}},{"id":"ia","ch":"ia","name":"ia","say":"家","tr":"jiā","group":"finals","sound":"\"ee\" + \"ah\" glided together, like \"yah\".","example":{"t":"下","tr":"xià","mean":"down, below"}},{"id":"ie","ch":"ie","name":"ie","say":"也","tr":"yě","group":"finals","sound":"\"ee\" + \"eh\", like the \"ye\" in \"yes\".","example":{"t":"谢谢","tr":"xièxie","mean":"thank you"}},{"id":"iao","ch":"iao","name":"iao","say":"要","tr":"yào","group":"finals","sound":"\"ee\" + \"ow\", like \"yow\".","example":{"t":"小","tr":"xiǎo","mean":"small"}},{"id":"iu","ch":"iu (iou)","name":"iu","say":"六","tr":"liù","group":"finals","sound":"Short for iou: \"ee\" + \"oh\", like \"yo\". 六 liù sounds like \"lyoh\".","example":{"t":"九","tr":"jiǔ","mean":"nine"}},{"id":"ian","ch":"ian","name":"ian","say":"天","tr":"tiān","group":"finals","sound":"Careful: ian sounds like \"yen\", not \"yan\".","example":{"t":"钱","tr":"qián","mean":"money"},"tip":"ian rhymes with \"ten\", not with \"fan\"."},{"id":"in","ch":"in","name":"in","say":"心","tr":"xīn","group":"finals","sound":"Like the \"een\" in \"seen\", but shorter.","example":{"t":"今天","tr":"jīntiān","mean":"today"}},{"id":"iang","ch":"iang","name":"iang","say":"想","tr":"xiǎng","group":"finals","sound":"\"ee\" + \"ahng\", like \"yahng\".","example":{"t":"两","tr":"liǎng","mean":"two (of something)"}},{"id":"ing","ch":"ing","name":"ing","say":"听","tr":"tīng","group":"finals","sound":"Like the \"ing\" in \"sing\", often with a light \"uh\" glide before the ng.","example":{"t":"名字","tr":"míngzi","mean":"name"}},{"id":"iong","ch":"iong","name":"iong","say":"用","tr":"yòng","group":"finals","sound":"\"ee\" + \"oong\", like \"yoong\".","example":{"t":"熊","tr":"xióng","mean":"bear"}},{"id":"ua","ch":"ua","name":"ua","say":"花","tr":"huā","group":"finals","sound":"\"oo\" + \"ah\", like \"wah\".","example":{"t":"西瓜","tr":"xīguā","mean":"watermelon"}},{"id":"uo","ch":"uo","name":"uo","say":"多","tr":"duō","group":"finals","sound":"\"oo\" + \"aw\", like \"waw\".","example":{"t":"国","tr":"guó","mean":"country"}},{"id":"uai","ch":"uai","name":"uai","say":"快","tr":"kuài","group":"finals","sound":"\"oo\" + \"eye\", like \"why\".","example":{"t":"筷子","tr":"kuàizi","mean":"chopsticks"}},{"id":"ui","ch":"ui (uei)","name":"ui","say":"对","tr":"duì","group":"finals","sound":"Short for uei: \"oo\" + \"ay\", like \"way\". 对 duì sounds like \"dway\".","example":{"t":"水","tr":"shuǐ","mean":"water"}},{"id":"uan","ch":"uan","name":"uan","say":"欢","tr":"huān","group":"finals","sound":"\"oo\" + \"ahn\", like \"wahn\".","example":{"t":"玩","tr":"wán","mean":"to play"}},{"id":"un","ch":"un (uen)","name":"un","say":"春","tr":"chūn","group":"finals","sound":"Short for uen: \"oo\" + \"un\", like \"won\".","example":{"t":"困","tr":"kùn","mean":"sleepy"}},{"id":"uang","ch":"uang","name":"uang","say":"黄","tr":"huáng","group":"finals","sound":"\"oo\" + \"ahng\", like \"wahng\".","example":{"t":"床","tr":"chuáng","mean":"bed"}},{"id":"u-umlaut-e","ch":"üe","name":"üe","say":"月","tr":"yuè","group":"finals","sound":"ü + \"eh\": start with rounded lips, then open to \"eh\".","example":{"t":"学","tr":"xué","mean":"to study"}},{"id":"u-umlaut-an","ch":"üan","name":"üan","say":"远","tr":"yuǎn","group":"finals","sound":"ü + \"en\": like \"ywen\".","example":{"t":"元","tr":"yuán","mean":"yuan (money)"}},{"id":"u-umlaut-n","ch":"ün","name":"ün","say":"云","tr":"yún","group":"finals","sound":"ü + n: keep the lips rounded, then close with n.","example":{"t":"裙子","tr":"qúnzi","mean":"skirt"}},{"id":"tone-1","ch":"mā","name":"1st tone (high and level)","say":"妈","tr":"mā","group":"tones","sound":"High and flat, like holding one long note when you sing. Keep the voice up and steady.","example":{"t":"妈妈","tr":"māma","mean":"mum"},"tip":"The mark ¯ is flat, just like the voice."},{"id":"tone-2","ch":"má","name":"2nd tone (rising)","say":"麻","tr":"má","group":"tones","sound":"Rising from middle to high, like a surprised \"What?\".","example":{"t":"茶","tr":"chá","mean":"tea"},"tip":"The mark ´ climbs up, just like the voice."},{"id":"tone-3","ch":"mǎ","name":"3rd tone (low, dipping)","say":"马","tr":"mǎ","group":"tones","sound":"Low, dipping down and coming back up, like a doubtful \"Well...?\". In quick speech it often just stays low.","example":{"t":"好","tr":"hǎo","mean":"good"},"tip":"The mark ˇ is a valley: down, then up."},{"id":"tone-4","ch":"mà","name":"4th tone (falling)","say":"骂","tr":"mà","group":"tones","sound":"Falling sharply from high to low, like a firm \"No!\" or \"Go!\".","example":{"t":"不","tr":"bù","mean":"not, no"},"tip":"The mark ` drops down, just like the voice."},{"id":"tone-0","ch":"ma","name":"Neutral tone (light)","say":"吗","tr":"ma","group":"tones","sound":"Short, light and unstressed, with no mark. Its pitch depends on the syllable before it.","example":{"t":"谢谢","tr":"xièxie","mean":"thank you"},"tip":"No mark, no effort: just let it drop lightly."}]};
LC.units.push({"id":"pinyin","order":1,"icon":"ā","color":"teal","title":"Pinyin & Tones","subtitle":"The sounds of Mandarin: initials, finals, the four tones and how to read pinyin","lessons":[{"id":"u1-syllable","icon":"音","title":"How a Mandarin Syllable Works","subtitle":"Initial + final + tone: the three parts of every syllable","minutes":8,"goals":["Name the three parts of a Mandarin syllable","See why one character = one syllable","Know what pinyin is for"],"blocks":[{"type":"text","text":"Welcome to Mandarin! Before characters, we learn the sounds. Chinese is written in characters, but learners (and Chinese children) use **pinyin**, the official Roman-letter spelling, to see how each character sounds."},{"type":"text","text":"Good news: Mandarin syllables are very regular. Every syllable has the same three parts: an **initial**, a **final** and a **tone**.","title":"Three parts"},{"type":"steps","items":[{"title":"Initial","desc":"The consonant at the start, like m, h or zh. Some syllables have no initial at all."},{"title":"Final","desc":"Everything after the initial: a vowel, a glide like ao, or a vowel + n / ng."},{"title":"Tone","desc":"The pitch of your voice: high, rising, dipping or falling. It is shown by a mark over a vowel."}],"title":"The recipe"},{"type":"table","head":["Character","Initial","Final","Tone","Pinyin"],"rows":[["{{妈}}","m","a","1st","mā"],["{{好}}","h","ao","3rd","hǎo"],["{{中}}","zh","ong","1st","zhōng"],["{{学}}","x","üe (written ue)","2nd","xué"],["{{是}}","sh","i","4th","shì"],["{{爱}}","(none)","ai","4th","ài"]],"title":"Taking syllables apart"},{"type":"rule","name":"One character = one syllable","color":"blue","desc":"Each Chinese character is read as exactly one syllable. A word of two characters has two syllables.","how":"Count the characters and you know how many syllables to say.","examples":[{"t":"你好","tr":"nǐ hǎo"},{"t":"中国","tr":"Zhōngguó"},{"t":"谢谢","tr":"xièxie"}]},{"type":"tip","kind":"fun","text":"Mandarin has only about 400 basic syllables (around 1,300 with tones), while English has thousands. That is why tones matter so much: they keep words apart."},{"type":"text","text":"Same initial, same final, different tone: a completely different word. Tap each one and listen.","title":"Tones change meaning"},{"type":"examples","items":[{"t":"妈","tr":"mā","mean":"mother"},{"t":"麻","tr":"má","mean":"hemp; numb"},{"t":"马","tr":"mǎ","mean":"horse"},{"t":"骂","tr":"mà","mean":"to scold"}]},{"type":"tip","kind":"memory","text":"Think of a syllable as a sandwich: the initial is the top slice, the final is the filling, and the tone is the sauce. Leave out the sauce and it is a different meal!"},{"type":"tip","kind":"tip","text":"Pinyin letters do not always sound like English letters. q, x, c and zh are the big surprises. We meet them all in this unit."},{"type":"letters","items":["m","a","tone-1","h","ao","tone-3"],"title":"Sounds in this lesson"},{"type":"practice","text":"Tap each character, listen, then say it out loud. Name its initial, final and tone.","lines":["妈","好","中","学","是","爱"]},{"type":"quiz","items":[{"q":"What are the three parts of a Mandarin syllable?","options":["Root, prefix, suffix","Vowel, accent, stress","Initial, final, tone","Letter, word, phrase"],"answer":2},{"q":"How many syllables does a character have?","options":["One","Two","It depends","Three"],"answer":0},{"q":"In {{好}} hǎo, what is the final?","options":["h","hǎ","o","ao"],"answer":3},{"q":"Which syllable has no initial?","options":["mā","ài","shì","hǎo"],"answer":1},{"q":"What is pinyin?","options":["A kind of character","The official Roman-letter spelling of Mandarin sounds","A Chinese dialect","The name of the 4th tone"],"answer":1},{"q":"{{妈}} mā and {{马}} mǎ differ only in their...","options":["initial","final","number of syllables","tone"],"answer":3}],"title":"Quick quiz"}]},{"id":"u1-tones","icon":"ā","title":"The Four Tones + the Neutral Tone","subtitle":"High, rising, dipping, falling, and light","minutes":12,"goals":["Say the four tones clearly","Recognise the tone marks","Hear the difference between tones","Use the light neutral tone"],"blocks":[{"type":"text","text":"Tones are the music of Mandarin. Every syllable is said with a pitch shape, and the shape is part of the word. Do not worry: with a little daily practice, your ears and voice will learn them."},{"type":"letters","items":["tone-1","tone-2","tone-3","tone-4","tone-0"],"title":"The tones"},{"type":"rule","name":"1st tone: high and level","color":"red","desc":"Start high and stay high, like singing one long note.","how":"Mark: ¯ (a flat line).","examples":[{"t":"妈","tr":"mā"},{"t":"八","tr":"bā"},{"t":"书","tr":"shū"}]},{"type":"rule","name":"2nd tone: rising","color":"orange","desc":"Start in the middle and go up, like asking \"Huh?\" or \"What?\".","how":"Mark: ´ (a line going up).","examples":[{"t":"麻","tr":"má"},{"t":"茶","tr":"chá"},{"t":"来","tr":"lái"}]},{"type":"rule","name":"3rd tone: low and dipping","color":"green","desc":"Go low, dip down, and (when the syllable is said alone) come back up.","how":"Mark: ˇ (a little valley).","examples":[{"t":"马","tr":"mǎ"},{"t":"好","tr":"hǎo"},{"t":"你","tr":"nǐ"}]},{"type":"rule","name":"4th tone: falling","color":"blue","desc":"Start high and drop sharply, like a firm \"No!\".","how":"Mark: ` (a line going down).","examples":[{"t":"骂","tr":"mà"},{"t":"是","tr":"shì"},{"t":"不","tr":"bù"}]},{"type":"rule","name":"Neutral tone: light","color":"gray","desc":"Short, soft and quick, with no mark. It often appears on the second half of a word or on little grammar words.","how":"No mark at all.","examples":[{"t":"吗","tr":"ma"},{"t":"妈妈","tr":"māma","hl":"妈"},{"t":"谢谢","tr":"xièxie"}]},{"type":"table","head":["Tone","Mark","Pitch","Feels like"],"rows":[["1st","ā","high, flat","singing a long note"],["2nd","á","middle → high","a surprised \"What?\""],["3rd","ǎ","low, dip (→ up)","a doubtful \"Well...?\""],["4th","à","high → low","a firm \"No!\""],["neutral","a","short, light","a quick, soft beat"]],"title":"Tones at a glance"},{"type":"tip","kind":"memory","text":"Draw the tone in the air with your hand as you say it: flat line, up, dip, down. Your voice follows your hand."},{"type":"compare","items":[{"t":"汤","label":"1st tone · tāng","desc":"soup"},{"t":"糖","label":"2nd tone · táng","desc":"sugar, sweets"},{"t":"躺","label":"3rd tone · tǎng","desc":"to lie down"},{"t":"烫","label":"4th tone · tàng","desc":"very hot (to touch)"}],"title":"Same sound, four meanings"},{"type":"tip","kind":"fun","text":"Mixing up tones can be funny: ask for {{汤}} tāng (soup) with the wrong tone and you might be asking for {{糖}} táng (sugar)!"},{"type":"text","text":"Most people speak the 3rd tone low and only rise at the end of a sentence or when the syllable is said alone. Practise the low part first: it is the most important.","title":"About the 3rd tone"},{"type":"practice","text":"Tap and repeat each row. Exaggerate the tones: big tones now, natural tones later.","lines":["妈 麻 马 骂 吗","八 拔 把 爸","汤 糖 躺 烫","书 熟 鼠 树"]},{"type":"quiz","items":[{"q":"Listen. Which tone do you hear?","say":"马","options":["1st tone","2nd tone","3rd tone","4th tone"],"answer":2,"explain":"马 mǎ (horse) has the dipping 3rd tone."},{"q":"Listen. Which tone do you hear?","say":"烫","options":["1st tone","2nd tone","3rd tone","4th tone"],"answer":3,"explain":"烫 tàng (very hot) falls: 4th tone."},{"q":"Listen. Which tone do you hear?","say":"书","options":["1st tone","2nd tone","3rd tone","4th tone"],"answer":0,"explain":"书 shū (book) is high and level: 1st tone."},{"q":"Listen. Which tone do you hear?","say":"茶","options":["1st tone","2nd tone","3rd tone","4th tone"],"answer":1,"explain":"茶 chá (tea) rises: 2nd tone."},{"q":"Which tone mark looks like a little valley?","options":["ǎ","á","à","ā"],"answer":0},{"q":"Which word means \"horse\"?","options":["mā","má","mǎ","mà"],"answer":2},{"q":"How is the neutral tone written?","options":["With no mark","With a dot","With a circle","With two lines"],"answer":0},{"q":"Which tone sounds like a firm \"No!\"?","options":["1st tone","2nd tone","4th tone","Neutral tone"],"answer":2}],"title":"Quick quiz"}]},{"id":"u1-initials","icon":"b","title":"Initials, Group by Group","subtitle":"b p m f · d t n l · g k h","minutes":12,"goals":["Say the lip, tongue-tip and back-of-tongue initials","Hear the difference between b and p, d and t, g and k","Learn the puff-of-air trick"],"blocks":[{"type":"text","text":"Mandarin has 21 initials. Teachers group them by where in the mouth you make them. Let us start with the easy groups: most of these sound almost like English."},{"type":"letters","items":["b","p","m","f"],"title":"Lips: b p m f"},{"type":"text","text":"Made with the lips. m and f are just like English. The trick is **b** versus **p**."},{"type":"letters","items":["d","t","n","l"],"title":"Tongue tip: d t n l"},{"type":"text","text":"Made with the tongue tip behind the top teeth. n and l are just like English. The trick is **d** versus **t**."},{"type":"letters","items":["g","k","h"],"title":"Back of the tongue: g k h"},{"type":"text","text":"Made at the back of the mouth. The trick is **g** versus **k**, and h is a little rougher than English h."},{"type":"rule","name":"The puff-of-air rule","color":"orange","desc":"In Mandarin, b/p, d/t and g/k are not about voice. They are about air: b, d, g have **no** puff; p, t, k have a **strong** puff.","how":"Hold your hand or a tissue in front of your mouth. No movement: b d g. A clear puff: p t k.","examples":[{"t":"爸","tr":"bà"},{"t":"怕","tr":"pà"},{"t":"大","tr":"dà"},{"t":"他","tr":"tā"},{"t":"哥","tr":"gē"},{"t":"可","tr":"kě"}]},{"type":"compare","items":[{"t":"爸","label":"b · no puff","desc":"bà, dad. Soft, like the p in \"spin\"."},{"t":"怕","label":"p · puff","desc":"pà, to be afraid. Like the p in \"pie\"."}],"title":"b or p?"},{"type":"compare","items":[{"t":"肚","label":"d · no puff","desc":"dù, belly. Soft, like the t in \"stop\"."},{"t":"兔","label":"t · puff","desc":"tù, rabbit. Like the t in \"top\"."}],"title":"d or t?"},{"type":"compare","items":[{"t":"哥","label":"g · no puff","desc":"gē, older brother."},{"t":"科","label":"k · puff","desc":"kē, subject (of study)."}],"title":"g or k?"},{"type":"tip","kind":"tip","text":"The h in Mandarin is made further back, with a little friction, a bit like a gentle version of the \"ch\" in Scottish \"loch\". Try {{喝}} hē (to drink) and {{好}} hǎo (good)."},{"type":"tip","kind":"memory","text":"p, t, k = \"puff, tissue, kick\": these three blow the tissue away."},{"type":"examples","items":[{"t":"爸爸","tr":"bàba","mean":"dad"},{"t":"朋友","tr":"péngyou","mean":"friend"},{"t":"妈妈","tr":"māma","mean":"mum"},{"t":"飞机","tr":"fēijī","mean":"plane"},{"t":"弟弟","tr":"dìdi","mean":"younger brother"},{"t":"他","tr":"tā","mean":"he"},{"t":"你","tr":"nǐ","mean":"you"},{"t":"老师","tr":"lǎoshī","mean":"teacher"},{"t":"哥哥","tr":"gēge","mean":"older brother"},{"t":"咖啡","tr":"kāfēi","mean":"coffee"},{"t":"好","tr":"hǎo","mean":"good"}],"title":"Words to try"},{"type":"practice","text":"Read each pair. Feel the puff on the second one.","lines":["爸 怕","大 他","哥 科","饱 跑","弟 替"]},{"type":"quiz","items":[{"q":"Listen. Which initial do you hear?","say":"怕","options":["b","p","m","f"],"answer":1},{"q":"Listen. Which initial do you hear?","say":"大","options":["t","n","l","d"],"answer":3},{"q":"Listen. Which initial do you hear?","say":"可","options":["g","h","d","k"],"answer":3},{"q":"What is the real difference between b and p in Mandarin?","options":["b is louder","p has a puff of air, b does not","p is a vowel","b is always 4th tone"],"answer":1},{"q":"Which group is made with the lips?","options":["d t n l","g k h","b p m f","j q x"],"answer":2},{"q":"Mandarin b sounds most like the English p in...","options":["\"spin\"","\"pie\"","\"phone\"","\"pool\""],"answer":0},{"q":"Which word means \"teacher\"?","options":["哥哥 gēge","咖啡 kāfēi","老师 lǎoshī","弟弟 dìdi"],"answer":2}],"title":"Quick quiz"}]},{"id":"u1-tricky-initials","icon":"q","title":"The Tricky Initials","subtitle":"j q x · z c s · zh ch sh r","minutes":15,"goals":["Say j q x with the tongue tip down","Say z c s like \"ds\", \"ts\", \"s\"","Curl the tongue for zh ch sh r","Say the special \"buzzing\" i"],"blocks":[{"type":"text","text":"These ten initials are where pinyin looks least like English. Do not read them with English habits! Take them slowly, one group at a time."},{"type":"letters","items":["j","q","x"],"title":"Flat tongue, tip down: j q x"},{"type":"text","text":"Put your tongue tip behind your **lower** front teeth, press the middle of the tongue up, and smile. j has no puff, q has a puff, x is a soft hiss."},{"type":"table","head":["Pinyin","Sounds like","Character"],"rows":[["j","j in \"jeep\", tongue tip down","{{鸡}} jī, chicken"],["q","ch in \"cheese\", tongue tip down, puff","{{七}} qī, seven"],["x","sh in \"sheep\" said with a smile","{{西}} xī, west"]]},{"type":"tip","kind":"warn","text":"q is never \"kw\" and x is never \"ks\". {{七}} qī sounds like \"chee\", {{谢谢}} xièxie sounds like \"shyeh-shyeh\"."},{"type":"letters","items":["z","c","s"],"title":"Tongue at the teeth: z c s"},{"type":"table","head":["Pinyin","Sounds like","Character"],"rows":[["z","ds in \"kids\"","{{字}} zì, character"],["c","ts in \"cats\", with a puff","{{菜}} cài, dish"],["s","s in \"sun\"","{{四}} sì, four"]]},{"type":"tip","kind":"warn","text":"c is never \"k\" or \"s\": {{菜}} cài sounds like \"tsai\". And z is not the buzzy z of \"zoo\": it is \"ds\", as in \"kids\"."},{"type":"letters","items":["zh","ch","sh","r"],"title":"Curled tongue: zh ch sh r"},{"type":"text","text":"Curl the tongue tip up and back towards the roof of your mouth. These are a \"curled\" version of English j, ch, sh and r."},{"type":"table","head":["Pinyin","Sounds like","Character"],"rows":[["zh","j in \"judge\", tongue curled","{{知}} zhī, to know"],["ch","ch in \"church\", tongue curled, puff","{{吃}} chī, to eat"],["sh","sh in \"shirt\", tongue curled","{{十}} shí, ten"],["r","r in \"run\" mixed with s in \"pleasure\"","{{日}} rì, sun, day"]]},{"type":"rule","name":"The \"buzzing\" i","color":"purple","desc":"After z c s zh ch sh r, the letter i is **not** \"ee\". Hold the tongue where the initial was and just let the voice buzz on.","how":"Compare 西 xī (\"shee\") with 四 sì (\"sz\") and 十 shí (\"shr\").","examples":[{"t":"字","tr":"zì"},{"t":"四","tr":"sì"},{"t":"知","tr":"zhī"},{"t":"吃","tr":"chī"},{"t":"十","tr":"shí"},{"t":"日","tr":"rì"}]},{"type":"compare","items":[{"t":"西","label":"x · tongue down","desc":"xī, west. Smiling \"shee\"."},{"t":"四","label":"s · teeth","desc":"sì, four. A plain hiss and buzz."},{"t":"十","label":"sh · curled","desc":"shí, ten. Tongue curled back."}],"title":"x, s or sh?"},{"type":"compare","items":[{"t":"七","label":"q · tongue down","desc":"qī, seven."},{"t":"吃","label":"ch · curled","desc":"chī, to eat."},{"t":"词","label":"c · teeth","desc":"cí, word."}],"title":"q, ch or c?"},{"type":"tip","kind":"memory","text":"j q x are \"smiley\" sounds: tongue down, lips smiling. zh ch sh r are \"curly\" sounds: tongue curled up. z c s are \"snake\" sounds: hissing at the teeth."},{"type":"tip","kind":"culture","text":"In southern China and Taiwan many people pronounce zh ch sh like z c s. Learn the standard curled sounds, but do not be surprised to hear both."},{"type":"practice","text":"Read each line, feeling where your tongue is.","lines":["鸡 七 西","字 词 四","知 吃 十 日","七 吃 词","西 四 十"]},{"type":"quiz","items":[{"q":"Listen. Which initial do you hear?","say":"七","options":["q","ch","c","j"],"answer":0},{"q":"Listen. Which initial do you hear?","say":"十","options":["x","s","r","sh"],"answer":3},{"q":"Listen. Which initial do you hear?","say":"菜","options":["z","c","q","ch"],"answer":1},{"q":"Where is the tongue tip for j q x?","options":["Curled back","Down behind the lower teeth","Between the teeth","Touching the lips"],"answer":1},{"q":"Pinyin c sounds like...","options":["k in \"cat\"","s in \"city\"","ch in \"chat\"","ts in \"cats\""],"answer":3},{"q":"In {{四}} sì, the i sounds like...","options":["a buzz, not \"ee\"","ee in \"see\"","i in \"sit\"","eye"],"answer":0},{"q":"Which group needs a curled tongue?","options":["z c s","j q x","zh ch sh r","b p m f"],"answer":2},{"q":"{{谢谢}} xièxie sounds roughly like...","options":["\"shyeh-shyeh\"","\"ksee-ay ksee-ay\"","\"zee-ay zee-ay\"","\"kyeh-kyeh\""],"answer":0}],"title":"Quick quiz"}]},{"id":"u1-finals","icon":"ü","title":"Finals and the ü Sound","subtitle":"Simple, compound and nasal finals","minutes":15,"goals":["Say the six simple vowels, including ü","Glide through compound finals like ao and iao","Tell n from ng"],"blocks":[{"type":"text","text":"Finals are the vowel part of the syllable. There are quite a few, but they are built from just six simple vowels. Learn those first and the rest snap together."},{"type":"letters","items":["a","o","e","i","u","u-umlaut"],"title":"The six simple vowels"},{"type":"table","head":["Pinyin","Sounds like","Character"],"rows":[["a","a in \"father\"","{{啊}} ā"],["o","\"aw\" with round lips","{{哦}} ò"],["e","\"uh\" from the back of the throat","{{饿}} è, hungry"],["i","ee in \"see\"","{{一}} yī, one"],["u","oo in \"food\"","{{五}} wǔ, five"],["ü","\"ee\" with \"oo\" lips","{{鱼}} yú, fish"]]},{"type":"tip","kind":"warn","text":"Pinyin e is **not** English e. {{饿}} è (hungry) sounds like a deep \"uh\". But inside ie, üe and ei, e sounds like the e in \"yes\"."},{"type":"rule","name":"Making ü","color":"purple","desc":"Say \"ee\" and hold your tongue still. Now round your lips tightly as if to whistle. That is ü!","how":"Smile-and-kiss: tongue says \"ee\", lips say \"oo\".","examples":[{"t":"鱼","tr":"yú"},{"t":"女","tr":"nǚ"},{"t":"绿","tr":"lǜ"},{"t":"去","tr":"qù"}]},{"type":"compare","items":[{"t":"路","label":"u · lù","desc":"road. Lips round, tongue back."},{"t":"绿","label":"ü · lǜ","desc":"green. Lips round, tongue forward as for \"ee\"."}],"title":"u or ü?"},{"type":"letters","items":["er"],"title":"The curly er"},{"type":"text","text":"{{二}} èr (two) is a special final: say \"uh\" while curling the tongue tip back, like American \"are\"."},{"type":"letters","items":["ai","ei","ao","ou","ia","ie","iao","iu","ua","uo","uai","ui","u-umlaut-e"],"title":"Compound finals: glide from vowel to vowel"},{"type":"table","head":["Final","Sounds like","Character"],"rows":[["ai","eye","{{爱}} ài, love"],["ei","ay in \"say\"","{{飞}} fēi, to fly"],["ao","ow in \"cow\"","{{好}} hǎo, good"],["ou","o in \"go\"","{{狗}} gǒu, dog"],["ie","ye in \"yes\"","{{也}} yě, also"],["iao","yow","{{小}} xiǎo, small"],["iu","yo","{{六}} liù, six"],["uo","waw","{{多}} duō, many"],["ui","way","{{水}} shuǐ, water"]]},{"type":"letters","items":["an","en","ang","eng","ong","in","ing","ian","iang","iong","uan","un","uang","u-umlaut-an","u-umlaut-n"],"title":"Nasal finals: ending in n or ng"},{"type":"compare","items":[{"t":"饭","label":"an · fàn","desc":"meal. Tongue tip touches behind the top teeth for n."},{"t":"放","label":"ang · fàng","desc":"to put. Back of the tongue rises for ng, like \"sing\"."}],"title":"n or ng?"},{"type":"compare","items":[{"t":"心","label":"in · xīn","desc":"heart. Short, clean n."},{"t":"星","label":"ing · xīng","desc":"star. Ends with ng."}]},{"type":"tip","kind":"warn","text":"ian sounds like \"yen\", not \"yan\". {{天}} tiān (sky) sounds like \"tyen\", and {{钱}} qián (money) like \"chyen\"."},{"type":"tip","kind":"memory","text":"n is \"front door\" (tongue tip at the front), ng is \"back door\" (tongue at the back, as in \"sing\")."},{"type":"practice","text":"Read across each line slowly, gliding smoothly.","lines":["啊 哦 饿 一 五 鱼","爱 飞 好 狗","也 小 六 多 水","饭 放 心 星","天 钱 远 云","路 绿"]},{"type":"quiz","items":[{"q":"Listen. Which final do you hear?","say":"鱼","options":["u","i","ü","e"],"answer":2},{"q":"Listen. Which final do you hear?","say":"放","options":["an","ang","en","eng"],"answer":1},{"q":"How do you make ü?","options":["Say \"oo\" with a smile","Say \"uh\" with the tongue curled","Say \"ah\" through the nose","Say \"ee\" with rounded lips"],"answer":3},{"q":"The final ian sounds like...","options":["\"yan\"","\"yawn\"","\"eye-an\"","\"yen\""],"answer":3},{"q":"Pinyin ao rhymes with...","options":["\"go\"","\"cow\"","\"say\"","\"see\""],"answer":1},{"q":"Which word means \"green\"?","options":["lù","liù","lǜ","lè"],"answer":2},{"q":"Which pair differs by n and ng?","options":["心 xīn and 星 xīng","路 lù and 绿 lǜ","爱 ài and 飞 fēi","五 wǔ and 鱼 yú"],"answer":0}],"title":"Quick quiz"}]},{"id":"u1-tone-marks","icon":"´","title":"Where the Tone Mark Goes","subtitle":"One simple order: a, then o or e, then the rest","minutes":8,"goals":["Put tone marks on the right vowel","Handle iu and ui correctly","Write ü with tone marks"],"blocks":[{"type":"text","text":"A tone mark always sits on a vowel. When a syllable has two or three vowels, which one gets it? There is a simple rule of priority."},{"type":"rule","name":"Tone mark priority","color":"green","desc":"Look for **a** first. No a? Look for **o** or **e** (they never appear together except in ou, and there o wins). Neither? Put it on the **last** vowel.","how":"a  →  o / e  →  last vowel","examples":[{"t":"好","tr":"hǎo"},{"t":"谢","tr":"xiè"},{"t":"多","tr":"duō"},{"t":"狗","tr":"gǒu"},{"t":"对","tr":"duì"},{"t":"六","tr":"liù"}]},{"type":"steps","items":[{"title":"Is there an a?","t":"好","tr":"hǎo","mean":"good","desc":"Yes: mark the a. Also kuài, tiān, xiǎo."},{"title":"No a. Is there an o or e?","t":"谢","tr":"xiè","mean":"to thank","desc":"Mark it: xiè, duō, hēi, gǒu, yuè."},{"title":"Neither? Mark the last vowel.","t":"六","tr":"liù","mean":"six","desc":"iu marks the u, ui marks the i: liù, duì, shuǐ."}],"title":"Three questions"},{"type":"tip","kind":"memory","text":"\"**A** gets it first; **O** and **E** take turns; otherwise the **last** one wins.\""},{"type":"table","head":["Final","Marked vowel","Example"],"rows":[["ao","a","{{好}} hǎo"],["ia","a","{{家}} jiā"],["ian","a","{{天}} tiān"],["ou","o","{{狗}} gǒu"],["uo","o","{{国}} guó"],["ei","e","{{黑}} hēi"],["üe","e","{{学}} xué"],["iu","u (last)","{{九}} jiǔ"],["ui","i (last)","{{水}} shuǐ"]]},{"type":"rule","name":"The dot on i","color":"gray","desc":"When i carries a tone mark, the mark replaces the dot.","examples":[{"t":"一","tr":"yī"},{"t":"你","tr":"nǐ"},{"t":"米","tr":"mǐ"},{"t":"是","tr":"shì"}]},{"type":"rule","name":"Marks on ü","color":"gray","desc":"ü keeps its two dots and the tone mark goes on top of them.","examples":[{"t":"女","tr":"nǚ"},{"t":"绿","tr":"lǜ"},{"t":"旅","tr":"lǚ"}]},{"type":"tip","kind":"tip","text":"On a phone or computer you can usually type ü as \"v\" in pinyin input: \"nv\" gives 女 nǚ."},{"type":"practice","text":"Say each word, then say which vowel carries the mark.","lines":["好","谢谢","多","狗","六","对","水","学"]},{"type":"quiz","items":[{"q":"Which spelling is correct for \"good\"?","options":["haǒ","hǎǒ","hǎo","hāo"],"answer":2},{"q":"Which spelling is correct for \"six\"?","options":["liù","lìu","líu","liú"],"answer":0},{"q":"Which spelling is correct for \"water\"?","options":["shǔi","shùi","shúi","shuǐ"],"answer":3},{"q":"In xiè, the mark is on e because...","options":["e is the first vowel","there is no a, so e gets it","i cannot take marks","it is a 4th tone"],"answer":1},{"q":"In ou, which vowel gets the mark?","options":["u","o","neither","both"],"answer":1},{"q":"What happens to the dot on i under a tone mark?","options":["It moves to the side","It becomes two dots","It stays under the mark","The mark replaces it"],"answer":3}],"title":"Quick quiz"}]},{"id":"u1-tone-changes","icon":"变","title":"Tone Changes","subtitle":"3rd-tone pairs, 不 bù and 一 yī","minutes":12,"goals":["Change 3rd + 3rd into 2nd + 3rd","Use the low \"half-3rd\" tone","Know when 不 and 一 change tone"],"blocks":[{"type":"text","text":"Tones sometimes change when syllables sit next to each other. This is called **tone sandhi**. There are only three common changes, and they make speech flow smoothly."},{"type":"rule","name":"Rule 1: two 3rd tones in a row","color":"green","desc":"When a 3rd tone comes before another 3rd tone, the first one is said as a **2nd tone**. Pinyin still writes the original marks.","how":"3 + 3  →  2 + 3","examples":[{"t":"你好","tr":"nǐ hǎo → ní hǎo"},{"t":"很好","tr":"hěn hǎo → hén hǎo"},{"t":"水果","tr":"shuǐguǒ → shuíguǒ"},{"t":"可以","tr":"kěyǐ → kéyǐ"}]},{"type":"tip","kind":"memory","text":"Two valleys in a row are hard to walk, so the first one climbs into a hill: ní hǎo!"},{"type":"rule","name":"Rule 2: the half-3rd tone","color":"blue","desc":"Before a 1st, 2nd, 4th or neutral tone, a 3rd tone is usually just **low**, without rising back up.","how":"Say only the low part of the dip.","examples":[{"t":"老师","tr":"lǎoshī"},{"t":"很忙","tr":"hěn máng"},{"t":"好看","tr":"hǎokàn"},{"t":"你们","tr":"nǐmen"}]},{"type":"rule","name":"Rule 3: 不 bù","color":"red","desc":"{{不}} (not) is normally bù, 4th tone. Before another **4th tone** it becomes **bú**, 2nd tone.","how":"bù + 4th  →  bú + 4th","examples":[{"t":"不是","tr":"bú shì","hl":"不"},{"t":"不对","tr":"bú duì","hl":"不"},{"t":"不要","tr":"bú yào","hl":"不"},{"t":"不好","tr":"bù hǎo","hl":"不"},{"t":"不来","tr":"bù lái","hl":"不"},{"t":"不吃","tr":"bù chī","hl":"不"}]},{"type":"table","head":["一 is followed by...","Say 一 as","Examples"],"rows":[["nothing (alone, counting, at the end)","yī (1st)","{{一}} yī, {{十一}} shíyī, {{第一}} dì-yī"],["a 4th tone","yí (2nd)","{{一个}} yí gè, {{一样}} yíyàng"],["a 1st, 2nd or 3rd tone","yì (4th)","{{一天}} yì tiān, {{一年}} yì nián, {{一起}} yìqǐ"]],"title":"Rule 4: 一 yī"},{"type":"tip","kind":"tip","text":"Dates and order numbers keep the plain yī: {{一月}} yīyuè (January), {{第一天}} dì-yī tiān (the first day). Do not change it there."},{"type":"tip","kind":"tip","text":"Many textbooks write the changed tones for 不 and 一 (bú shì, yí gè) to help learners, but dictionaries list the original bù and yī. For 3rd + 3rd, pinyin normally keeps the original marks: nǐ hǎo."},{"type":"compare","items":[{"t":"不去","label":"bú qù","desc":"not go: 去 is 4th tone, so 不 rises."},{"t":"不忙","label":"bù máng","desc":"not busy: 忙 is 2nd tone, so 不 stays bù."}],"title":"不: change or not?"},{"type":"compare","items":[{"t":"一共","label":"yígòng","desc":"altogether: 共 is 4th tone."},{"t":"一点儿","label":"yìdiǎnr","desc":"a little: 点 is 3rd tone."}],"title":"一: yí or yì?"},{"type":"practice","text":"Read with the tone changes. Listen and copy the flow.","lines":["你好","很好","水果","不是","不好","一个","一天","一起"]},{"type":"quiz","items":[{"q":"How do you actually say {{你好}}?","options":["ní hǎo","nǐ hǎo with two dips","nì hǎo","nī hāo"],"answer":0},{"q":"What happens to 3rd + 3rd?","options":["Both become 1st tone","The second becomes 4th","The first becomes 2nd tone","Nothing changes"],"answer":2},{"q":"How is {{不是}} said?","options":["bú shì","bù shì","bǔ shì","bū shì"],"answer":0},{"q":"How is {{不好}} said?","options":["bú hǎo","bǔ hǎo","bù hǎo","bū hǎo"],"answer":2},{"q":"How is {{一个}} said?","options":["yī gè","yí gè","yì gè","yǐ gè"],"answer":1},{"q":"How is {{一天}} said?","options":["yí tiān","yī tiān","yǐ tiān","yì tiān"],"answer":3},{"q":"In {{第一}} (first), 一 is said...","options":["yí","yì","yǐ","yī"],"answer":3}],"title":"Quick quiz"}]},{"id":"u1-spelling","icon":"y","title":"Pinyin Spelling Rules","subtitle":"y and w, ü after j q x, and short forms","minutes":12,"goals":["Spell syllables that start with i, u or ü","Know when ü is written without dots","Read iu, ui and un correctly","Use the apostrophe"],"blocks":[{"type":"text","text":"Pinyin has a few spelling habits. They do not change the sound: they just make syllables easier to see on the page. Once you know them, reading gets much easier."},{"type":"rule","name":"Starting with i → y","color":"blue","desc":"When a syllable has no initial and starts with i, write y. If i is the only vowel (or before n / ng), write yi.","examples":[{"t":"一","tr":"i → yī"},{"t":"也","tr":"ie → yě"},{"t":"要","tr":"iao → yào"},{"t":"有","tr":"iou → yǒu"},{"t":"烟","tr":"ian → yān"},{"t":"英","tr":"ing → yīng"}]},{"type":"rule","name":"Starting with u → w","color":"green","desc":"When a syllable has no initial and starts with u, write w. If u is the only vowel, write wu.","examples":[{"t":"五","tr":"u → wǔ"},{"t":"我","tr":"uo → wǒ"},{"t":"外","tr":"uai → wài"},{"t":"为","tr":"uei → wèi"},{"t":"问","tr":"uen → wèn"},{"t":"王","tr":"uang → wáng"}]},{"type":"rule","name":"Starting with ü → yu","color":"purple","desc":"When a syllable starts with ü, write yu, and drop the dots.","examples":[{"t":"鱼","tr":"ü → yú"},{"t":"月","tr":"üe → yuè"},{"t":"远","tr":"üan → yuǎn"},{"t":"云","tr":"ün → yún"}]},{"type":"rule","name":"ü after j q x: no dots","color":"orange","desc":"j, q, x (and y) never go with u, so after them ü is written plain u. It still **sounds** like ü!","how":"ju, qu, xu, yu = ü sounds.","examples":[{"t":"去","tr":"qù"},{"t":"句","tr":"jù"},{"t":"学","tr":"xué"},{"t":"鱼","tr":"yú"}]},{"type":"rule","name":"ü after n and l: keep the dots","color":"red","desc":"n and l can go with both u and ü, so here the dots matter.","examples":[{"t":"女","tr":"nǚ"},{"t":"努","tr":"nǔ"},{"t":"绿","tr":"lǜ"},{"t":"路","tr":"lù"}]},{"type":"table","head":["Full form","Written after an initial","Example"],"rows":[["iou","iu","{{六}} liù, {{九}} jiǔ"],["uei","ui","{{对}} duì, {{水}} shuǐ"],["uen","un","{{春}} chūn, {{困}} kùn"]],"title":"Short forms"},{"type":"tip","kind":"tip","text":"The hidden vowel is still there in the sound: {{六}} liù is really \"lyoh\", {{对}} duì is \"dway\"."},{"type":"rule","name":"The apostrophe","color":"gray","desc":"When a syllable starting with a, o or e follows another syllable, use an apostrophe so the break is clear.","how":"Xī'ān (two syllables, a city) is not xiān (one syllable, first).","examples":[{"t":"西安","tr":"Xī'ān"},{"t":"先","tr":"xiān"},{"t":"天安门","tr":"Tiān'ānmén"}]},{"type":"tip","kind":"memory","text":"j, q, x are \"too shy\" to sit next to plain u, so any u you see after them is really ü wearing a disguise."},{"type":"practice","text":"Read each word. Think: what is the full form behind the spelling?","lines":["一 也 要 有","五 我 外 为","鱼 月 远 云","去 学 女 路","西安 先"]},{"type":"quiz","items":[{"q":"How do you write the syllable i on its own with the 1st tone?","options":["ī","yī","yiī","wī"],"answer":1},{"q":"How do you write the syllable u with the 3rd tone?","options":["ǔ","yǔ","wǔ","hǔ"],"answer":2},{"q":"In {{去}} qù, the u sounds like...","options":["ü","oo in \"food\"","u in \"cup\"","yoo"],"answer":0},{"q":"Why does {{女}} nǚ keep its dots?","options":["Because it is 3rd tone","Because n is a lip sound","Because nu and nü are both possible","It is a spelling mistake"],"answer":2},{"q":"iu is short for...","options":["iou","ieu","iau","yuu"],"answer":0},{"q":"What does the apostrophe in Xī'ān show?","options":["A neutral tone","A missing letter","A foreign word","Where one syllable ends and the next begins"],"answer":3},{"q":"The final uei with no initial is written...","options":["ui","wei","wui","uei"],"answer":1}],"title":"Quick quiz"}]},{"id":"u1-reading-lab","icon":"读","title":"Pinyin Reading Lab","subtitle":"Put it all together with real words and sentences","minutes":15,"goals":["Read everyday words from pinyin","Read short sentences with tone changes","Write pinyin you hear"],"blocks":[{"type":"text","text":"Time to use everything: initials, finals, tones, spelling rules and tone changes. Read each item, tap to check, and repeat until it feels natural."},{"type":"vocab","items":[{"t":"你好","tr":"nǐ hǎo","mean":"hello","example":{"t":"你好！","tr":"nǐ hǎo!","mean":"Hello!"}},{"t":"谢谢","tr":"xièxie","mean":"thank you"},{"t":"再见","tr":"zàijiàn","mean":"goodbye"},{"t":"对不起","tr":"duìbuqǐ","mean":"sorry"},{"t":"没关系","tr":"méi guānxi","mean":"it does not matter"},{"t":"老师","tr":"lǎoshī","mean":"teacher"},{"t":"学生","tr":"xuésheng","mean":"student"},{"t":"朋友","tr":"péngyou","mean":"friend"},{"t":"中国","tr":"Zhōngguó","mean":"China"},{"t":"中文","tr":"Zhōngwén","mean":"Chinese (language)"}],"title":"Word bank"},{"type":"tip","kind":"tip","text":"Some words end in a neutral tone: xièxie, péngyou, xuésheng. Say the last syllable lightly and quickly."},{"type":"sentence","t":"你好吗？","tr":"nǐ hǎo ma?","mean":"How are you?","words":[{"t":"你","mean":"you"},{"t":"好","mean":"good, well"},{"t":"吗","mean":"(question word)"}],"note":"你好 is said ní hǎo (3rd + 3rd). 吗 is a light neutral tone."},{"type":"sentence","t":"我很好。","tr":"wǒ hěn hǎo.","mean":"I am very well.","words":[{"t":"我","mean":"I"},{"t":"很","mean":"very"},{"t":"好","mean":"good, well"}],"note":"Three 3rd tones! Most people say wǒ hén hǎo or wó hén hǎo."},{"type":"sentence","t":"我不是老师。","tr":"wǒ bú shì lǎoshī.","mean":"I am not a teacher.","words":[{"t":"我","mean":"I"},{"t":"不","mean":"not"},{"t":"是","mean":"am, is, are"},{"t":"老师","mean":"teacher"}],"note":"不 becomes bú before the 4th-tone 是."},{"type":"sentence","t":"我学中文。","tr":"wǒ xué Zhōngwén.","mean":"I study Chinese.","words":[{"t":"我","mean":"I"},{"t":"学","mean":"study"},{"t":"中文","mean":"Chinese"}]},{"type":"dialogue","lines":[{"who":"Lín","t":"你好！","tr":"nǐ hǎo!","mean":"Hello!"},{"who":"Amy","t":"你好！你好吗？","tr":"nǐ hǎo! nǐ hǎo ma?","mean":"Hello! How are you?"},{"who":"Lín","t":"我很好，谢谢。","tr":"wǒ hěn hǎo, xièxie.","mean":"I am very well, thanks."},{"who":"Amy","t":"再见！","tr":"zàijiàn!","mean":"Goodbye!"},{"who":"Lín","t":"再见！","tr":"zàijiàn!","mean":"Goodbye!"}],"title":"A first chat"},{"type":"tip","kind":"culture","text":"Friends usually do not ask 你好吗 every day. A friendly 你好 or, among friends, 嗨 hāi (hi) is more common. 你好吗 is still a perfect first phrase to learn."},{"type":"practice","text":"Read each line aloud with good tones.","lines":["你好","谢谢","再见","对不起","没关系","你好吗？","我很好。","我不是老师。","我学中文。"]},{"type":"dictation","items":[{"t":"你好","tr":"nǐ hǎo","mean":"hello"},{"t":"谢谢","tr":"xièxie","mean":"thank you"},{"t":"老师","tr":"lǎoshī","mean":"teacher"},{"t":"朋友","tr":"péngyou","mean":"friend"},{"t":"中国","tr":"Zhōngguó","mean":"China"},{"t":"再见","tr":"zàijiàn","mean":"goodbye"}],"title":"Listen and write the pinyin"},{"type":"selfcheck","items":["I can name the initial, final and tone of a syllable.","I can say the four tones and the neutral tone.","I can say j q x, z c s and zh ch sh r.","I can make the ü sound.","I know where tone marks go.","I can use the tone changes for 3rd + 3rd, 不 and 一."]},{"type":"quiz","items":[{"q":"Listen. Which word is it?","say":"谢谢","options":["zàijiàn","xièxie","nǐ hǎo","duìbuqǐ"],"answer":1},{"q":"Listen. Which word is it?","say":"朋友","options":["lǎoshī","xuésheng","Zhōngguó","péngyou"],"answer":3},{"q":"What does {{对不起}} mean?","options":["sorry","thank you","goodbye","hello"],"answer":0},{"q":"How do you say \"I am not a teacher\"?","options":["wǒ shì lǎoshī","nǐ bú shì lǎoshī","wǒ bú shì lǎoshī","wǒ hěn hǎo"],"answer":2},{"q":"What does {{吗}} do at the end of a sentence?","options":["It makes a yes/no question","It means \"very\"","It means \"mother\"","It makes it polite"],"answer":0},{"q":"{{中文}} means...","options":["China","teacher","Chinese (language)","student"],"answer":2}],"title":"Quick quiz"}]}]});
LC.units.push({"id":"characters","order":2,"icon":"字","color":"cyan","title":"Characters & Writing","subtitle":"Strokes, stroke order, radicals and your first 17 characters","lessons":[{"id":"u2-what-are-characters","icon":"字","title":"What Are Chinese Characters?","subtitle":"Pictures, ideas, and meaning + sound","minutes":10,"goals":["Know what a character is","Recognise pictographs and ideographs","Spot the meaning part and the sound part"],"blocks":[{"type":"text","text":"Chinese is not written with an alphabet. Each **character** (汉字 hànzì) stands for one syllable and carries a meaning. Some started life as little pictures, but most are clever combinations of parts."},{"type":"tip","kind":"fun","text":"The oldest known Chinese writing was carved on bones and turtle shells more than 3,000 years ago. Many characters you will learn today come from those ancient shapes."},{"type":"text","text":"A pictograph is a simplified drawing of a thing. Over centuries the curves became straight strokes, but you can still see the picture.","title":"Type 1: pictographs"},{"type":"table","head":["Character","Pinyin","Meaning","The picture"],"rows":[["{{人}}","rén","person","a person walking, two legs striding"],["{{日}}","rì","sun, day","once a circle with a dot in the middle"],["{{月}}","yuè","moon, month","a crescent moon"],["{{山}}","shān","mountain","three peaks"],["{{水}}","shuǐ","water","a stream with splashes"],["{{火}}","huǒ","fire","flames rising"],["{{木}}","mù","tree, wood","branches above, roots below"],["{{口}}","kǒu","mouth","an open mouth"]]},{"type":"text","text":"Ideas that are hard to draw are shown with simple signs.","title":"Type 2: simple ideographs"},{"type":"examples","items":[{"t":"一 二 三","tr":"yī èr sān","mean":"one, two, three","note":"one, two and three lines"},{"t":"上","tr":"shàng","mean":"up, above","note":"a mark above a line"},{"t":"下","tr":"xià","mean":"down, below","note":"a mark below a line"},{"t":"本","tr":"běn","mean":"root, origin","note":"a tree 木 with a mark at its base"}]},{"type":"text","text":"Two or more meaningful parts join to make a new idea.","title":"Type 3: compound ideographs"},{"type":"examples","items":[{"t":"休","tr":"xiū","mean":"to rest","note":"a person 亻 leaning on a tree 木"},{"t":"明","tr":"míng","mean":"bright","note":"sun 日 + moon 月"},{"t":"林","tr":"lín","mean":"woods","note":"two trees"},{"t":"森","tr":"sēn","mean":"forest","note":"three trees: lots of trees!"},{"t":"好","tr":"hǎo","mean":"good","note":"woman 女 + child 子"}]},{"type":"rule","name":"Type 4: meaning part + sound part","color":"purple","desc":"Most characters (roughly 80%) combine a **meaning part** (often called the radical) with a **sound part** that hints at the pronunciation.","how":"妈 = 女 (woman: the meaning) + 马 mǎ (horse: just for the sound). So 妈 is a woman who sounds like \"ma\": mum!","examples":[{"t":"妈","tr":"mā"},{"t":"吗","tr":"ma"},{"t":"骂","tr":"mà"}]},{"type":"tip","kind":"memory","text":"When you meet a new character, ask two questions: \"What is the meaning part?\" and \"What is the sound part?\" You will remember it twice as fast."},{"type":"tip","kind":"tip","text":"About 2,500 common characters cover around 98% of everyday written Chinese. You do not need tens of thousands!"},{"type":"practice","text":"Tap each character and say it. Can you see the picture or the idea?","lines":["人","日","月","山","水","火","木","口","休","明","林","森","好","妈"]},{"type":"quiz","items":[{"q":"A Chinese character stands for...","options":["one letter","a whole sentence","one syllable with a meaning","a sound with no meaning"],"answer":2},{"q":"Which character began as a picture of a mountain?","options":["山","水","日","人"],"answer":0},{"q":"{{明}} (bright) is made of...","options":["tree + tree","person + tree","woman + child","sun + moon"],"answer":3},{"q":"In {{妈}}, which part gives the sound?","options":["女","马","both","neither"],"answer":1},{"q":"Most Chinese characters are made of...","options":["pure pictures","a meaning part + a sound part","letters","numbers"],"answer":1},{"q":"{{休}} means \"to rest\" because it shows...","options":["three trees","the sun over a mountain","a mouth and water","a person by a tree"],"answer":3}],"title":"Quick quiz"}]},{"id":"u2-strokes","icon":"丿","title":"The Basic Strokes","subtitle":"Eight strokes build every character","minutes":10,"goals":["Name the eight basic strokes","Write each stroke in the right direction","Spot strokes inside characters"],"blocks":[{"type":"text","text":"Every character is built from a small set of **strokes**: a stroke is one movement of the pen, from touching the paper to lifting it. Learn these eight and you can write anything."},{"type":"table","head":["Stroke","Name","How to write it","Found in"],"rows":[["一","héng · horizontal","left to right, slightly rising","{{一}} {{二}} {{十}}"],["丨","shù · vertical","top to bottom, straight down","{{十}} {{中}}"],["丿","piě · left-falling","from top right sweeping down to the left","{{人}} {{八}}"],["㇏","nà · right-falling","from top left down to the right, ending in a flat tail","{{人}} {{大}}"],["丶","diǎn · dot","a short press, down and to the right","{{六}} {{小}}"],["㇀","tí · rising","from lower left flicking up to the right","{{打}} {{汉}}"],["㇕","zhé · turn","change direction without lifting the pen","{{口}} {{日}}"],["亅","gōu · hook","a quick flick at the end of a stroke","{{小}} {{子}}"]],"title":"The eight basic strokes"},{"type":"vocab","items":[{"t":"横","tr":"héng","mean":"horizontal stroke"},{"t":"竖","tr":"shù","mean":"vertical stroke"},{"t":"撇","tr":"piě","mean":"left-falling stroke"},{"t":"捺","tr":"nà","mean":"right-falling stroke"},{"t":"点","tr":"diǎn","mean":"dot"},{"t":"提","tr":"tí","mean":"rising stroke"},{"t":"折","tr":"zhé","mean":"turning stroke"},{"t":"钩","tr":"gōu","mean":"hook"}],"title":"Stroke names"},{"type":"rule","name":"Strokes have a direction","color":"red","desc":"Horizontals go left → right. Verticals go top → bottom. A turn (折) is one single stroke: do not lift the pen at the corner.","how":"The top and right side of 口 are ONE stroke (横折).","examples":[{"t":"口","tr":"kǒu"},{"t":"日","tr":"rì"}]},{"type":"tip","kind":"tip","text":"Strokes combine: a horizontal that turns down is 横折 héngzhé; a vertical with a hook is 竖钩 shùgōu. You will see these names in the stroke-order steps."},{"type":"howto","char":"八","name":"bā · eight","steps":["Stroke 1: 撇, a stroke from the top sweeping down to the left.","Stroke 2: 捺, a separate stroke from the top sweeping down to the right."],"tip":"Two strokes parting like a gate opening: 八 means eight, and it is a lucky number in China!"},{"type":"howto","char":"六","name":"liù · six","steps":["Stroke 1: 点, a dot at the top.","Stroke 2: 横, a long horizontal.","Stroke 3: 撇, a short stroke down to the left.","Stroke 4: 点, a dot on the lower right."],"tip":"A little person with a hat (the dot) and legs apart."},{"type":"tip","kind":"fun","text":"Calligraphers practise with {{永}} yǒng (forever), because this one character contains nearly all the basic strokes. It is called \"the eight principles of 永\"."},{"type":"tip","kind":"memory","text":"Remember the eight with a story: \"Line (横), pole (竖), slide left (撇), slide right (捺), drop (点), flick up (提), bend (折), hook (钩).\""},{"type":"write","level":"letter","items":["一","八","六","十"],"note":"Trace each stroke slowly. Say its name as you write it."},{"type":"quiz","items":[{"q":"Which way is a horizontal stroke (横) written?","options":["Left to right","Right to left","Bottom to top","Either way"],"answer":0},{"q":"Which stroke sweeps down to the left?","options":["捺 nà","提 tí","撇 piě","点 diǎn"],"answer":2},{"q":"Which stroke flicks up to the right?","options":["提 tí","竖 shù","撇 piě","横 héng"],"answer":0},{"q":"How many strokes make the top and right side of {{口}}?","options":["Two","Three","One","Four"],"answer":2},{"q":"What is a stroke?","options":["One complete character","One pen movement before lifting","A radical","A tone mark"],"answer":1},{"q":"{{八}} is written with...","options":["捺 then 撇","横 then 竖","two dots","撇 then 捺"],"answer":3}],"title":"Quick quiz"}]},{"id":"u2-stroke-order","icon":"顺","title":"Stroke-Order Rules","subtitle":"Seven rules that tell you which stroke comes first","minutes":12,"goals":["Learn the seven main stroke-order rules","Apply them to new characters","Know the common exceptions"],"blocks":[{"type":"text","text":"Chinese people write strokes in a fixed order. It is not just tradition: the right order makes characters faster to write, better balanced, and easier to read in handwriting. A handful of rules covers almost everything."},{"type":"rule","name":"1. Horizontal before vertical","color":"blue","desc":"When a horizontal and a vertical cross, write the horizontal first.","how":"先横后竖 xiān héng hòu shù","examples":[{"t":"十","tr":"shí"},{"t":"干","tr":"gàn"}]},{"type":"rule","name":"2. Left-falling before right-falling","color":"blue","desc":"When 撇 and 捺 meet, write 撇 (down-left) first.","how":"先撇后捺 xiān piě hòu nà","examples":[{"t":"人","tr":"rén"},{"t":"八","tr":"bā"}]},{"type":"rule","name":"3. Top to bottom","color":"green","desc":"Write the upper strokes or parts before the lower ones.","how":"从上到下 cóng shàng dào xià","examples":[{"t":"三","tr":"sān"},{"t":"字","tr":"zì"}]},{"type":"rule","name":"4. Left to right","color":"green","desc":"Write the left strokes or parts before the right ones.","how":"从左到右 cóng zuǒ dào yòu","examples":[{"t":"川","tr":"chuān"},{"t":"林","tr":"lín"}]},{"type":"rule","name":"5. Outside before inside","color":"orange","desc":"Write the frame first, then what is inside it.","how":"从外到内 cóng wài dào nèi","examples":[{"t":"月","tr":"yuè"},{"t":"同","tr":"tóng"}]},{"type":"rule","name":"6. Inside before closing the box","color":"orange","desc":"For a fully closed box, write the left side and top first, then the inside, and close the bottom last.","how":"先里头后封口 xiān lǐtou hòu fēngkǒu","examples":[{"t":"日","tr":"rì"},{"t":"回","tr":"huí"},{"t":"国","tr":"guó"}]},{"type":"rule","name":"7. Middle before the sides","color":"purple","desc":"When a character has a strong middle stroke with small parts on both sides, write the middle first.","how":"先中间后两边 xiān zhōngjiān hòu liǎngbiān","examples":[{"t":"小","tr":"xiǎo"},{"t":"水","tr":"shuǐ"}]},{"type":"tip","kind":"memory","text":"A short chant: \"Across, then down. Left slide, then right. Top, then bottom. Left, then right. Outside, then inside, then shut the door. Middle, then the wings.\""},{"type":"howto","char":"回","name":"huí · to return","steps":["Stroke 1: 竖, the left side of the big box.","Stroke 2: 横折, the top and right side of the big box in one stroke.","Strokes 3–5: the small box inside: left side, top-and-right (横折), then its bottom line.","Stroke 6: 横, close the big box at the bottom. Total: 6 strokes."],"tip":"A box inside a box: you go \"back\" inside before you shut the door."},{"type":"tip","kind":"warn","text":"Some exceptions: a dot at the top right often comes last, as in {{书}} shū (book). And the \"walking\" part 辶 in {{这}} zhè (this) and {{进}} jìn (to enter) is written after the part it holds.","title":"Exceptions"},{"type":"tip","kind":"tip","text":"On the website, tap a character to watch its stroke order animate, then try the stroke-by-stroke writing quiz."},{"type":"practice","text":"Say which rule each character follows, then write it in the air.","lines":["十","人","三","川","月","日","回","小"]},{"type":"quiz","items":[{"q":"In {{十}}, which stroke comes first?","options":["The vertical","Either","Both together","The horizontal"],"answer":3},{"q":"In {{人}}, which stroke comes first?","options":["捺 (down-right)","撇 (down-left)","Either","A dot"],"answer":1},{"q":"In {{日}}, when is the bottom line written?","options":["First","Second","Last","Third"],"answer":2},{"q":"In {{小}}, which stroke comes first?","options":["The middle hook","The left dot","The right dot","Any of them"],"answer":0},{"q":"Which rule fits {{林}} (two trees side by side)?","options":["Inside before closing","Middle before sides","Left to right","Bottom to top"],"answer":2},{"q":"Why does stroke order matter?","options":["Faster, better-balanced, readable writing","It changes the meaning","It changes the tone","It is only for exams"],"answer":0},{"q":"How many strokes does {{回}} have?","options":["4","5","8","6"],"answer":3}],"title":"Quick quiz"}]},{"id":"u2-first-characters-1","icon":"一","title":"First Characters: Numbers, People, Sun and Moon","subtitle":"一 二 三 十 人 口 日 月 大","minutes":18,"goals":["Write nine basic characters in the correct stroke order","Remember each one with a picture","Read simple words made from them"],"blocks":[{"type":"text","text":"Now the fun part: writing real characters! Each one comes with its stroke order and a memory trick. Write each one several times, saying the strokes aloud."},{"type":"howto","char":"一","name":"yī · one","steps":["1 stroke: 横, from left to right.","Press at the start, move steadily, and lift gently at the end."],"tip":"One line means one. The easiest character there is!"},{"type":"howto","char":"二","name":"èr · two","steps":["Stroke 1: a short 横 on top.","Stroke 2: a longer 横 underneath."],"tip":"Two lines, two. The bottom line is longer, like a shelf holding the top one."},{"type":"howto","char":"三","name":"sān · three","steps":["Stroke 1: a medium 横 on top.","Stroke 2: a short 横 in the middle.","Stroke 3: the longest 横 at the bottom."],"tip":"Three lines, three. The middle one is the shortest, the bottom one the longest."},{"type":"howto","char":"十","name":"shí · ten","steps":["Stroke 1: 横, from left to right.","Stroke 2: 竖, from top to bottom, crossing the middle of the 横."],"tip":"Looks like a plus sign: hold up both hands and add them up: ten!"},{"type":"howto","char":"人","name":"rén · person","steps":["Stroke 1: 撇, start at the top and sweep down to the left.","Stroke 2: 捺, start on the 撇 just below its top and sweep down to the right."],"tip":"A person walking: two legs striding along."},{"type":"howto","char":"口","name":"kǒu · mouth","steps":["Stroke 1: 竖, the left side, top to bottom.","Stroke 2: 横折, across the top and down the right side in one stroke.","Stroke 3: 横, the bottom line closes the box."],"tip":"A wide-open mouth saying \"Oh!\". Make it a little narrower at the bottom."},{"type":"howto","char":"日","name":"rì · sun, day","steps":["Stroke 1: 竖, the left side.","Stroke 2: 横折, the top and right side in one stroke.","Stroke 3: 横, the middle line (inside first!).","Stroke 4: 横, the bottom line closes the box."],"tip":"A window with the sun shining through. It is taller than it is wide."},{"type":"howto","char":"月","name":"yuè · moon, month","steps":["Stroke 1: 竖撇, down the left side, curving left at the bottom.","Stroke 2: 横折钩, across the top and down the right side, ending in a small hook to the left.","Stroke 3: 横, the upper line inside.","Stroke 4: 横, the lower line inside."],"tip":"A tall crescent moon with two clouds drifting across it. The bottom stays open."},{"type":"howto","char":"大","name":"dà · big","steps":["Stroke 1: 横, a long horizontal.","Stroke 2: 撇, from above the 横, through it, sweeping down to the left.","Stroke 3: 捺, from where the strokes cross, sweeping down to the right."],"tip":"A person 人 stretching their arms wide: \"The fish was THIS big!\""},{"type":"vocab","items":[{"t":"一","tr":"yī","mean":"one","example":{"t":"一月","tr":"yīyuè","mean":"January"}},{"t":"二","tr":"èr","mean":"two","example":{"t":"二十","tr":"èrshí","mean":"twenty"}},{"t":"三","tr":"sān","mean":"three","example":{"t":"三月","tr":"sānyuè","mean":"March"}},{"t":"十","tr":"shí","mean":"ten","example":{"t":"十一","tr":"shíyī","mean":"eleven"}},{"t":"人","tr":"rén","mean":"person","example":{"t":"大人","tr":"dàrén","mean":"adult"}},{"t":"口","tr":"kǒu","mean":"mouth","example":{"t":"人口","tr":"rénkǒu","mean":"population"}},{"t":"日","tr":"rì","mean":"sun, day","example":{"t":"日子","tr":"rìzi","mean":"day; life"}},{"t":"月","tr":"yuè","mean":"moon, month","example":{"t":"二月","tr":"èryuè","mean":"February"}},{"t":"大","tr":"dà","mean":"big","example":{"t":"大人","tr":"dàrén","mean":"adult"}}],"title":"Your new characters"},{"type":"tip","kind":"fun","text":"Chinese months are just numbers: 一月 is \"month one\" (January), 二月 \"month two\" (February), all the way to 十二月 shí'èryuè (December)."},{"type":"tip","kind":"memory","text":"人 + 一 = 大: a person with arms stretched out is big. Add one more line on top and you get 天 tiān (sky): what is above the big person."},{"type":"write","level":"letter","items":["一","二","三","十","人","口","日","月","大"],"note":"Follow the stroke order. Write each character at least five times."},{"type":"write","level":"word","items":["三月","十一","大人","人口","二十"],"note":"Two characters per word: keep them the same size."},{"type":"practice","text":"Read the characters and words aloud.","lines":["一 二 三 十","人 口 日 月 大","一月 二月 三月","十一 二十","大人 人口"]},{"type":"quiz","items":[{"q":"Listen. Which character is it?","say":"日","options":["月","日","口","十"],"answer":1},{"q":"Which character means \"big\"?","options":["人","大","十","口"],"answer":1},{"q":"How many strokes does {{口}} have?","options":["4","2","5","3"],"answer":3},{"q":"In {{日}}, which stroke is written third?","options":["The middle line","The bottom line","The left side","The top line"],"answer":0},{"q":"What does {{三月}} mean?","options":["Three moons","Wednesday","March","Thirty days"],"answer":2},{"q":"Which line of {{三}} is the shortest?","options":["The middle one","The top one","The bottom one","They are equal"],"answer":0},{"q":"{{二十}} means...","options":["twelve","two","twenty","February"],"answer":2}],"title":"Quick quiz"}]},{"id":"u2-first-characters-2","icon":"山","title":"First Characters: Nature and Family","subtitle":"小 中 山 水 火 木 女 子","minutes":18,"goals":["Write eight more characters in the correct stroke order","Use the middle-first rule","Read words made from your characters"],"blocks":[{"type":"text","text":"Eight more characters, full of nature and people. Several of them follow the \"middle first\" rule, so watch the first stroke carefully."},{"type":"howto","char":"小","name":"xiǎo · small","steps":["Stroke 1: 竖钩, a vertical line down the middle with a small hook to the left.","Stroke 2: 点, a short dot on the left.","Stroke 3: 点, a dot on the right."],"tip":"One tall stick with two small crumbs beside it: small things!"},{"type":"howto","char":"中","name":"zhōng · middle","steps":["Stroke 1: 竖, the left side of the box.","Stroke 2: 横折, the top and right side in one stroke.","Stroke 3: 横, close the bottom of the box.","Stroke 4: 竖, a long line straight through the middle, written last."],"tip":"An arrow right through the middle of a target. China is 中国, the \"Middle Country\"."},{"type":"howto","char":"山","name":"shān · mountain","steps":["Stroke 1: 竖, the tall middle peak.","Stroke 2: 竖折, down the left side and along the bottom in one stroke.","Stroke 3: 竖, the right peak."],"tip":"Three peaks, the middle one the tallest."},{"type":"howto","char":"水","name":"shuǐ · water","steps":["Stroke 1: 竖钩, the long middle line with a hook to the left.","Stroke 2: 横撇, on the left: a short horizontal that turns down to the left.","Stroke 3: 撇, a short stroke on the upper right.","Stroke 4: 捺, sweeping down to the lower right."],"tip":"A river running down the middle with splashes on both sides."},{"type":"howto","char":"火","name":"huǒ · fire","steps":["Stroke 1: 点, a short dot on the upper left.","Stroke 2: 撇, a short stroke on the upper right, pointing down to the left.","Stroke 3: 撇, the long main stroke from the top centre down to the left.","Stroke 4: 捺, from the middle of stroke 3, sweeping down to the right."],"tip":"A campfire with two sparks jumping out of it."},{"type":"howto","char":"木","name":"mù · tree, wood","steps":["Stroke 1: 横, the branches.","Stroke 2: 竖, the trunk, from top to bottom through the 横.","Stroke 3: 撇, the root on the left.","Stroke 4: 捺, the root on the right."],"tip":"Branches across, trunk down, roots spreading. Two trees 林 make woods; three trees 森 make a forest."},{"type":"howto","char":"女","name":"nǚ · woman","steps":["Stroke 1: 撇点, go down to the left, then turn down to the right, in one stroke.","Stroke 2: 撇, from the upper right sweep down to the lower left, crossing stroke 1.","Stroke 3: 横, a long line across the middle."],"tip":"A dancer with crossed legs and arms stretched out wide."},{"type":"howto","char":"子","name":"zǐ · child","steps":["Stroke 1: 横撇, a short horizontal that turns down to the left.","Stroke 2: 弯钩, a gently curved line down the middle with a hook to the left.","Stroke 3: 横, a long line across the middle."],"tip":"A baby wrapped in a blanket, arms stretched out for a hug."},{"type":"tip","kind":"warn","text":"In {{木}} the last stroke is a long 捺. When 木 sits on the left of another character, as in {{林}} lín, it gets squeezed and that stroke becomes a short dot."},{"type":"vocab","items":[{"t":"小","tr":"xiǎo","mean":"small","example":{"t":"大小","tr":"dàxiǎo","mean":"size"}},{"t":"中","tr":"zhōng","mean":"middle","example":{"t":"中国","tr":"Zhōngguó","mean":"China"}},{"t":"山","tr":"shān","mean":"mountain","example":{"t":"火山","tr":"huǒshān","mean":"volcano"}},{"t":"水","tr":"shuǐ","mean":"water","example":{"t":"山水","tr":"shānshuǐ","mean":"landscape"}},{"t":"火","tr":"huǒ","mean":"fire","example":{"t":"火山","tr":"huǒshān","mean":"volcano"}},{"t":"木","tr":"mù","mean":"tree, wood","example":{"t":"木头","tr":"mùtou","mean":"wood (material)"}},{"t":"女","tr":"nǚ","mean":"woman, female","example":{"t":"女人","tr":"nǚrén","mean":"woman"}},{"t":"子","tr":"zǐ","mean":"child, son","example":{"t":"子女","tr":"zǐnǚ","mean":"sons and daughters"}}],"title":"Your new characters"},{"type":"tip","kind":"memory","text":"火 + 山 = 火山 huǒshān, a \"fire mountain\": a volcano! And 山 + 水 = 山水, \"mountains and water\", the word for a landscape (and for classic Chinese landscape painting)."},{"type":"tip","kind":"culture","text":"女 + 子 makes {{好}} hǎo (good). One old explanation: a woman with her child is a good thing."},{"type":"write","level":"letter","items":["小","中","山","水","火","木","女","子"],"note":"Watch the first stroke: 小 and 水 start in the middle."},{"type":"write","level":"word","items":["大小","火山","山水","女人","子女"],"note":"Keep both characters the same size, each in its own square."},{"type":"practice","text":"Read the characters and words aloud.","lines":["小 中 山 水","火 木 女 子","大小 火山 山水","女人 子女 中国"]},{"type":"quiz","items":[{"q":"Listen. Which character is it?","say":"水","options":["火","水","山","木"],"answer":1},{"q":"What is the first stroke of {{小}}?","options":["The left dot","The right dot","A horizontal","The middle hook"],"answer":3},{"q":"What is the last stroke of {{中}}?","options":["The bottom line","The left side","The top line","The long middle vertical"],"answer":3},{"q":"{{火山}} means...","options":["campfire","volcano","mountain water","big fire"],"answer":1},{"q":"Which character means \"woman\"?","options":["子","大","女","人"],"answer":2},{"q":"How many strokes does {{山}} have?","options":["3","4","2","5"],"answer":0},{"q":"Which two characters make {{好}} (good)?","options":["人 + 木","日 + 月","女 + 子","小 + 大"],"answer":2}],"title":"Quick quiz"}]},{"id":"u2-radicals","icon":"氵","title":"Common Radicals","subtitle":"The meaning parts that unlock thousands of characters","minutes":15,"goals":["Recognise ten common radicals","Guess the meaning area of a new character","Write the radicals in the correct stroke order"],"blocks":[{"type":"text","text":"A **radical** (部首 bùshǒu) is the part of a character that hints at its meaning. Dictionaries are organised by radicals, and once you know the common ones, new characters stop looking like random strokes."},{"type":"table","head":["Radical","Name","Meaning area","Examples"],"rows":[["氵","sāndiǎnshuǐ · \"three drops of water\"","water, liquids","{{河}} hé river, {{海}} hǎi sea, {{洗}} xǐ to wash"],["亻","dānrénpáng · \"person side\"","people","{{你}} nǐ you, {{他}} tā he, {{休}} xiū rest"],["口","kǒuzìpáng · \"mouth side\"","mouth, speaking, eating","{{吃}} chī eat, {{喝}} hē drink, {{叫}} jiào call"],["女","nǚzìpáng · \"woman side\"","women, family","{{妈}} mā mum, {{姐}} jiě big sister, {{她}} tā she"],["木","mùzìpáng · \"tree side\"","trees, wood","{{树}} shù tree, {{林}} lín woods, {{桌}} zhuō table"],["心 / 忄","xīnzìdǐ / shùxīnpáng · \"heart\"","feelings, thinking","{{想}} xiǎng think, {{忙}} máng busy, {{快}} kuài fast"],["讠","yánzìpáng · \"speech side\"","speech, words","{{说}} shuō speak, {{话}} huà words, {{请}} qǐng please"],["扌","tíshǒupáng · \"hand side\"","hand actions","{{打}} dǎ hit, {{找}} zhǎo look for, {{拉}} lā pull"],["艹","cǎozìtóu · \"grass top\"","plants","{{花}} huā flower, {{茶}} chá tea, {{草}} cǎo grass"],["宀","bǎogàitóu · \"roof top\"","houses, shelter","{{家}} jiā home, {{字}} zì character, {{安}} ān peace"]],"title":"Ten radicals to know"},{"type":"tip","kind":"memory","text":"氵 is three drops of water sliding down a window. 亻 is a person standing sideways. 扌 is a hand with fingers spread. 艹 is two little sprouts. 宀 is a roof with a chimney."},{"type":"howto","char":"氵","name":"water radical","steps":["Stroke 1: 点, a dot at the top.","Stroke 2: 点, a second dot below it.","Stroke 3: 提, a rising stroke flicking up to the right."],"tip":"Three drops: drip, drip, splash!"},{"type":"howto","char":"亻","name":"person radical","steps":["Stroke 1: 撇, a short stroke down to the left.","Stroke 2: 竖, a vertical line hanging from the middle of the 撇."],"tip":"A person standing sideways to make room for a friend."},{"type":"howto","char":"讠","name":"speech radical","steps":["Stroke 1: 点, a dot.","Stroke 2: 横折提, a short horizontal, down, then flick up to the right, all in one stroke."],"tip":"A mouth (the dot) and the words coming out."},{"type":"howto","char":"扌","name":"hand radical","steps":["Stroke 1: 横, a short horizontal.","Stroke 2: 竖钩, a vertical line with a hook to the left.","Stroke 3: 提, a rising stroke crossing the 竖 from lower left to upper right."],"tip":"A hand ready to grab something."},{"type":"howto","char":"艹","name":"grass radical","steps":["Stroke 1: 横, a horizontal.","Stroke 2: 竖, a short vertical on the left.","Stroke 3: 竖, a short vertical on the right."],"tip":"Two blades of grass poking through the ground. In mainland China it is written with 3 strokes."},{"type":"howto","char":"宀","name":"roof radical","steps":["Stroke 1: 点, a dot on top (the chimney).","Stroke 2: 点, a short dot on the left.","Stroke 3: 横钩, a horizontal across with a hook down at the right."],"tip":"A roof with a chimney: 宀 + 子 = 字, a child under a roof learning characters."},{"type":"howto","char":"忄","name":"heart radical (side form)","steps":["Stroke 1: 点, a short dot on the left.","Stroke 2: 点, a short dot on the right.","Stroke 3: 竖, a long vertical line down the middle."],"tip":"心 stands up straight when it sits on the side: a heart beating with feelings."},{"type":"vocab","items":[{"t":"河","tr":"hé","mean":"river","root":"氵"},{"t":"洗","tr":"xǐ","mean":"to wash","root":"氵"},{"t":"你","tr":"nǐ","mean":"you","root":"亻"},{"t":"吃","tr":"chī","mean":"to eat","root":"口"},{"t":"妈","tr":"mā","mean":"mum","root":"女"},{"t":"树","tr":"shù","mean":"tree","root":"木"},{"t":"想","tr":"xiǎng","mean":"to think; to want","root":"心"},{"t":"说","tr":"shuō","mean":"to speak","root":"讠"},{"t":"打","tr":"dǎ","mean":"to hit; to play (ball)","root":"扌"},{"t":"花","tr":"huā","mean":"flower","root":"艹"},{"t":"家","tr":"jiā","mean":"home, family","root":"宀"}],"title":"Words grouped by radical"},{"type":"tip","kind":"tip","text":"A radical gives the **area** of meaning, not the exact meaning. 忙 (busy) has the heart radical: being busy is a state of mind!"},{"type":"write","level":"letter","items":["氵","亻","讠","扌","艹","宀","忄"],"note":"Radicals are usually written narrow or flat, because they share a square with another part."},{"type":"practice","text":"Read each group. Say the radical they share.","lines":["河 海 洗","你 他 休","吃 喝 叫","妈 姐 她","说 话 请","花 茶 草","家 字 安"]},{"type":"quiz","items":[{"q":"A character with 氵 probably has to do with...","options":["water","people","plants","speech"],"answer":0},{"q":"Which radical is in {{说}}, {{话}} and {{请}}?","options":["氵","扌","亻","讠"],"answer":3},{"q":"{{花}} (flower) has which radical?","options":["宀","艹","木","口"],"answer":1},{"q":"Which character has the \"person\" radical?","options":["她","他","吃","河"],"answer":1},{"q":"The radical 宀 shows...","options":["a hand","a heart","a mouth","a roof"],"answer":3},{"q":"{{打}} (to hit) has the hand radical. What does a radical tell you?","options":["The general area of meaning","The exact pronunciation","The tone","The stroke count"],"answer":0},{"q":"Which radical is a form of 心 (heart)?","options":["亻","讠","忄","扌"],"answer":2}],"title":"Quick quiz"}]},{"id":"u2-building","icon":"好","title":"Building Characters from Parts","subtitle":"Shapes, idea combinations and sound families","minutes":15,"goals":["Recognise left-right, top-bottom and enclosed shapes","Read idea combinations like 休 and 明","Use sound parts to guess pronunciation"],"blocks":[{"type":"text","text":"Most characters are built like Lego: two or three parts snapped together in a square. Learn the parts and the ways they fit, and every new character becomes a little puzzle you can solve."},{"type":"table","head":["Shape","How the parts fit","Examples"],"rows":[["left + right","two parts side by side","{{你}} {{好}} {{林}} {{妈}}"],["top + bottom","one part above another","{{字}} {{花}} {{想}} {{家}}"],["left + middle + right","three parts side by side","{{树}} {{谢}}"],["full enclosure","a box around the inside","{{国}} {{回}} {{四}}"],["half enclosure","a frame on two or three sides","{{这}} {{同}} {{医}}"]],"title":"How parts fit together"},{"type":"tip","kind":"tip","text":"Every character fits in an imaginary square, no matter how many strokes it has. A part on the left gets thin; a part on top gets flat."},{"type":"text","text":"Put meanings together and a new meaning appears.","title":"Idea combinations"},{"type":"examples","items":[{"t":"休","tr":"xiū","mean":"to rest","note":"亻 person + 木 tree: resting against a tree"},{"t":"明","tr":"míng","mean":"bright","note":"日 sun + 月 moon: the brightest things in the sky"},{"t":"好","tr":"hǎo","mean":"good","note":"女 woman + 子 child"},{"t":"林","tr":"lín","mean":"woods","note":"木 + 木: two trees"},{"t":"森","tr":"sēn","mean":"forest","note":"木 + 木 + 木: many trees"},{"t":"从","tr":"cóng","mean":"from; to follow","note":"人 + 人: one person following another"},{"t":"众","tr":"zhòng","mean":"crowd","note":"人 + 人 + 人: lots of people"},{"t":"尖","tr":"jiān","mean":"pointed, sharp","note":"小 small on top + 大 big below"},{"t":"男","tr":"nán","mean":"man, male","note":"田 field + 力 strength: working in the fields"},{"t":"安","tr":"ān","mean":"peace, safe","note":"宀 roof + 女 woman"}]},{"type":"tip","kind":"memory","text":"{{尖}} is the easiest one ever: small on top of big makes a point, like the tip of a pencil."},{"type":"rule","name":"Sound families","color":"purple","desc":"Characters that share a sound part often sound similar. The meaning part on the side tells them apart.","how":"Same sound part 马, different radicals: 女 woman, 口 mouth, 石 stone...","examples":[{"t":"马","tr":"mǎ · horse"},{"t":"妈","tr":"mā · mum"},{"t":"吗","tr":"ma · question word"},{"t":"骂","tr":"mà · to scold"},{"t":"码","tr":"mǎ · code, number"}]},{"type":"table","head":["Character","Pinyin","Meaning part","Meaning"],"rows":[["{{青}}","qīng","(the sound part)","blue-green; young"],["{{清}}","qīng","氵 water","clear (like water)"],["{{晴}}","qíng","日 sun","sunny"],["{{请}}","qǐng","讠 speech","please; to invite"],["{{情}}","qíng","忄 heart","feeling"],["{{睛}}","jīng","目 eye","eyeball"]],"title":"The 青 family"},{"type":"tip","kind":"warn","text":"Sound parts give a hint, not a guarantee. Tones often differ, and sometimes the sound has changed a lot over the centuries: 睛 is jīng, not qīng."},{"type":"table","head":["Character","Pinyin","Meaning part","Meaning"],"rows":[["{{包}}","bāo","(the sound part)","bag; to wrap"],["{{饱}}","bǎo","饣 food","full (after eating)"],["{{跑}}","pǎo","足 foot (squeezed on the left)","to run"],["{{抱}}","bào","扌 hand","to hug"],["{{泡}}","pào","氵 water","to soak; bubble"]],"title":"The 包 family"},{"type":"practice","text":"Read each family. Notice how similar they sound.","lines":["马 妈 吗 骂","青 清 晴 请 情","包 饱 跑 抱 泡","休 明 林 森 尖"]},{"type":"quiz","items":[{"q":"What does {{明}} (sun + moon) mean?","options":["bright","night","month","sky"],"answer":0},{"q":"{{晴}} has 日 on the left. It probably means...","options":["clear water","feeling","sunny","please"],"answer":2},{"q":"In {{请}} (please), what does 青 give?","options":["The meaning","The sound","The tone","Nothing"],"answer":1},{"q":"{{尖}} means \"pointed\" because...","options":["it has a sharp hook","it looks like a knife","it is a pictograph of a pen","small sits on top of big"],"answer":3},{"q":"Which shape is {{国}}?","options":["left + right","top + bottom","half enclosure","full enclosure"],"answer":3},{"q":"Which character is about running (with a foot radical)?","options":["抱","跑","饱","泡"],"answer":1},{"q":"{{众}} (three people) means...","options":["family","to follow","crowd","one person"],"answer":2}],"title":"Quick quiz"}]},{"id":"u2-simplified-traditional","icon":"繁","title":"Simplified and Traditional Characters","subtitle":"Two ways of writing the same language","minutes":8,"goals":["Know where each system is used","Recognise a few common pairs","Understand how characters were simplified"],"blocks":[{"type":"text","text":"There are two standard sets of Chinese characters. This course teaches **Simplified** characters, used in mainland China. It is useful to know that **Traditional** characters exist too."},{"type":"table","head":["Feature","Simplified 简体字","Traditional 繁體字"],"rows":[["Used in","mainland China, Singapore, Malaysia","Taiwan, Hong Kong, Macau, many overseas communities"],["Since","officially from the 1950s–60s","the older standard forms"],["Strokes","fewer","more"]],"title":"Two systems"},{"type":"table","head":["Simplified","Traditional","Pinyin","Meaning"],"rows":[["{{马}}","{{馬}}","mǎ","horse"],["{{门}}","{{門}}","mén","door"],["{{车}}","{{車}}","chē","vehicle"],["{{说}}","{{說}}","shuō","to speak"],["{{国}}","{{國}}","guó","country"],["{{学}}","{{學}}","xué","to study"],["{{书}}","{{書}}","shū","book"],["{{龙}}","{{龍}}","lóng","dragon"]],"title":"Common pairs"},{"type":"steps","items":[{"title":"Shorter components","t":"说","tr":"shuō","mean":"to speak","desc":"A common part gets a short form: 言 → 讠, 馬 → 马, 門 → 门."},{"title":"Handwriting shapes","t":"书","tr":"shū","mean":"book","desc":"Flowing handwritten forms became standard: 書 → 书, 東 → 东."},{"title":"Keeping just a part","t":"声","tr":"shēng","mean":"sound","desc":"Only part of the old character remains: 聲 → 声."},{"title":"A simpler sound part","t":"远","tr":"yuǎn","mean":"far","desc":"A sound part with fewer strokes replaced the old one: 遠 → 远."}],"title":"How characters were simplified"},{"type":"tip","kind":"fun","text":"The dragon {{龙}} has 5 strokes in Simplified, but {{龍}} has 16 in Traditional!"},{"type":"tip","kind":"culture","text":"A popular joke: Traditional {{愛}} (love) has a heart 心 inside, but Simplified {{爱}} lost it and gained 友 (friend) instead. Love without a heart, but with a friend!"},{"type":"tip","kind":"tip","text":"Good news: all 17 characters you learned in this unit (一 二 三 十 人 口 日 月 大 小 中 山 水 火 木 女 子) are the same in both systems. Pinyin and the spoken language are also the same."},{"type":"practice","text":"Read the simplified characters aloud.","lines":["马 门 车","说 国 学","书 龙 爱"]},{"type":"quiz","items":[{"q":"Which character set does mainland China use?","options":["Simplified","Traditional","Both equally","Neither"],"answer":0},{"q":"Where are Traditional characters used?","options":["Beijing and Shanghai","Singapore","Taiwan and Hong Kong","Only in old books"],"answer":2},{"q":"What is the Simplified form of {{門}}?","options":["门","问","们","间"],"answer":0},{"q":"Which pair matches?","options":["学 / 書","马 / 龍","说 / 車","国 / 國"],"answer":3},{"q":"Simplified characters usually have...","options":["more strokes","fewer strokes","different sounds","no radicals"],"answer":1},{"q":"Are {{人}} and {{山}} different in Traditional?","options":["Yes, both changed","No, they are the same","Only 人 changed","Only 山 changed"],"answer":1}],"title":"Quick quiz"}]},{"id":"u2-copywork","icon":"写","title":"Copywork and Dictation","subtitle":"Write, listen, and check yourself","minutes":15,"goals":["Copy characters neatly in the correct order","Write characters from dictation","Check your progress"],"blocks":[{"type":"text","text":"Practice makes characters stick. In this lesson you copy, then write from memory, then check yourself. A few minutes every day works much better than one long session."},{"type":"steps","items":[{"title":"Look","desc":"Study the character. Find its parts and count its strokes."},{"title":"Trace","desc":"Trace it in the grid, saying each stroke name."},{"title":"Copy","desc":"Write it by yourself, looking at the model."},{"title":"Recall","desc":"Cover the model and write it from memory."},{"title":"Use","desc":"Write a word with it, and say it aloud with the right tone."}],"title":"A five-step routine"},{"type":"tip","kind":"tip","text":"Keep each character in its own square, centred and balanced. Write strokes firmly; do not go back over them."},{"type":"write","level":"letter","items":["一","二","三","十","人","口","日","月","大","小","中","山","水","火","木","女","子"],"note":"Copywork: all 17 characters from this unit."},{"type":"write","level":"word","items":["大人","人口","日子","大小","火山","山水","女人","子女","一月","十二月"],"note":"Copy each word. Say it aloud as you write."},{"type":"write","level":"line","items":["三月十一日","二月二十日","大山小山","日月山水"],"note":"Write each line in one go. 三月十一日 means \"11 March\"."},{"type":"tip","kind":"memory","text":"Before writing from memory, close your eyes and \"see\" the character with its memory picture: the campfire 火, the three peaks 山, the arrow through the target 中."},{"type":"dictation","items":[{"t":"山","tr":"shān","mean":"mountain"},{"t":"水","tr":"shuǐ","mean":"water"},{"t":"火","tr":"huǒ","mean":"fire"},{"t":"人","tr":"rén","mean":"person"},{"t":"中","tr":"zhōng","mean":"middle"},{"t":"大小","tr":"dàxiǎo","mean":"size"},{"t":"火山","tr":"huǒshān","mean":"volcano"},{"t":"三月","tr":"sānyuè","mean":"March"}],"title":"Dictation: listen and write the characters"},{"type":"selfcheck","items":["I can name the eight basic strokes.","I know the seven stroke-order rules.","I can write all 17 characters from memory in the correct order.","I can recognise the ten common radicals.","I can explain how 妈 gets its meaning and its sound.","I know the difference between Simplified and Traditional characters."]},{"type":"quiz","items":[{"q":"Listen. Which character is it?","say":"火","options":["水","大","人","火"],"answer":3},{"q":"Listen. Which word is it?","say":"山水","options":["山水","火山","大小","日子"],"answer":0},{"q":"Which character has 4 strokes?","options":["口","人","木","山"],"answer":2},{"q":"Which character has only 2 strokes?","options":["人","大","女","子"],"answer":0},{"q":"{{日子}} means...","options":["Sunday","son","day; life","sunshine"],"answer":2},{"q":"What is the best way to learn characters?","options":["One long session a month","A little practice every day","Only reading pinyin","Guessing the strokes"],"answer":1},{"q":"{{三月十一日}} is the date...","options":["3 November","31 January","13 March","11 March"],"answer":3}],"title":"Quick quiz"}]}]});
LC.units.push({"id":"words","order":3,"icon":"你好","color":"emerald","title":"First Words & Phrases","subtitle":"Greetings, numbers, money, time, family, food and getting around","lessons":[{"id":"u3-greetings","icon":"你好","title":"Greetings & Politeness","subtitle":"Hello, goodbye, thank you and sorry","minutes":12,"goals":["Greet people politely","Say thank you and sorry","Answer 'How are you?'","Say goodbye"],"blocks":[{"type":"text","text":"Time for your first real Chinese words! Greetings in Mandarin are short, friendly and easy to say. Tap any word to hear it, then copy the voice out loud."},{"type":"vocab","items":[{"t":"你好","tr":"nǐ hǎo","mean":"hello","root":"亻 person","example":{"t":"你好！我是安娜。","tr":"Nǐ hǎo! Wǒ shì Ānnà.","mean":"Hello! I'm Anna."}},{"t":"您好","tr":"nín hǎo","mean":"hello (polite)","root":"心 heart","example":{"t":"老师，您好！","tr":"Lǎoshī, nín hǎo!","mean":"Hello, teacher!"}},{"t":"你们好","tr":"nǐmen hǎo","mean":"hello, everyone","root":"亻 person"},{"t":"早上好","tr":"zǎoshang hǎo","mean":"good morning","root":"日 sun"},{"t":"晚上好","tr":"wǎnshang hǎo","mean":"good evening","root":"日 sun"},{"t":"晚安","tr":"wǎn'ān","mean":"good night (before bed)","root":"宀 roof"},{"t":"再见","tr":"zàijiàn","mean":"goodbye","root":"见 see"},{"t":"明天见","tr":"míngtiān jiàn","mean":"see you tomorrow","root":"见 see"}],"title":"Hello and goodbye"},{"type":"tip","kind":"memory","text":"{{再见}} is literally 'again see'. You can swap in a time: {{明天见}} = 'tomorrow see' = see you tomorrow!"},{"type":"tip","kind":"tip","text":"Two third tones together: the first one rises. So {{你好}} sounds like 'ní hǎo'. The pinyin still writes {{nǐ hǎo}}, so just let your voice do it."},{"type":"tip","kind":"culture","text":"Use {{您}} instead of {{你}} for teachers, older people and customers. It shows respect. With friends and classmates, {{你}} is perfect."},{"type":"sentence","t":"你好吗？","tr":"Nǐ hǎo ma?","mean":"How are you?","words":[{"t":"你","mean":"you"},{"t":"好","mean":"good, well"},{"t":"吗","mean":"(turns it into a question)"}],"note":"Use it with people you already know. With a stranger, a simple 你好！ is enough."},{"type":"examples","items":[{"t":"我很好。","tr":"Wǒ hěn hǎo.","mean":"I'm fine.","hl":"很好"},{"t":"还可以。","tr":"Hái kěyǐ.","mean":"Not bad. / OK."},{"t":"不太好。","tr":"Bú tài hǎo.","mean":"Not so good."},{"t":"你呢？","tr":"Nǐ ne?","mean":"And you?","hl":"呢"}],"title":"Answering 'How are you?'"},{"type":"vocab","items":[{"t":"谢谢","tr":"xièxie","mean":"thank you","root":"讠 speech","example":{"t":"谢谢你！","tr":"Xièxie nǐ!","mean":"Thank you!"}},{"t":"不客气","tr":"bú kèqi","mean":"you're welcome","root":"宀 roof"},{"t":"不用谢","tr":"búyòng xiè","mean":"no need to thank me","root":"讠 speech"},{"t":"对不起","tr":"duìbuqǐ","mean":"sorry","root":"寸 inch"},{"t":"没关系","tr":"méi guānxi","mean":"it's OK, never mind","root":"氵 water"},{"t":"请","tr":"qǐng","mean":"please (inviting, asking politely)","root":"讠 speech","example":{"t":"请坐！","tr":"Qǐng zuò!","mean":"Please sit down!"}},{"t":"请问","tr":"qǐngwèn","mean":"excuse me, may I ask…","root":"讠 speech"}],"title":"Magic words"},{"type":"tip","kind":"tip","text":"{{不}} is normally {{bù}}, but before a fourth tone it changes to {{bú}}: {{不客气}} = {{bú kèqi}}. In this course we always write the tone you actually say."},{"type":"tip","kind":"culture","text":"Close friends and family say {{谢谢}} less than English speakers say 'thanks'. Too many thank-yous can sound a little distant. With shop staff, teachers and strangers, always say it!"},{"type":"tip","kind":"fun","text":"Older neighbours sometimes greet each other with {{你吃了吗？}} (Have you eaten?). It is just a friendly 'hi', not a dinner invitation!"},{"type":"dialogue","lines":[{"who":"Xiaoming","t":"王老师，您好！","tr":"Wáng lǎoshī, nín hǎo!","mean":"Hello, Teacher Wang!"},{"who":"Teacher Wang","t":"你好，小明！你好吗？","tr":"Nǐ hǎo, Xiǎomíng! Nǐ hǎo ma?","mean":"Hi, Xiaoming! How are you?"},{"who":"Xiaoming","t":"我很好，谢谢。您呢？","tr":"Wǒ hěn hǎo, xièxie. Nín ne?","mean":"I'm fine, thanks. And you?"},{"who":"Teacher Wang","t":"我也很好。","tr":"Wǒ yě hěn hǎo.","mean":"I'm fine too."},{"who":"Xiaoming","t":"老师，再见！","tr":"Lǎoshī, zàijiàn!","mean":"Goodbye, teacher!"},{"who":"Teacher Wang","t":"明天见！","tr":"Míngtiān jiàn!","mean":"See you tomorrow!"}],"title":"At school"},{"type":"practice","text":"Read each line aloud. Tap a word if you need to hear it again.","lines":["你好！","您好！","你好吗？","我很好，谢谢。你呢？","对不起！ 没关系。","谢谢！ 不客气。","再见！ 明天见！"]},{"type":"quiz","items":[{"q":"Listen. What does it mean?","say":"谢谢","options":["Thank you","Hello","Sorry","Goodbye"],"answer":0},{"q":"Someone says {{谢谢}} to you. What do you answer?","options":["没关系","不客气","早上好","再见"],"answer":1,"explain":"{{不客气}} = you're welcome. {{没关系}} answers 'sorry'."},{"q":"Which hello is more polite, for an older person?","options":["你好","你们好","晚安","您好"],"answer":3,"explain":"{{您}} is the respectful 'you'."},{"q":"{{对不起}} means…","options":["Please","Sorry","Good night","Thank you"],"answer":1},{"q":"Listen. When do you say this?","say":"晚安","options":["At bedtime","When you're sorry","In the morning","At lunchtime"],"answer":0},{"q":"How do you say 'See you tomorrow'?","options":["早上好","晚上好","再见了","明天见"],"answer":3},{"q":"What does {{你呢？}} mean?","options":["Where are you?","Are you OK?","And you?","Who are you?"],"answer":2}],"title":"Quick quiz"}]},{"id":"u3-introduce","icon":"我","title":"Introducing Yourself","subtitle":"Your name, your country, nice to meet you","minutes":14,"goals":["Say your name with 我叫…","Ask someone's name","Say where you are from","Say 'nice to meet you'"],"blocks":[{"type":"text","text":"Let's introduce ourselves! With just three short patterns you can tell people your name, where you are from and that you are happy to meet them."},{"type":"sentence","t":"我叫李明。","tr":"Wǒ jiào Lǐ Míng.","mean":"My name is Li Ming.","words":[{"t":"我","mean":"I"},{"t":"叫","mean":"am called"},{"t":"李明","mean":"Li Ming (a name)"}],"note":"叫 means 'to be called'. Put your own name at the end."},{"type":"sentence","t":"你叫什么名字？","tr":"Nǐ jiào shénme míngzi?","mean":"What's your name?","words":[{"t":"你","mean":"you"},{"t":"叫","mean":"are called"},{"t":"什么","mean":"what"},{"t":"名字","mean":"name"}],"note":"Word for word: 'You are called what name?'"},{"type":"tip","kind":"memory","text":"Chinese questions don't flip the word order. The question word sits exactly where the answer goes: {{你叫什么名字？}} → {{我叫李明。}}"},{"type":"vocab","items":[{"t":"名字","tr":"míngzi","mean":"name","root":"口 mouth"},{"t":"叫","tr":"jiào","mean":"to be called; to call","root":"口 mouth","example":{"t":"我叫安娜。","tr":"Wǒ jiào Ānnà.","mean":"My name is Anna."}},{"t":"姓","tr":"xìng","mean":"surname; to be surnamed","root":"女 woman","example":{"t":"我姓王。","tr":"Wǒ xìng Wáng.","mean":"My surname is Wang."}},{"t":"是","tr":"shì","mean":"to be (am, is, are)","root":"日 sun"},{"t":"人","tr":"rén","mean":"person, people","root":"人 person"},{"t":"学生","tr":"xuésheng","mean":"student","root":"子 child"},{"t":"老师","tr":"lǎoshī","mean":"teacher","root":"巾 cloth"},{"t":"朋友","tr":"péngyou","mean":"friend","root":"月 moon"},{"t":"认识","tr":"rènshi","mean":"to know (a person), to meet","root":"讠 speech"},{"t":"高兴","tr":"gāoxìng","mean":"happy, glad","root":"八 eight"}],"title":"Words for meeting people"},{"type":"sentence","t":"很高兴认识你。","tr":"Hěn gāoxìng rènshi nǐ.","mean":"Nice to meet you.","words":[{"t":"很","mean":"very"},{"t":"高兴","mean":"glad"},{"t":"认识","mean":"to meet, to know"},{"t":"你","mean":"you"}],"note":"Reply with 我也很高兴认识你 (I'm glad to meet you too)."},{"type":"tip","kind":"culture","text":"Chinese names put the **family name first**. In {{王丽}} (Wáng Lì), Wang is the surname and Li is the given name. The most common surnames are {{王}}, {{李}}, {{张}}, {{刘}} and {{陈}}."},{"type":"examples","items":[{"t":"您贵姓？","tr":"Nín guì xìng?","mean":"May I ask your surname? (polite)","hl":"贵姓"},{"t":"我姓王，叫王丽。","tr":"Wǒ xìng Wáng, jiào Wáng Lì.","mean":"My surname is Wang; my full name is Wang Li.","hl":"姓王"}],"title":"The polite way"},{"type":"vocab","items":[{"t":"中国","tr":"Zhōngguó","mean":"China","root":"囗 enclosure"},{"t":"美国","tr":"Měiguó","mean":"the USA","root":"囗 enclosure"},{"t":"英国","tr":"Yīngguó","mean":"the UK","root":"囗 enclosure"},{"t":"加拿大","tr":"Jiānádà","mean":"Canada"},{"t":"澳大利亚","tr":"Àodàlìyà","mean":"Australia"},{"t":"法国","tr":"Fǎguó","mean":"France","root":"囗 enclosure"},{"t":"德国","tr":"Déguó","mean":"Germany","root":"囗 enclosure"},{"t":"日本","tr":"Rìběn","mean":"Japan","root":"日 sun"},{"t":"印度","tr":"Yìndù","mean":"India"}],"title":"Countries"},{"type":"sentence","t":"你是哪国人？","tr":"Nǐ shì nǎ guó rén?","mean":"Which country are you from?","words":[{"t":"你","mean":"you"},{"t":"是","mean":"are"},{"t":"哪","mean":"which"},{"t":"国","mean":"country"},{"t":"人","mean":"person"}],"note":"Literally 'You are which-country person?'"},{"type":"rule","name":"Country + 人 = nationality","color":"green","desc":"Add {{人}} (person) after a country and you get the nationality.","examples":[{"t":"中国人","tr":"Zhōngguó rén","hl":"人"},{"t":"美国人","tr":"Měiguó rén","hl":"人"},{"t":"英国人","tr":"Yīngguó rén","hl":"人"}]},{"type":"examples","items":[{"t":"我是美国人。","tr":"Wǒ shì Měiguó rén.","mean":"I'm American.","hl":"美国人"},{"t":"她是中国人。","tr":"Tā shì Zhōngguó rén.","mean":"She is Chinese.","hl":"中国人"},{"t":"我是学生。","tr":"Wǒ shì xuésheng.","mean":"I'm a student.","hl":"学生"}]},{"type":"dialogue","lines":[{"who":"Anna","t":"你好！我叫安娜。你叫什么名字？","tr":"Nǐ hǎo! Wǒ jiào Ānnà. Nǐ jiào shénme míngzi?","mean":"Hi! I'm Anna. What's your name?"},{"who":"Li Ming","t":"我叫李明。很高兴认识你！","tr":"Wǒ jiào Lǐ Míng. Hěn gāoxìng rènshi nǐ!","mean":"I'm Li Ming. Nice to meet you!"},{"who":"Anna","t":"我也很高兴认识你。","tr":"Wǒ yě hěn gāoxìng rènshi nǐ.","mean":"Nice to meet you too."},{"who":"Li Ming","t":"你是哪国人？","tr":"Nǐ shì nǎ guó rén?","mean":"Where are you from?"},{"who":"Anna","t":"我是英国人。你是中国人吗？","tr":"Wǒ shì Yīngguó rén. Nǐ shì Zhōngguó rén ma?","mean":"I'm British. Are you Chinese?"},{"who":"Li Ming","t":"对，我是中国人。我是学生。","tr":"Duì, wǒ shì Zhōngguó rén. Wǒ shì xuésheng.","mean":"Yes, I'm Chinese. I'm a student."}],"title":"First meeting"},{"type":"steps","items":[{"title":"Say hello","t":"你好！","tr":"Nǐ hǎo!","mean":"Hello!"},{"title":"Give your name","t":"我叫……","tr":"Wǒ jiào …","mean":"My name is …"},{"title":"Say where you are from","t":"我是……人。","tr":"Wǒ shì … rén.","mean":"I'm from …"},{"title":"Be friendly","t":"很高兴认识你！","tr":"Hěn gāoxìng rènshi nǐ!","mean":"Nice to meet you!"}],"title":"Your introduction in 4 steps"},{"type":"practice","text":"Read these aloud, then say them again with your own name and country.","lines":["我叫李明。","你叫什么名字？","我姓王。","我是美国人。","你是哪国人？","很高兴认识你！"]},{"type":"quiz","items":[{"q":"How do you ask 'What's your name?'","options":["你是哪国人？","你是学生吗？","你叫什么名字？","你好吗？"],"answer":2},{"q":"{{我是英国人}} means…","options":["I'm a teacher.","I'm Chinese.","I live in England.","I'm British."],"answer":3},{"q":"In the name {{张伟}} (Zhāng Wěi), which part is the surname?","options":["Neither","Both","张","伟"],"answer":2,"explain":"Chinese surnames come first."},{"q":"Listen. What did you hear?","say":"很高兴认识你","options":["Where are you from?","What's your name?","Nice to meet you.","See you tomorrow."],"answer":2},{"q":"Which word means 'friend'?","options":["名字","学生","朋友","老师"],"answer":2},{"q":"How do you say 'Japanese person'?","options":["人日本","是日本","日本人","日本国"],"answer":2},{"q":"Listen. Which word means 'to be called'?","say":"叫","options":["叫","姓","人","是"],"answer":0}],"title":"Quick quiz"}]},{"id":"u3-numbers","icon":"八","title":"Numbers 0–10 & Hand Signs","subtitle":"Count to ten with your voice and one hand","minutes":12,"goals":["Count from 0 to 10","Use Chinese hand signs for 6–10","Know when 一 changes its tone","Know the lucky and unlucky numbers"],"blocks":[{"type":"text","text":"Chinese numbers are short, clear and very logical. Learn these eleven and you can already count to 99 in the next lesson!"},{"type":"vocab","items":[{"t":"零","tr":"líng","mean":"0, zero","root":"雨 rain"},{"t":"一","tr":"yī","mean":"1, one","root":"一 one"},{"t":"二","tr":"èr","mean":"2, two","root":"二 two"},{"t":"三","tr":"sān","mean":"3, three"},{"t":"四","tr":"sì","mean":"4, four","root":"囗 enclosure"},{"t":"五","tr":"wǔ","mean":"5, five"},{"t":"六","tr":"liù","mean":"6, six","root":"八 eight"},{"t":"七","tr":"qī","mean":"7, seven"},{"t":"八","tr":"bā","mean":"8, eight","root":"八 eight"},{"t":"九","tr":"jiǔ","mean":"9, nine"},{"t":"十","tr":"shí","mean":"10, ten","root":"十 ten"},{"t":"两","tr":"liǎng","mean":"two (before a measure word)","example":{"t":"两个人","tr":"liǎng gè rén","mean":"two people"}}],"title":"Zero to ten"},{"type":"tip","kind":"memory","text":"One, two and three are just lines: {{一}} {{二}} {{三}}. {{十}} is a cross, like a plus sign. {{八}} looks like two lines spreading apart."},{"type":"tip","kind":"warn","text":"Listen carefully: {{四}} (sì, 4) and {{十}} (shí, 10) sound close. Sì is a short falling 'ss'; shí rises and has the 'sh' sound."},{"type":"table","head":["Number","Chinese","Pinyin","Hand sign"],"rows":[["1","{{一}}","yī","Index finger up"],["2","{{二}}","èr","Index and middle finger up"],["3","{{三}}","sān","Middle, ring and little finger up"],["4","{{四}}","sì","Four fingers up, thumb folded in"],["5","{{五}}","wǔ","Open hand"],["6","{{六}}","liù","Thumb and little finger out"],["7","{{七}}","qī","Fingertips of thumb, index and middle finger pinched together"],["8","{{八}}","bā","Thumb and index finger out, like an L"],["9","{{九}}","jiǔ","Index finger bent into a hook"],["10","{{十}}","shí","A fist, or two index fingers crossed like {{十}}"]],"title":"Count on one hand"},{"type":"tip","kind":"culture","text":"Chinese people count to ten on **one hand**. You will see these signs at markets and in noisy places. Some regions use small variations, but these are the most common."},{"type":"rule","name":"The tone of 一 changes","color":"orange","desc":"When counting, in dates and at the end of a number, {{一}} is {{yī}}. Before a fourth tone it becomes {{yí}}. Before tones 1, 2 and 3 it becomes {{yì}}.","examples":[{"t":"一个","tr":"yí gè","hl":"一"},{"t":"一天","tr":"yì tiān","hl":"一"},{"t":"一年","tr":"yì nián","hl":"一"},{"t":"一百","tr":"yìbǎi","hl":"一"},{"t":"十一","tr":"shíyī","hl":"一"}]},{"type":"tip","kind":"tip","text":"When people read out phone numbers or room numbers, they often say {{yāo}} for 1, so it is not confused with {{七}} (qī). Room 101 = 'yāo líng yāo'."},{"type":"tip","kind":"fun","text":"{{八}} (bā) is the luckiest number because it sounds like {{发}} (fā, to get rich). The Beijing Olympics opened on 8/8/2008 at 8:08 p.m.! {{四}} (sì) is unlucky because it sounds like {{死}} (sǐ, to die), so some buildings skip the 4th floor."},{"type":"howto","char":"十","name":"shí — ten","steps":["Draw a horizontal line from left to right.","Draw a vertical line from top to bottom, crossing the middle."],"tip":"Horizontal before vertical is one of the basic stroke-order rules."},{"type":"write","level":"letter","items":["一","二","三","十","八","六"],"note":"Copy each number. Say it out loud as you write."},{"type":"practice","text":"Count out loud. Then count backwards!","lines":["一 二 三 四 五","六 七 八 九 十","十 九 八 七 六","五 四 三 二 一 零"]},{"type":"quiz","items":[{"q":"Listen. Which number?","say":"七","options":["7","1","10","4"],"answer":0},{"q":"Listen. Which number?","say":"四","options":["10","5","9","4"],"answer":3},{"q":"Thumb and little finger out means…","options":["8","3","10","6"],"answer":3},{"q":"Which number is lucky in China?","options":["8","7","4","1"],"answer":0,"explain":"{{八}} bā sounds like {{发}} fā, to get rich."},{"q":"{{零}} is…","options":["2","0","6","10"],"answer":1},{"q":"Which is the correct pinyin for {{一个}}?","options":["yǐ gè","yī gè","yì gè","yí gè"],"answer":3,"explain":"个 is a fourth tone, so 一 becomes yí."},{"q":"Listen. Which number?","say":"九","options":["5","2","6","9"],"answer":3}],"title":"Quick quiz"}]},{"id":"u3-money","icon":"钱","title":"Numbers to 100 & Money","subtitle":"Count to a hundred and go shopping","minutes":15,"goals":["Say any number up to 100","Use 块, 毛 and 元 for prices","Ask 'How much is it?'","Bargain politely at a market"],"blocks":[{"type":"text","text":"If you know 1 to 10, you already know 11 to 99. Chinese numbers are built like Lego. Then we'll use them to go shopping!"},{"type":"table","head":["Number","Chinese","Pinyin","How it works"],"rows":[["11","{{十一}}","shíyī","ten + one"],["12","{{十二}}","shí'èr","ten + two"],["20","{{二十}}","èrshí","two tens"],["21","{{二十一}}","èrshíyī","two tens + one"],["35","{{三十五}}","sānshíwǔ","three tens + five"],["99","{{九十九}}","jiǔshíjiǔ","nine tens + nine"],["100","{{一百}}","yìbǎi","one hundred"]],"title":"Building numbers"},{"type":"rule","name":"Tens + 十 + units","color":"blue","desc":"Say the tens digit, then {{十}}, then the units digit. Nothing else to learn!","examples":[{"t":"十五","tr":"shíwǔ"},{"t":"四十","tr":"sìshí"},{"t":"六十八","tr":"liùshíbā"},{"t":"七十七","tr":"qīshíqī"}]},{"type":"tip","kind":"warn","text":"Order matters! {{十四}} (shísì) is 14 but {{四十}} (sìshí) is 40."},{"type":"vocab","items":[{"t":"钱","tr":"qián","mean":"money","root":"钅 metal"},{"t":"块","tr":"kuài","mean":"yuan (spoken)","root":"土 earth","example":{"t":"五块","tr":"wǔ kuài","mean":"five yuan"}},{"t":"元","tr":"yuán","mean":"yuan (written, on price tags)"},{"t":"毛","tr":"máo","mean":"0.1 yuan (spoken)","root":"毛 fur"},{"t":"角","tr":"jiǎo","mean":"0.1 yuan (written)"},{"t":"分","tr":"fēn","mean":"0.01 yuan; minute","root":"刀 knife"},{"t":"人民币","tr":"rénmínbì","mean":"RMB, Chinese money","root":"巾 cloth"},{"t":"多少","tr":"duōshao","mean":"how much, how many"},{"t":"贵","tr":"guì","mean":"expensive","root":"贝 shell"},{"t":"便宜","tr":"piányi","mean":"cheap","root":"亻 person"},{"t":"买","tr":"mǎi","mean":"to buy"},{"t":"卖","tr":"mài","mean":"to sell","root":"十 ten"}],"title":"Money words"},{"type":"tip","kind":"memory","text":"{{买}} (mǎi, buy) and {{卖}} (mài, sell) look alike. Selling has an extra {{十}} on top: you need **more** (+) to sell!"},{"type":"tip","kind":"memory","text":"The radical {{贝}} is an old picture of a shell. Long ago shells were money, so {{贵}} (expensive) has a shell inside."},{"type":"table","head":["Price","Written (tag)","Spoken"],"rows":[["¥5","{{五元}}","{{五块}}"],["¥0.50","{{五角}}","{{五毛}}"],["¥3.50","{{三元五角}}","{{三块五}}"],["¥2","{{二元}}","{{两块}}"],["¥12.80","{{十二元八角}}","{{十二块八}}"]],"title":"Reading prices"},{"type":"tip","kind":"tip","text":"In speech you can drop the last unit: {{三块五}} = 3.50. And before {{块}} or {{毛}} on its own, 2 is {{两}}: {{两块}}, not 二块. But 12 is still {{十二块}}."},{"type":"sentence","t":"这个多少钱？","tr":"Zhège duōshao qián?","mean":"How much is this?","words":[{"t":"这个","mean":"this one"},{"t":"多少","mean":"how much"},{"t":"钱","mean":"money"}]},{"type":"examples","items":[{"t":"太贵了！","tr":"Tài guì le!","mean":"Too expensive!","hl":"贵"},{"t":"便宜一点儿吧。","tr":"Piányi yìdiǎnr ba.","mean":"A bit cheaper, please.","hl":"便宜"},{"t":"我买两个。","tr":"Wǒ mǎi liǎng gè.","mean":"I'll buy two.","hl":"两个"},{"t":"一共多少钱？","tr":"Yígòng duōshao qián?","mean":"How much altogether?","hl":"一共"}],"title":"Shopping phrases"},{"type":"dialogue","lines":[{"who":"Customer","t":"老板，苹果多少钱一斤？","tr":"Lǎobǎn, píngguǒ duōshao qián yì jīn?","mean":"Excuse me, how much are apples per jin?"},{"who":"Seller","t":"八块一斤。","tr":"Bā kuài yì jīn.","mean":"Eight kuai a jin."},{"who":"Customer","t":"太贵了！六块吧。","tr":"Tài guì le! Liù kuài ba.","mean":"Too expensive! How about six?"},{"who":"Seller","t":"七块，好吗？","tr":"Qī kuài, hǎo ma?","mean":"Seven, OK?"},{"who":"Customer","t":"好，我买两斤。","tr":"Hǎo, wǒ mǎi liǎng jīn.","mean":"OK, I'll take two jin."},{"who":"Seller","t":"一共十四块。","tr":"Yígòng shísì kuài.","mean":"That's fourteen kuai altogether."}],"title":"At the fruit market"},{"type":"tip","kind":"culture","text":"Fruit and vegetables are sold by the {{斤}} (jīn), which is 500 grams. Shop owners are often called {{老板}} (boss). Today most people pay by scanning a QR code with their phone, but cash still works."},{"type":"practice","text":"Read the numbers and prices aloud.","lines":["十一 二十 三十五 九十九 一百","五块","三块五","两块","这个多少钱？","太贵了！"]},{"type":"quiz","items":[{"q":"Listen. Which number?","say":"四十","options":["14","4","44","40"],"answer":3},{"q":"How do you say 99?","options":["九九十","十九九","九十九","九百九"],"answer":2},{"q":"How do you SAY ¥2.50 in a shop?","options":["二块五","两毛五","两块五","二十五块"],"answer":2},{"q":"{{多少钱？}} means…","options":["Is it cheap?","How many people?","Where is the money?","How much is it?"],"answer":3},{"q":"Listen. What does the shopper say?","say":"太贵了","options":["How much?","That's very cheap!","Too expensive!","I'll buy two of them."],"answer":2},{"q":"1 {{块}} = how many {{毛}}?","options":["10","2","5","100"],"answer":0},{"q":"Which word means 'cheap'?","options":["卖","贵","钱","便宜"],"answer":3}],"title":"Quick quiz"}]},{"id":"u3-time","icon":"点","title":"Dates & Time","subtitle":"Days, months, dates and telling the time","minutes":15,"goals":["Name the days of the week","Say a date in Chinese order","Ask and tell the time","Talk about birthdays"],"blocks":[{"type":"text","text":"Good news: Chinese dates and times use the numbers you already know. Monday is 'week-one', May is 'five-month'. Easy!"},{"type":"vocab","items":[{"t":"今天","tr":"jīntiān","mean":"today","root":"人 person"},{"t":"明天","tr":"míngtiān","mean":"tomorrow","root":"日 sun"},{"t":"昨天","tr":"zuótiān","mean":"yesterday","root":"日 sun"},{"t":"星期","tr":"xīngqī","mean":"week","root":"日 sun"},{"t":"周末","tr":"zhōumò","mean":"weekend"},{"t":"年","tr":"nián","mean":"year"},{"t":"月","tr":"yuè","mean":"month; moon","root":"月 moon"},{"t":"号","tr":"hào","mean":"day of the month (spoken)","root":"口 mouth"},{"t":"日","tr":"rì","mean":"day of the month (written); sun","root":"日 sun"},{"t":"生日","tr":"shēngrì","mean":"birthday","root":"日 sun"}],"title":"Days and dates"},{"type":"table","head":["English","Chinese","Pinyin"],"rows":[["Monday","{{星期一}}","xīngqīyī"],["Tuesday","{{星期二}}","xīngqī'èr"],["Wednesday","{{星期三}}","xīngqīsān"],["Thursday","{{星期四}}","xīngqīsì"],["Friday","{{星期五}}","xīngqīwǔ"],["Saturday","{{星期六}}","xīngqīliù"],["Sunday","{{星期天}} / {{星期日}}","xīngqītiān / xīngqīrì"]],"title":"Days of the week"},{"type":"tip","kind":"memory","text":"Monday to Saturday are 'week + 1' to 'week + 6'. Sunday is the odd one: 'week + day' ({{天}}) or 'week + sun' ({{日}}). On signs you will also see {{周一}} for Monday."},{"type":"examples","items":[{"t":"一月","tr":"yīyuè","mean":"January"},{"t":"五月","tr":"wǔyuè","mean":"May"},{"t":"十月","tr":"shíyuè","mean":"October"},{"t":"十二月","tr":"shí'èryuè","mean":"December"}],"title":"Months: number + 月"},{"type":"rule","name":"Big to small","color":"purple","desc":"Chinese dates go from the biggest unit to the smallest: year → month → day → weekday. Years are read digit by digit.","examples":[{"t":"二〇二六年","tr":"èr líng èr liù nián","hl":"年"},{"t":"一月一日","tr":"yīyuè yī rì","hl":"日"},{"t":"二〇二六年一月一日，星期四","tr":"èr líng èr liù nián yīyuè yī rì, xīngqīsì"}]},{"type":"sentence","t":"今天几月几号？","tr":"Jīntiān jǐ yuè jǐ hào?","mean":"What's the date today?","words":[{"t":"今天","mean":"today"},{"t":"几","mean":"which (number)"},{"t":"月","mean":"month"},{"t":"几","mean":"which (number)"},{"t":"号","mean":"day"}]},{"type":"sentence","t":"今天星期几？","tr":"Jīntiān xīngqī jǐ?","mean":"What day is it today?","words":[{"t":"今天","mean":"today"},{"t":"星期","mean":"week"},{"t":"几","mean":"which number"}],"note":"No 是 is needed in date sentences: 今天星期五 = Today is Friday."},{"type":"vocab","items":[{"t":"现在","tr":"xiànzài","mean":"now"},{"t":"点","tr":"diǎn","mean":"o'clock","root":"灬 fire"},{"t":"分","tr":"fēn","mean":"minute","root":"刀 knife"},{"t":"半","tr":"bàn","mean":"half"},{"t":"刻","tr":"kè","mean":"quarter of an hour","root":"刂 knife"},{"t":"差","tr":"chà","mean":"to (before the hour); short of"},{"t":"早上","tr":"zǎoshang","mean":"early morning","root":"日 sun"},{"t":"上午","tr":"shàngwǔ","mean":"morning (before noon)"},{"t":"中午","tr":"zhōngwǔ","mean":"noon"},{"t":"下午","tr":"xiàwǔ","mean":"afternoon"},{"t":"晚上","tr":"wǎnshang","mean":"evening, night","root":"日 sun"}],"title":"Telling the time"},{"type":"sentence","t":"现在几点？","tr":"Xiànzài jǐ diǎn?","mean":"What time is it now?","words":[{"t":"现在","mean":"now"},{"t":"几","mean":"how many"},{"t":"点","mean":"o'clock"}]},{"type":"examples","items":[{"t":"八点","tr":"bā diǎn","mean":"8:00"},{"t":"两点","tr":"liǎng diǎn","mean":"2:00","hl":"两","note":"Use 两, not 二, for two o'clock."},{"t":"三点半","tr":"sān diǎn bàn","mean":"3:30","hl":"半"},{"t":"七点一刻","tr":"qī diǎn yí kè","mean":"7:15","hl":"一刻"},{"t":"十点十分","tr":"shí diǎn shí fēn","mean":"10:10","hl":"分"},{"t":"差五分九点","tr":"chà wǔ fēn jiǔ diǎn","mean":"8:55 (five to nine)","hl":"差"},{"t":"下午四点","tr":"xiàwǔ sì diǎn","mean":"4 p.m.","hl":"下午"}],"title":"What time is it?"},{"type":"tip","kind":"tip","text":"Part of the day goes **before** the time: {{晚上八点}} = 8 p.m. ('evening eight o'clock'). Timetables and tickets use the 24-hour clock."},{"type":"dialogue","lines":[{"who":"Lin","t":"你的生日是几月几号？","tr":"Nǐ de shēngrì shì jǐ yuè jǐ hào?","mean":"When is your birthday?"},{"who":"Sam","t":"五月八号。你呢？","tr":"Wǔyuè bā hào. Nǐ ne?","mean":"May 8th. And yours?"},{"who":"Lin","t":"我的生日是明天！","tr":"Wǒ de shēngrì shì míngtiān!","mean":"My birthday is tomorrow!"},{"who":"Sam","t":"真的吗？生日快乐！","tr":"Zhēn de ma? Shēngrì kuàilè!","mean":"Really? Happy birthday!"},{"who":"Lin","t":"谢谢！明天晚上七点，我们一起吃饭吧。","tr":"Xièxie! Míngtiān wǎnshang qī diǎn, wǒmen yìqǐ chī fàn ba.","mean":"Thanks! Let's have dinner together tomorrow at 7 p.m."},{"who":"Sam","t":"好啊！","tr":"Hǎo a!","mean":"Great!"}],"title":"Birthdays"},{"type":"tip","kind":"culture","text":"The Spring Festival (Chinese New Year) follows the lunar calendar, so its date moves every year, somewhere between late January and mid-February."},{"type":"practice","text":"Say these dates and times aloud.","lines":["星期一","星期天","十月一号","现在几点？","三点半","晚上八点"]},{"type":"quiz","items":[{"q":"How do you say 'Wednesday'?","options":["星期二","星期四","星期三","星期天"],"answer":2},{"q":"Listen. What time is it?","say":"三点半","options":["3:15","3:03","13:00","3:30"],"answer":3},{"q":"Which is NOT a way to say Sunday?","options":["星期日","星期七","星期天"],"answer":1,"explain":"There is no 'week-seven'. Sunday is 星期天 or 星期日."},{"q":"Which date is in the correct Chinese order?","options":["8日5月2026年","2026年5月8日","5月8日2026年"],"answer":1},{"q":"{{昨天}} means…","options":["the day after","today","tomorrow","yesterday"],"answer":3},{"q":"Listen. What time is it?","say":"差五分九点","options":["9:55","9:05","8:55","5:09"],"answer":2},{"q":"What time is {{两点}}?","options":["12:00","2:30","10:00","2:00"],"answer":3}],"title":"Quick quiz"}]},{"id":"u3-family","icon":"家","title":"Family","subtitle":"Parents, brothers, sisters and grandparents","minutes":13,"goals":["Name family members","Tell older and younger siblings apart","Say how many people are in your family","Use 有 and 没有"],"blocks":[{"type":"text","text":"Family is at the heart of Chinese culture, and the words are very precise. There is no single word for 'brother': you must say if he is older or younger!"},{"type":"vocab","items":[{"t":"家","tr":"jiā","mean":"family; home","root":"宀 roof"},{"t":"爸爸","tr":"bàba","mean":"dad","root":"父 father"},{"t":"妈妈","tr":"māma","mean":"mum","root":"女 woman"},{"t":"哥哥","tr":"gēge","mean":"older brother","root":"口 mouth"},{"t":"姐姐","tr":"jiějie","mean":"older sister","root":"女 woman"},{"t":"弟弟","tr":"dìdi","mean":"younger brother"},{"t":"妹妹","tr":"mèimei","mean":"younger sister","root":"女 woman"},{"t":"爷爷","tr":"yéye","mean":"grandpa (dad's father)","root":"父 father"},{"t":"奶奶","tr":"nǎinai","mean":"grandma (dad's mother)","root":"女 woman"},{"t":"外公","tr":"wàigōng","mean":"grandpa (mum's father)"},{"t":"外婆","tr":"wàipó","mean":"grandma (mum's mother)","root":"女 woman"},{"t":"儿子","tr":"érzi","mean":"son","root":"子 child"},{"t":"女儿","tr":"nǚ'ér","mean":"daughter","root":"女 woman"},{"t":"孩子","tr":"háizi","mean":"child, children","root":"子 child"},{"t":"丈夫","tr":"zhàngfu","mean":"husband"},{"t":"妻子","tr":"qīzi","mean":"wife","root":"女 woman"}],"title":"Family words"},{"type":"tip","kind":"memory","text":"Spot the radical {{女}} (woman) in {{妈}}, {{姐}}, {{妹}}, {{奶}}, {{婆}} and {{妻}}. And {{父}} (father) sits on top of {{爸}} and {{爷}}."},{"type":"table","head":["","Older","Younger"],"rows":[["Brother","{{哥哥}} gēge","{{弟弟}} dìdi"],["Sister","{{姐姐}} jiějie","{{妹妹}} mèimei"]],"title":"Older or younger?"},{"type":"tip","kind":"culture","text":"Grandparents on your dad's side ({{爷爷}}, {{奶奶}}) have different names from those on your mum's side ({{外公}}, {{外婆}}). {{外}} means 'outside'. Children also call adult friends of the family {{叔叔}} (shūshu, uncle) and {{阿姨}} (āyí, auntie)."},{"type":"vocab","items":[{"t":"有","tr":"yǒu","mean":"to have; there is","root":"月 moon","example":{"t":"我有一个妹妹。","tr":"Wǒ yǒu yí gè mèimei.","mean":"I have a younger sister."}},{"t":"没有","tr":"méiyǒu","mean":"not have","root":"氵 water","example":{"t":"我没有哥哥。","tr":"Wǒ méiyǒu gēge.","mean":"I don't have an older brother."}},{"t":"岁","tr":"suì","mean":"years old","root":"山 mountain","example":{"t":"他十二岁。","tr":"Tā shí'èr suì.","mean":"He is twelve."}},{"t":"口","tr":"kǒu","mean":"measure word for family members","root":"口 mouth"}],"title":"Useful words"},{"type":"sentence","t":"你家有几口人？","tr":"Nǐ jiā yǒu jǐ kǒu rén?","mean":"How many people are in your family?","words":[{"t":"你","mean":"your"},{"t":"家","mean":"family"},{"t":"有","mean":"has"},{"t":"几","mean":"how many"},{"t":"口","mean":"(measure word: 'mouths')"},{"t":"人","mean":"people"}],"note":"Family members are counted in 'mouths' ({{口}}), people to feed!"},{"type":"examples","items":[{"t":"我家有四口人。","tr":"Wǒ jiā yǒu sì kǒu rén.","mean":"There are four people in my family.","hl":"四口人"},{"t":"我有一个哥哥。","tr":"Wǒ yǒu yí gè gēge.","mean":"I have an older brother.","hl":"哥哥"},{"t":"我没有姐姐。","tr":"Wǒ méiyǒu jiějie.","mean":"I don't have an older sister.","hl":"没有","note":"The opposite of 有 is always 没有, never 不有."},{"t":"这是我妈妈。","tr":"Zhè shì wǒ māma.","mean":"This is my mum.","hl":"妈妈"}]},{"type":"dialogue","lines":[{"who":"Tom","t":"这是你的家人吗？","tr":"Zhè shì nǐ de jiārén ma?","mean":"Is this your family?"},{"who":"Xiaoyu","t":"对。这是我爸爸，这是我妈妈。","tr":"Duì. Zhè shì wǒ bàba, zhè shì wǒ māma.","mean":"Yes. This is my dad, and this is my mum."},{"who":"Tom","t":"他是你哥哥吗？","tr":"Tā shì nǐ gēge ma?","mean":"Is he your older brother?"},{"who":"Xiaoyu","t":"不是，他是我弟弟。他十二岁。","tr":"Bú shì, tā shì wǒ dìdi. Tā shí'èr suì.","mean":"No, he's my younger brother. He's twelve."},{"who":"Tom","t":"你有姐姐吗？","tr":"Nǐ yǒu jiějie ma?","mean":"Do you have an older sister?"},{"who":"Xiaoyu","t":"没有。我家有四口人。","tr":"Méiyǒu. Wǒ jiā yǒu sì kǒu rén.","mean":"No. There are four of us in my family."}],"title":"Looking at a photo"},{"type":"practice","text":"Read aloud, then describe your own family.","lines":["爸爸 妈妈 哥哥 姐姐 弟弟 妹妹","你家有几口人？","我家有三口人。","我有一个弟弟。","我没有妹妹。"]},{"type":"quiz","items":[{"q":"{{姐姐}} is your…","options":["older sister","younger sister","older brother","mum"],"answer":0},{"q":"Listen. Who is it?","say":"弟弟","options":["son","older brother","grandpa","younger brother"],"answer":3},{"q":"Your mum's mother is your…","options":["奶奶","外婆","妈妈","妹妹"],"answer":1},{"q":"How do you say 'I don't have a younger sister'?","options":["我有不妹妹。","我没有妹妹。","我不有妹妹。","我没妹妹有。"],"answer":1},{"q":"Which radical appears in 妈, 姐 and 妹?","options":["女","父","子","口"],"answer":0},{"q":"Listen. What is the question?","say":"你家有几口人","options":["How many people are in your family?","Is this your mum?","Do you have a brother?","How old are you?"],"answer":0},{"q":"Which word means 'daughter'?","options":["孩子","女儿","妻子","儿子"],"answer":1}],"title":"Quick quiz"}]},{"id":"u3-food","icon":"吃","title":"Food & Drink","subtitle":"Order a meal and talk about what you like","minutes":15,"goals":["Name common foods and drinks","Order in a restaurant","Use 碗, 杯, 瓶 and 盘","Say if something tastes good"],"blocks":[{"type":"text","text":"Food is one of the best reasons to learn Chinese! In this lesson you'll learn the dishes and drinks you'll see everywhere, and how to order them."},{"type":"vocab","items":[{"t":"米饭","tr":"mǐfàn","mean":"(cooked) rice","root":"饣 food"},{"t":"面条","tr":"miàntiáo","mean":"noodles","root":"木 wood"},{"t":"饺子","tr":"jiǎozi","mean":"dumplings","root":"饣 food"},{"t":"包子","tr":"bāozi","mean":"steamed buns","root":"子 child"},{"t":"鸡蛋","tr":"jīdàn","mean":"egg","root":"虫 insect"},{"t":"鸡肉","tr":"jīròu","mean":"chicken (meat)"},{"t":"牛肉","tr":"niúròu","mean":"beef","root":"牛 cow"},{"t":"猪肉","tr":"zhūròu","mean":"pork","root":"犭 animal"},{"t":"鱼","tr":"yú","mean":"fish","root":"鱼 fish"},{"t":"菜","tr":"cài","mean":"vegetables; a dish","root":"艹 grass"},{"t":"水果","tr":"shuǐguǒ","mean":"fruit","root":"木 tree"},{"t":"苹果","tr":"píngguǒ","mean":"apple","root":"艹 grass"},{"t":"香蕉","tr":"xiāngjiāo","mean":"banana","root":"艹 grass"}],"title":"Food"},{"type":"vocab","items":[{"t":"水","tr":"shuǐ","mean":"water","root":"水 water"},{"t":"茶","tr":"chá","mean":"tea","root":"艹 grass"},{"t":"咖啡","tr":"kāfēi","mean":"coffee","root":"口 mouth"},{"t":"牛奶","tr":"niúnǎi","mean":"milk","root":"女 woman"},{"t":"果汁","tr":"guǒzhī","mean":"juice","root":"氵 water"},{"t":"啤酒","tr":"píjiǔ","mean":"beer","root":"氵 water"}],"title":"Drinks"},{"type":"vocab","items":[{"t":"吃","tr":"chī","mean":"to eat","root":"口 mouth","example":{"t":"我吃饺子。","tr":"Wǒ chī jiǎozi.","mean":"I eat dumplings."}},{"t":"喝","tr":"hē","mean":"to drink","root":"口 mouth","example":{"t":"你喝茶吗？","tr":"Nǐ hē chá ma?","mean":"Do you drink tea?"}},{"t":"饿","tr":"è","mean":"hungry","root":"饣 food"},{"t":"渴","tr":"kě","mean":"thirsty","root":"氵 water"},{"t":"好吃","tr":"hǎochī","mean":"delicious (food)"},{"t":"好喝","tr":"hǎohē","mean":"tasty (drinks)"},{"t":"辣","tr":"là","mean":"spicy"}],"title":"Eating and drinking"},{"type":"tip","kind":"memory","text":"Radicals give clues: {{饣}} (food) in {{饭}}, {{饺}}, {{饿}}; {{口}} (mouth) in {{吃}}, {{喝}}; {{氵}} (water) in {{汁}}, {{酒}}, {{渴}}; {{艹}} (grass, plants) in {{菜}}, {{茶}}, {{苹}}."},{"type":"sentence","t":"我要一碗米饭。","tr":"Wǒ yào yì wǎn mǐfàn.","mean":"I'd like a bowl of rice.","words":[{"t":"我","mean":"I"},{"t":"要","mean":"want"},{"t":"一","mean":"one"},{"t":"碗","mean":"bowl (measure word)"},{"t":"米饭","mean":"rice"}]},{"type":"examples","items":[{"t":"一杯茶","tr":"yì bēi chá","mean":"a cup of tea","hl":"杯"},{"t":"一瓶水","tr":"yì píng shuǐ","mean":"a bottle of water","hl":"瓶"},{"t":"一碗面条","tr":"yì wǎn miàntiáo","mean":"a bowl of noodles","hl":"碗"},{"t":"一盘饺子","tr":"yì pán jiǎozi","mean":"a plate of dumplings","hl":"盘"}],"title":"Cups, bottles, bowls and plates"},{"type":"examples","items":[{"t":"服务员！","tr":"Fúwùyuán!","mean":"Excuse me! (to call the waiter)"},{"t":"请给我菜单。","tr":"Qǐng gěi wǒ càidān.","mean":"The menu, please.","hl":"菜单"},{"t":"不要辣的。","tr":"Bú yào là de.","mean":"Not spicy, please.","hl":"辣"},{"t":"很好吃！","tr":"Hěn hǎochī!","mean":"It's delicious!","hl":"好吃"},{"t":"买单！","tr":"Mǎidān!","mean":"The bill, please!"}],"title":"In a restaurant"},{"type":"dialogue","lines":[{"who":"Waiter","t":"你好！你们吃什么？","tr":"Nǐ hǎo! Nǐmen chī shénme?","mean":"Hello! What would you like to eat?"},{"who":"Mia","t":"我要一盘饺子和一碗米饭。","tr":"Wǒ yào yì pán jiǎozi hé yì wǎn mǐfàn.","mean":"A plate of dumplings and a bowl of rice, please."},{"who":"Waiter","t":"喝什么？","tr":"Hē shénme?","mean":"Anything to drink?"},{"who":"Mia","t":"一杯绿茶，谢谢。","tr":"Yì bēi lǜchá, xièxie.","mean":"A cup of green tea, thanks."},{"who":"Mia","t":"服务员，买单！","tr":"Fúwùyuán, mǎidān!","mean":"Excuse me, the bill please!"},{"who":"Waiter","t":"一共四十五块。","tr":"Yígòng sìshíwǔ kuài.","mean":"That's forty-five kuai altogether."}],"title":"Ordering dinner"},{"type":"tip","kind":"culture","text":"Dishes are usually shared in the middle of the table. Never stand your chopsticks upright in a bowl of rice: it looks like the incense sticks used for the dead. When people raise a glass they say {{干杯！}} (gānbēi, cheers!)."},{"type":"practice","text":"Read aloud as if you were ordering.","lines":["我饿了。","我要一碗面条。","我要一杯咖啡。","不要辣的。","很好吃！","买单！"]},{"type":"quiz","items":[{"q":"Listen. What is it?","say":"饺子","options":["noodles","rice","dumplings","eggs"],"answer":2},{"q":"How do you say 'a cup of tea'?","options":["一盘茶","一杯茶","一瓶茶","一碗茶"],"answer":1},{"q":"Which radical means food?","options":["艹","氵","口","饣"],"answer":3},{"q":"{{好吃}} means…","options":["hard to eat","tasty","thirsty","very hungry"],"answer":1},{"q":"How do you ask for the bill?","options":["好喝！","干杯！","买单！","菜单！"],"answer":2},{"q":"Listen. What does the customer want?","say":"我要一瓶水","options":["a plate of rice","a bottle of water","a bowl of noodles","a cup of coffee"],"answer":1},{"q":"Which is a drink?","options":["猪肉","包子","鸡蛋","果汁"],"answer":3}],"title":"Quick quiz"}]},{"id":"u3-colours","icon":"色","title":"Colours","subtitle":"Red for luck, and every colour in between","minutes":11,"goals":["Name the main colours","Use a colour before a noun","Say which colour you like","Know what colours mean in China"],"blocks":[{"type":"text","text":"Colours in Chinese are easy: most are one character + {{色}} (sè, colour). Some also carry strong cultural meanings."},{"type":"vocab","items":[{"t":"颜色","tr":"yánsè","mean":"colour","root":"页 page"},{"t":"红色","tr":"hóngsè","mean":"red","root":"纟 silk"},{"t":"黄色","tr":"huángsè","mean":"yellow"},{"t":"蓝色","tr":"lánsè","mean":"blue","root":"艹 grass"},{"t":"绿色","tr":"lǜsè","mean":"green","root":"纟 silk"},{"t":"白色","tr":"báisè","mean":"white","root":"白 white"},{"t":"黑色","tr":"hēisè","mean":"black","root":"灬 fire"},{"t":"橙色","tr":"chéngsè","mean":"orange","root":"木 tree"},{"t":"紫色","tr":"zǐsè","mean":"purple","root":"纟 silk"},{"t":"粉色","tr":"fěnsè","mean":"pink","root":"米 rice"},{"t":"灰色","tr":"huīsè","mean":"grey","root":"火 fire"},{"t":"棕色","tr":"zōngsè","mean":"brown","root":"木 tree"},{"t":"金色","tr":"jīnsè","mean":"gold","root":"金 metal"}],"title":"Colours"},{"type":"tip","kind":"memory","text":"Long ago, cloth was dyed, so many colour characters have the silk radical {{纟}}: {{红}}, {{绿}}, {{紫}} (at the bottom, as {{糸}})."},{"type":"rule","name":"Colour + noun","color":"green","desc":"A one-character colour goes straight before the noun, no {{色}} needed.","examples":[{"t":"红苹果","tr":"hóng píngguǒ","hl":"红"},{"t":"白猫","tr":"bái māo","hl":"白"},{"t":"黑车","tr":"hēi chē","hl":"黑"}]},{"type":"tip","kind":"fun","text":"Black tea is called {{红茶}} (hóngchá), 'red tea', because of the colour of the drink. Green tea is {{绿茶}} (lǜchá)."},{"type":"sentence","t":"你喜欢什么颜色？","tr":"Nǐ xǐhuan shénme yánsè?","mean":"What colour do you like?","words":[{"t":"你","mean":"you"},{"t":"喜欢","mean":"like"},{"t":"什么","mean":"what"},{"t":"颜色","mean":"colour"}]},{"type":"examples","items":[{"t":"我喜欢蓝色。","tr":"Wǒ xǐhuan lánsè.","mean":"I like blue.","hl":"蓝色"},{"t":"我的车是白色的。","tr":"Wǒ de chē shì báisè de.","mean":"My car is white.","hl":"白色"},{"t":"这件衣服是红色的。","tr":"Zhè jiàn yīfu shì hóngsè de.","mean":"This piece of clothing is red.","hl":"红色"},{"t":"我要黑的。","tr":"Wǒ yào hēi de.","mean":"I want the black one.","hl":"黑的","note":"Colour + 的 = 'the … one'."}]},{"type":"tip","kind":"culture","text":"**Red** means luck and joy: weddings, Spring Festival and the red envelopes of money called {{红包}} (hóngbāo). **White** is traditionally the colour of mourning. Never give a man a green hat: {{戴绿帽子}} means his partner is cheating!"},{"type":"tip","kind":"fun","text":"On Chinese stock market screens, **red** means prices are going up and **green** means down, the opposite of many Western screens."},{"type":"write","level":"word","items":["红色","白色","黑色","绿色"],"note":"Copy each colour and say it aloud."},{"type":"practice","text":"Say each colour, then point at something of that colour around you.","lines":["红色 黄色 蓝色 绿色","白色 黑色 灰色 粉色","你喜欢什么颜色？","我喜欢绿色。"]},{"type":"quiz","items":[{"q":"Listen. Which colour?","say":"红色","options":["green","red","yellow","blue"],"answer":1},{"q":"How do you say 'black'?","options":["黑色","蓝色","白色","灰色"],"answer":0},{"q":"{{红茶}} is…","options":["black tea","red wine","rose juice","green tea"],"answer":0,"explain":"It's called 'red tea' because of the drink's colour."},{"q":"Which colour is lucky at weddings and Spring Festival?","options":["红色","黑色","绿色","白色"],"answer":0},{"q":"Listen. What does the speaker like?","say":"我喜欢紫色","options":["pink","orange","purple","brown"],"answer":2},{"q":"Which phrase means 'white cat'?","options":["猫的白","猫白","白色是猫","白猫"],"answer":3}],"title":"Quick quiz"}]},{"id":"u3-places","icon":"车","title":"Places & Transport","subtitle":"Where are you going and how will you get there?","minutes":15,"goals":["Name places around town","Ask where something is","Use 坐, 骑 and 开 with transport","Take a taxi"],"blocks":[{"type":"text","text":"Let's get around town! You'll learn the places you need, how to ask where they are, and how to talk about buses, trains and bikes."},{"type":"vocab","items":[{"t":"学校","tr":"xuéxiào","mean":"school","root":"木 tree"},{"t":"医院","tr":"yīyuàn","mean":"hospital","root":"阝 mound"},{"t":"银行","tr":"yínháng","mean":"bank","root":"钅 metal"},{"t":"商店","tr":"shāngdiàn","mean":"shop","root":"广 shelter"},{"t":"超市","tr":"chāoshì","mean":"supermarket"},{"t":"饭馆","tr":"fànguǎn","mean":"restaurant","root":"饣 food"},{"t":"公园","tr":"gōngyuán","mean":"park","root":"囗 enclosure"},{"t":"酒店","tr":"jiǔdiàn","mean":"hotel","root":"广 shelter"},{"t":"机场","tr":"jīchǎng","mean":"airport","root":"土 earth"},{"t":"火车站","tr":"huǒchēzhàn","mean":"train station","root":"火 fire"},{"t":"洗手间","tr":"xǐshǒujiān","mean":"restroom, toilet","root":"氵 water"},{"t":"公司","tr":"gōngsī","mean":"company, office"}],"title":"Places"},{"type":"vocab","items":[{"t":"车","tr":"chē","mean":"vehicle, car","root":"车 vehicle"},{"t":"公交车","tr":"gōngjiāochē","mean":"city bus","root":"车 vehicle"},{"t":"地铁","tr":"dìtiě","mean":"subway, metro","root":"钅 metal"},{"t":"出租车","tr":"chūzūchē","mean":"taxi","root":"车 vehicle"},{"t":"火车","tr":"huǒchē","mean":"train","root":"火 fire"},{"t":"高铁","tr":"gāotiě","mean":"high-speed train","root":"钅 metal"},{"t":"飞机","tr":"fēijī","mean":"plane","root":"木 wood"},{"t":"自行车","tr":"zìxíngchē","mean":"bicycle","root":"车 vehicle"}],"title":"Transport"},{"type":"vocab","items":[{"t":"去","tr":"qù","mean":"to go","example":{"t":"我去银行。","tr":"Wǒ qù yínháng.","mean":"I'm going to the bank."}},{"t":"来","tr":"lái","mean":"to come"},{"t":"坐","tr":"zuò","mean":"to sit; to take (bus, train, plane)","root":"土 earth"},{"t":"骑","tr":"qí","mean":"to ride (bike, horse)","root":"马 horse"},{"t":"开车","tr":"kāichē","mean":"to drive","root":"车 vehicle"},{"t":"走路","tr":"zǒulù","mean":"to walk","root":"足 foot"},{"t":"在","tr":"zài","mean":"to be at, to be in","root":"土 earth"},{"t":"哪儿","tr":"nǎr","mean":"where","root":"口 mouth"}],"title":"Verbs for getting around"},{"type":"rule","name":"坐, 骑 or 开?","color":"blue","desc":"You {{坐}} (sit in) buses, subways, taxis, trains and planes. You {{骑}} (sit astride) bikes, motorbikes and horses. You {{开}} (drive) a car yourself.","examples":[{"t":"坐地铁","tr":"zuò dìtiě","hl":"坐"},{"t":"坐飞机","tr":"zuò fēijī","hl":"坐"},{"t":"骑自行车","tr":"qí zìxíngchē","hl":"骑"},{"t":"开车","tr":"kāichē","hl":"开"}]},{"type":"tip","kind":"memory","text":"{{骑}} has the horse radical {{马}}: you ride a bike the way you ride a horse."},{"type":"sentence","t":"你去哪儿？","tr":"Nǐ qù nǎr?","mean":"Where are you going?","words":[{"t":"你","mean":"you"},{"t":"去","mean":"go"},{"t":"哪儿","mean":"where"}]},{"type":"sentence","t":"我坐地铁去学校。","tr":"Wǒ zuò dìtiě qù xuéxiào.","mean":"I take the subway to school.","words":[{"t":"我","mean":"I"},{"t":"坐","mean":"take (sit on)"},{"t":"地铁","mean":"subway"},{"t":"去","mean":"go to"},{"t":"学校","mean":"school"}],"note":"'How' comes before 'where': first the subway, then the school."},{"type":"examples","items":[{"t":"请问，洗手间在哪儿？","tr":"Qǐngwèn, xǐshǒujiān zài nǎr?","mean":"Excuse me, where is the restroom?","hl":"在哪儿"},{"t":"银行在那儿。","tr":"Yínháng zài nàr.","mean":"The bank is over there.","hl":"那儿"},{"t":"我去超市买水果。","tr":"Wǒ qù chāoshì mǎi shuǐguǒ.","mean":"I'm going to the supermarket to buy fruit.","hl":"超市"},{"t":"我走路去公园。","tr":"Wǒ zǒulù qù gōngyuán.","mean":"I walk to the park.","hl":"走路"}],"title":"Useful sentences"},{"type":"tip","kind":"tip","text":"{{哪儿}} (nǎr) is common in the north, {{哪里}} (nǎlǐ) in the south. Both mean 'where'. Likewise {{这儿}} = here, {{那儿}} = there."},{"type":"tip","kind":"culture","text":"Taxi and ride-hailing drivers are politely called {{师傅}} (shīfu, master). China also has the world's largest high-speed rail network, so {{高铁}} is a great way to travel between cities."},{"type":"dialogue","lines":[{"who":"Driver","t":"你好，去哪儿？","tr":"Nǐ hǎo, qù nǎr?","mean":"Hello, where to?"},{"who":"Ben","t":"师傅，去火车站。远吗？","tr":"Shīfu, qù huǒchēzhàn. Yuǎn ma?","mean":"To the train station, please. Is it far?"},{"who":"Driver","t":"不太远，二十分钟。","tr":"Bú tài yuǎn, èrshí fēnzhōng.","mean":"Not too far, twenty minutes."},{"who":"Ben","t":"好的，谢谢。","tr":"Hǎo de, xièxie.","mean":"OK, thanks."},{"who":"Driver","t":"到了。三十二块。","tr":"Dào le. Sānshí'èr kuài.","mean":"Here we are. Thirty-two kuai."},{"who":"Ben","t":"给您。再见！","tr":"Gěi nín. Zàijiàn!","mean":"Here you are. Goodbye!"}],"title":"In a taxi"},{"type":"practice","text":"Read aloud. Then say how YOU get to school or work.","lines":["你去哪儿？","我去机场。","我坐公交车去公司。","我骑自行车去学校。","洗手间在哪儿？"]},{"type":"quiz","items":[{"q":"Listen. Where is the speaker going?","say":"我去机场","options":["the park","the hospital","the bank","the airport"],"answer":3},{"q":"Which verb goes with {{自行车}} (bicycle)?","options":["开","骑","坐","走"],"answer":1},{"q":"How do you say 'Where is the restroom?'","options":["洗手间去哪儿？","哪儿是洗手间吗？","你去洗手间？","洗手间在哪儿？"],"answer":3},{"q":"{{地铁}} is…","options":["a plane","a taxi","the bus","the subway"],"answer":3},{"q":"Choose the correct order: 'I take the bus to school.'","options":["我坐公交车去学校。","我去学校坐公交车。","我学校去坐公交车。","坐公交车我学校去。"],"answer":0},{"q":"Listen. What place is it?","say":"银行","options":["bank","shop","hotel","school"],"answer":0},{"q":"What do you call a taxi driver politely?","options":["师傅","老板","老师","服务员"],"answer":0}],"title":"Quick quiz"}]},{"id":"u3-objects","icon":"本","title":"Everyday Objects","subtitle":"Things around you, counted the Chinese way","minutes":14,"goals":["Name everyday objects","Ask 'What is this?'","Count things with measure words","Use 这 and 那"],"blocks":[{"type":"text","text":"In Chinese you can't say 'one book' directly. You say 'one **volume** book': {{一本书}}. These little counting words are called **measure words**. Let's meet them with the objects around you."},{"type":"vocab","items":[{"t":"书","tr":"shū","mean":"book","example":{"t":"一本书","tr":"yì běn shū","mean":"a book"}},{"t":"笔","tr":"bǐ","mean":"pen","root":"⺮ bamboo","example":{"t":"一支笔","tr":"yì zhī bǐ","mean":"a pen"}},{"t":"纸","tr":"zhǐ","mean":"paper","root":"纟 silk","example":{"t":"一张纸","tr":"yì zhāng zhǐ","mean":"a sheet of paper"}},{"t":"手机","tr":"shǒujī","mean":"mobile phone","root":"木 wood","example":{"t":"一个手机","tr":"yí gè shǒujī","mean":"a mobile phone"}},{"t":"电脑","tr":"diànnǎo","mean":"computer","root":"月 body","example":{"t":"一台电脑","tr":"yì tái diànnǎo","mean":"a computer"}},{"t":"桌子","tr":"zhuōzi","mean":"table, desk","root":"木 wood","example":{"t":"一张桌子","tr":"yì zhāng zhuōzi","mean":"a table"}},{"t":"椅子","tr":"yǐzi","mean":"chair","root":"木 wood","example":{"t":"一把椅子","tr":"yì bǎ yǐzi","mean":"a chair"}},{"t":"杯子","tr":"bēizi","mean":"cup, glass","root":"木 wood","example":{"t":"一个杯子","tr":"yí gè bēizi","mean":"a cup"}},{"t":"包","tr":"bāo","mean":"bag","example":{"t":"一个包","tr":"yí gè bāo","mean":"a bag"}},{"t":"钥匙","tr":"yàoshi","mean":"key","root":"钅 metal","example":{"t":"一把钥匙","tr":"yì bǎ yàoshi","mean":"a key"}},{"t":"雨伞","tr":"yǔsǎn","mean":"umbrella","root":"雨 rain","example":{"t":"一把雨伞","tr":"yì bǎ yǔsǎn","mean":"an umbrella"}},{"t":"衣服","tr":"yīfu","mean":"clothes","root":"衣 clothing","example":{"t":"一件衣服","tr":"yí jiàn yīfu","mean":"a piece of clothing"}},{"t":"钱包","tr":"qiánbāo","mean":"wallet, purse","root":"钅 metal","example":{"t":"一个钱包","tr":"yí gè qiánbāo","mean":"a wallet"}},{"t":"票","tr":"piào","mean":"ticket","root":"示 show","example":{"t":"两张票","tr":"liǎng zhāng piào","mean":"two tickets"}}],"title":"Things around you"},{"type":"rule","name":"Number + measure word + noun","color":"purple","desc":"Between a number and a noun you always need a measure word.","examples":[{"t":"一本书","tr":"yì běn shū","hl":"本"},{"t":"两张纸","tr":"liǎng zhāng zhǐ","hl":"张"},{"t":"三把椅子","tr":"sān bǎ yǐzi","hl":"把"}]},{"type":"table","head":["Measure word","Pinyin","Used for","Example"],"rows":[["{{个}}","gè","people and many things (the all-rounder)","{{一个杯子}}"],["{{本}}","běn","books, notebooks","{{一本书}}"],["{{张}}","zhāng","flat things: paper, tables, tickets, beds","{{两张票}}"],["{{把}}","bǎ","things with a handle: chairs, keys, umbrellas","{{一把钥匙}}"],["{{支}}","zhī","pens and pencils","{{三支笔}}"],["{{件}}","jiàn","clothes (tops, coats)","{{一件衣服}}"],["{{台}}","tái","machines: computers, TVs","{{一台电脑}}"],["{{辆}}","liàng","vehicles","{{一辆车}}"]],"title":"Common measure words"},{"type":"tip","kind":"tip","text":"Not sure which measure word to use? {{个}} is the safe default. People will understand you, and you'll pick up the others little by little."},{"type":"tip","kind":"memory","text":"{{张}} means 'to stretch out': anything flat and spread out. {{把}} means 'to hold': anything you grab by a handle."},{"type":"sentence","t":"这是什么？","tr":"Zhè shì shénme?","mean":"What's this?","words":[{"t":"这","mean":"this"},{"t":"是","mean":"is"},{"t":"什么","mean":"what"}]},{"type":"sentence","t":"那是我的手机。","tr":"Nà shì wǒ de shǒujī.","mean":"That is my phone.","words":[{"t":"那","mean":"that"},{"t":"是","mean":"is"},{"t":"我的","mean":"my"},{"t":"手机","mean":"phone"}]},{"type":"rule","name":"这 / 那 + measure word + noun","color":"orange","desc":"'This' and 'that' also need a measure word before a noun.","examples":[{"t":"这本书","tr":"zhè běn shū","hl":"这本"},{"t":"那把雨伞","tr":"nà bǎ yǔsǎn","hl":"那把"},{"t":"这件衣服","tr":"zhè jiàn yīfu","hl":"这件"}]},{"type":"examples","items":[{"t":"这本书是中文书。","tr":"Zhè běn shū shì Zhōngwén shū.","mean":"This book is a Chinese book.","hl":"这本书"},{"t":"我有两支笔。","tr":"Wǒ yǒu liǎng zhī bǐ.","mean":"I have two pens.","hl":"两支笔"},{"t":"这件衣服很漂亮。","tr":"Zhè jiàn yīfu hěn piàoliang.","mean":"This piece of clothing is very pretty.","hl":"这件"}]},{"type":"dialogue","lines":[{"who":"Mum","t":"你的钥匙呢？","tr":"Nǐ de yàoshi ne?","mean":"Where are your keys?"},{"who":"Xiaodong","t":"在包里。","tr":"Zài bāo li.","mean":"In my bag."},{"who":"Mum","t":"手机呢？","tr":"Shǒujī ne?","mean":"And your phone?"},{"who":"Xiaodong","t":"手机在桌子上。","tr":"Shǒujī zài zhuōzi shang.","mean":"My phone is on the table."},{"who":"Mum","t":"雨伞呢？今天会下雨。","tr":"Yǔsǎn ne? Jīntiān huì xià yǔ.","mean":"What about an umbrella? It's going to rain today."},{"who":"Xiaodong","t":"啊，我没有雨伞！","tr":"À, wǒ méiyǒu yǔsǎn!","mean":"Oh, I don't have an umbrella!"},{"who":"Mum","t":"给你，这把是我的。","tr":"Gěi nǐ, zhè bǎ shì wǒ de.","mean":"Here you go, this one is mine."}],"title":"Ready for school?"},{"type":"practice","text":"Point at things around you and name them with a number.","lines":["这是什么？","一本书","两支笔","三张纸","一把椅子","一台电脑"]},{"type":"selfcheck","items":["I can greet people politely and say goodbye.","I can introduce myself and ask someone's name.","I can count to 100 and ask for a price.","I can say the date and the time.","I can name family, food, colours, places and objects.","I can use 个, 本, 张 and 把."],"title":"Unit check"},{"type":"quiz","items":[{"q":"Which measure word goes with {{书}}?","options":["把","张","辆","本"],"answer":3},{"q":"Listen. What is it?","say":"一把雨伞","options":["a wallet","a key","a chair","an umbrella"],"answer":3},{"q":"{{一张票}} means…","options":["a book","a ticket","a key","a phone"],"answer":1},{"q":"How do you say 'two pens'?","options":["两笔","两支笔","二笔支","二支笔"],"answer":1},{"q":"{{这是什么？}} means…","options":["Where is it?","Who is this?","Is this yours?","What's this?"],"answer":3},{"q":"Which measure word is the safe all-rounder?","options":["支","件","台","个"],"answer":3},{"q":"Listen. Which object?","say":"电脑","options":["table","clothes","computer","mobile phone"],"answer":2}],"title":"Quick quiz"}]}]});
LC.units.push({"id":"grammar","order":4,"icon":"的","color":"indigo","title":"Grammar Made Easy","subtitle":"Build real sentences step by step: word order, questions, negatives and time","lessons":[{"id":"u4-word-order","icon":"我","title":"Word Order: Subject–Verb–Object","subtitle":"The good news: it's a lot like English","minutes":12,"goals":["Build simple subject–verb–object sentences","Use the personal pronouns","See that verbs never change","Know that there are no articles or plural -s"],"blocks":[{"type":"text","text":"Here's some great news: the basic word order of Chinese is the same as English. **Who** does **what** to **what**: subject, verb, object."},{"type":"sentence","t":"我爱你。","tr":"Wǒ ài nǐ.","mean":"I love you.","words":[{"t":"我","mean":"I"},{"t":"爱","mean":"love"},{"t":"你","mean":"you"}]},{"type":"sentence","t":"她学中文。","tr":"Tā xué Zhōngwén.","mean":"She studies Chinese.","words":[{"t":"她","mean":"she"},{"t":"学","mean":"studies"},{"t":"中文","mean":"Chinese"}]},{"type":"table","head":["Chinese","Pinyin","Meaning"],"rows":[["{{我}}","wǒ","I, me"],["{{你}}","nǐ","you"],["{{您}}","nín","you (polite)"],["{{他}}","tā","he, him"],["{{她}}","tā","she, her"],["{{它}}","tā","it"],["{{我们}}","wǒmen","we, us"],["{{你们}}","nǐmen","you (more than one)"],["{{他们}}","tāmen","they, them"]],"title":"Pronouns"},{"type":"tip","kind":"memory","text":"'I' and 'me' are the same word, {{我}}. Swap the places and the meaning swaps: {{我爱你}} (I love you) → {{你爱我}} (you love me)."},{"type":"tip","kind":"fun","text":"{{他}}, {{她}} and {{它}} all sound exactly the same: tā. Only the written character shows he, she or it."},{"type":"rule","name":"Verbs never change","color":"green","desc":"No -s, no -ed, no am/is/are. The verb stays the same for every person and every time.","examples":[{"t":"我吃","tr":"wǒ chī","hl":"吃"},{"t":"他吃","tr":"tā chī","hl":"吃"},{"t":"我们吃","tr":"wǒmen chī","hl":"吃"}]},{"type":"tip","kind":"tip","text":"There is no 'a', 'an' or 'the', and nouns have no plural -s. {{书}} can mean a book, the book or books. Only people can take {{们}}: {{老师们}} (teachers), but never 书们."},{"type":"examples","items":[{"t":"我喝茶。","tr":"Wǒ hē chá.","mean":"I drink tea.","hl":"喝"},{"t":"他看书。","tr":"Tā kàn shū.","mean":"He reads books.","hl":"看"},{"t":"我们学中文。","tr":"Wǒmen xué Zhōngwén.","mean":"We study Chinese.","hl":"学"},{"t":"妈妈做饭。","tr":"Māma zuò fàn.","mean":"Mum cooks.","hl":"做饭"}],"title":"Subject + verb + object"},{"type":"compare","items":[{"t":"我吃苹果。","label":"Same as English","desc":"I eat apples. Subject, verb, object."},{"t":"我在家吃苹果。","label":"Place moves forward","desc":"I eat apples at home. The place comes BEFORE the verb (more on this later)."}],"title":"One small difference"},{"type":"practice","text":"Read aloud and notice the order: who → does → what.","lines":["我爱你。","你爱我。","他喝咖啡。","我们学中文。","她们看书。"]},{"type":"quiz","items":[{"q":"Choose the correct sentence for 'He drinks tea.'","options":["茶他喝。","喝他茶。","他茶喝。","他喝茶。"],"answer":3},{"q":"How do you say 'they'?","options":["我们","他","他们","你们"],"answer":2},{"q":"How do you change {{我爱你}} into 'You love me'?","options":["我爱你们","爱你我","你爱你","你爱我"],"answer":3},{"q":"Listen. Who is studying Chinese?","say":"我们学中文","options":["she","they","we","I"],"answer":2},{"q":"What is the plural of {{书}} (book)?","options":["书","书子","书书","书们"],"answer":0,"explain":"Nouns don't change. 书 = book or books."},{"q":"Which pronoun means 'it'?","options":["你","他","它","她"],"answer":2},{"q":"Listen. What does it mean?","say":"妈妈做饭","options":["Mum reads.","Mum cooks.","Mum eats.","Mum drinks tea."],"answer":1}],"title":"Quick quiz"}]},{"id":"u4-shi","icon":"是","title":"是: To Be","subtitle":"Saying who and what someone is","minutes":11,"goals":["Use 是 to link two nouns","Make 是 negative with 不是","Know when NOT to use 是"],"blocks":[{"type":"text","text":"{{是}} (shì) works like 'am, is, are'. It links two nouns: 'I am a student', 'This is my book'. And it never changes!"},{"type":"sentence","t":"我是学生。","tr":"Wǒ shì xuésheng.","mean":"I am a student.","words":[{"t":"我","mean":"I"},{"t":"是","mean":"am"},{"t":"学生","mean":"student"}]},{"type":"rule","name":"A 是 B","color":"blue","desc":"Use {{是}} to say what or who something is. B is a noun.","examples":[{"t":"我是美国人。","tr":"Wǒ shì Měiguó rén.","hl":"是"},{"t":"这是我的书。","tr":"Zhè shì wǒ de shū.","hl":"是"},{"t":"她是医生。","tr":"Tā shì yīshēng.","hl":"是"}]},{"type":"sentence","t":"他不是老师。","tr":"Tā bú shì lǎoshī.","mean":"He is not a teacher.","words":[{"t":"他","mean":"he"},{"t":"不","mean":"not"},{"t":"是","mean":"is"},{"t":"老师","mean":"teacher"}],"note":"不 is said bú here, because 是 is a fourth tone."},{"type":"rule","name":"Negative: 不是","color":"red","desc":"Put {{不}} right before {{是}}.","examples":[{"t":"我不是老师。","tr":"Wǒ bú shì lǎoshī.","hl":"不是"},{"t":"这不是我的。","tr":"Zhè bú shì wǒ de.","hl":"不是"}]},{"type":"tip","kind":"warn","text":"Don't use {{是}} with adjectives like busy, tall or happy. 'I am busy' is {{我很忙}}, not 我是忙. You'll see why in the next lesson."},{"type":"tip","kind":"tip","text":"Ages, dates and prices often skip {{是}}: {{我二十岁。}} (I'm twenty.) {{今天星期五。}} (Today is Friday.) {{这个十块。}} (This one is ten kuai.)"},{"type":"vocab","items":[{"t":"医生","tr":"yīshēng","mean":"doctor","root":"匚 box"},{"t":"司机","tr":"sījī","mean":"driver","root":"木 wood"},{"t":"这","tr":"zhè","mean":"this","root":"辶 walk"},{"t":"那","tr":"nà","mean":"that","root":"阝 city"},{"t":"谁","tr":"shéi","mean":"who","root":"讠 speech"},{"t":"也","tr":"yě","mean":"also, too"}],"title":"Useful words"},{"type":"tip","kind":"memory","text":"{{也}} (also) goes before the verb, never at the end like 'too': {{我也是学生。}} = I'm a student too."},{"type":"examples","items":[{"t":"这是什么？","tr":"Zhè shì shénme?","mean":"What is this?","hl":"是"},{"t":"那是我朋友。","tr":"Nà shì wǒ péngyou.","mean":"That's my friend.","hl":"是"},{"t":"他是谁？","tr":"Tā shì shéi?","mean":"Who is he?","hl":"谁"},{"t":"他是我哥哥。","tr":"Tā shì wǒ gēge.","mean":"He's my older brother.","hl":"是"}]},{"type":"dialogue","lines":[{"who":"Leo","t":"你是老师吗？","tr":"Nǐ shì lǎoshī ma?","mean":"Are you a teacher?"},{"who":"Fang","t":"不是，我是学生。你呢？","tr":"Bú shì, wǒ shì xuésheng. Nǐ ne?","mean":"No, I'm a student. And you?"},{"who":"Leo","t":"我是医生。","tr":"Wǒ shì yīshēng.","mean":"I'm a doctor."},{"who":"Fang","t":"他也是医生吗？","tr":"Tā yě shì yīshēng ma?","mean":"Is he a doctor too?"},{"who":"Leo","t":"不是，他是司机。他是我弟弟。","tr":"Bú shì, tā shì sījī. Tā shì wǒ dìdi.","mean":"No, he's a driver. He's my younger brother."}]},{"type":"practice","text":"Read aloud, then say what you and your friends are.","lines":["我是学生。","我不是老师。","这是我的书。","那不是我的。","我也是美国人。"]},{"type":"quiz","items":[{"q":"How do you say 'I am not a doctor'?","options":["我没是医生。","不我是医生。","我不是医生。","我是不医生。"],"answer":2},{"q":"Which sentence is WRONG?","options":["他是老师。","我是忙。","我是学生。","我很忙。"],"answer":1,"explain":"Adjectives don't take 是. Say 我很忙."},{"q":"Listen. What does it mean?","say":"他是谁","options":["Where is he?","Is he a teacher?","Who is he?","What's this?"],"answer":2},{"q":"Where does {{也}} go in 'I'm a student too'?","options":["我也是学生。","我是也学生。","也我是学生。","我是学生也。"],"answer":0},{"q":"How is {{不是}} pronounced?","options":["bú shì","bǔ shì","bū shì","bù shì"],"answer":0,"explain":"不 becomes bú before a fourth tone."},{"q":"Which sentence can drop 是?","options":["他老师。","这我的书。","我二十岁。","我学生。"],"answer":2}],"title":"Quick quiz"}]},{"id":"u4-hen","icon":"很","title":"Adjectives with 很","subtitle":"Busy, tired, cold, beautiful","minutes":12,"goals":["Describe things with 很 + adjective","Avoid the 是 + adjective mistake","Say how much: 有点儿, 非常, 太…了","Make adjectives negative with 不"],"blocks":[{"type":"text","text":"In Chinese, adjectives behave like verbs. 'I am busy' is simply 'I busy'. But a lonely adjective sounds odd, so we add a little word in front: {{很}}."},{"type":"sentence","t":"我很忙。","tr":"Wǒ hěn máng.","mean":"I'm busy.","words":[{"t":"我","mean":"I"},{"t":"很","mean":"(very)"},{"t":"忙","mean":"busy"}],"note":"Here 很 is mostly a link word. It doesn't always mean 'very'."},{"type":"rule","name":"Subject + 很 + adjective","color":"green","desc":"No {{是}}! Use {{很}} (or another degree word) before the adjective.","examples":[{"t":"今天很冷。","tr":"Jīntiān hěn lěng.","hl":"很"},{"t":"中文很有意思。","tr":"Zhōngwén hěn yǒu yìsi.","hl":"很"},{"t":"她很高。","tr":"Tā hěn gāo.","hl":"很"}]},{"type":"tip","kind":"warn","text":"✗ 我是累。 ✓ {{我很累。}} (I'm tired.) English speakers make this mistake a lot, so watch out for it!"},{"type":"vocab","items":[{"t":"好","tr":"hǎo","mean":"good","root":"女 woman"},{"t":"忙","tr":"máng","mean":"busy","root":"忄 heart"},{"t":"累","tr":"lèi","mean":"tired","root":"糸 silk"},{"t":"冷","tr":"lěng","mean":"cold","root":"冫 ice"},{"t":"热","tr":"rè","mean":"hot","root":"灬 fire"},{"t":"高","tr":"gāo","mean":"tall, high"},{"t":"大","tr":"dà","mean":"big; old (age)"},{"t":"小","tr":"xiǎo","mean":"small; young"},{"t":"漂亮","tr":"piàoliang","mean":"beautiful, pretty","root":"氵 water"},{"t":"难","tr":"nán","mean":"difficult"},{"t":"容易","tr":"róngyì","mean":"easy","root":"宀 roof"},{"t":"有意思","tr":"yǒu yìsi","mean":"interesting","root":"心 heart"}],"title":"Common adjectives"},{"type":"tip","kind":"memory","text":"{{冷}} has two drops of ice {{冫}}, and {{热}} sits on four little flames {{灬}}."},{"type":"table","head":["Word","Pinyin","Meaning","Example"],"rows":[["{{不}}","bù","not","{{我不忙。}}"],["{{有点儿}}","yǒudiǎnr","a bit (usually negative)","{{今天有点儿冷。}}"],["{{很}}","hěn","(link) / very","{{他很高。}}"],["{{非常}}","fēicháng","extremely","{{非常好！}}"],["{{太…了}}","tài … le","too… / so…!","{{太贵了！}}"]],"title":"How much?"},{"type":"tip","kind":"tip","text":"{{太…了}} can be a complaint ({{太贵了}}, too expensive) or praise ({{太好了！}}, great!). Listen to the tone of voice."},{"type":"tip","kind":"memory","text":"Without {{很}}, an adjective sounds like a comparison: {{他高，我矮。}} = He's the tall one, I'm the short one."},{"type":"examples","items":[{"t":"我不累。","tr":"Wǒ bú lèi.","mean":"I'm not tired.","hl":"不"},{"t":"这个菜有点儿辣。","tr":"Zhège cài yǒudiǎnr là.","mean":"This dish is a bit spicy.","hl":"有点儿"},{"t":"北京非常大。","tr":"Běijīng fēicháng dà.","mean":"Beijing is extremely big.","hl":"非常"},{"t":"太好了！","tr":"Tài hǎo le!","mean":"Great!","hl":"太"}]},{"type":"dialogue","lines":[{"who":"Jia","t":"你今天忙吗？","tr":"Nǐ jīntiān máng ma?","mean":"Are you busy today?"},{"who":"Max","t":"很忙，我有点儿累。","tr":"Hěn máng, wǒ yǒudiǎnr lèi.","mean":"Very busy. I'm a bit tired."},{"who":"Jia","t":"中文难吗？","tr":"Zhōngwén nán ma?","mean":"Is Chinese difficult?"},{"who":"Max","t":"不太难，非常有意思！","tr":"Bú tài nán, fēicháng yǒu yìsi!","mean":"Not too hard, and really interesting!"}]},{"type":"practice","text":"Describe the weather and how you feel today.","lines":["今天很热。","今天有点儿冷。","我很好。","我不累。","中文很有意思！"]},{"type":"quiz","items":[{"q":"How do you say 'I'm tired'?","options":["我是累。","我很累。","我累是。","很我累。"],"answer":1},{"q":"Listen. What's the weather like?","say":"今天有点儿冷","options":["not cold","too hot","a bit cold","very hot"],"answer":2},{"q":"{{太贵了！}} means…","options":["Very cheap!","So pretty!","Not bad!","Too expensive!"],"answer":3},{"q":"Which radical in {{冷}} means ice?","options":["灬","氵","忄","冫"],"answer":3},{"q":"How do you say 'not busy'?","options":["很不","是忙","没忙","不忙"],"answer":3},{"q":"Listen. How is Chinese?","say":"中文很有意思","options":["easy","boring","interesting","difficult"],"answer":2},{"q":"{{非常好}} means…","options":["a bit good","too good to be true","not good","extremely good"],"answer":3}],"title":"Quick quiz"}]},{"id":"u4-ma","icon":"吗","title":"Yes/No Questions with 吗","subtitle":"Turn any sentence into a question","minutes":12,"goals":["Make yes/no questions with 吗","Answer without 'yes' or 'no'","Ask A-not-A questions","Bounce a question back with 呢"],"blocks":[{"type":"text","text":"This is one of the easiest things in Chinese: to ask a yes/no question, take a normal sentence and add {{吗}} (ma) at the end. Nothing moves!"},{"type":"rule","name":"Sentence + 吗？","color":"blue","desc":"Keep the word order. Just add {{吗}} and raise your eyebrows.","examples":[{"t":"你是老师吗？","tr":"Nǐ shì lǎoshī ma?","hl":"吗"},{"t":"你忙吗？","tr":"Nǐ máng ma?","hl":"吗"},{"t":"你喜欢茶吗？","tr":"Nǐ xǐhuan chá ma?","hl":"吗"}]},{"type":"sentence","t":"你喝咖啡吗？","tr":"Nǐ hē kāfēi ma?","mean":"Do you drink coffee?","words":[{"t":"你","mean":"you"},{"t":"喝","mean":"drink"},{"t":"咖啡","mean":"coffee"},{"t":"吗","mean":"(question)"}],"note":"English adds 'do' and moves words around. Chinese just adds 吗."},{"type":"tip","kind":"memory","text":"Chinese has no single word for 'yes' or 'no'. Answer with the verb: yes = repeat it, no = {{不}} + verb."},{"type":"table","head":["Question","Yes","No"],"rows":[["{{你是中国人吗？}}","{{是。}}","{{不是。}}"],["{{你忙吗？}}","{{忙。}}","{{不忙。}}"],["{{你喜欢猫吗？}}","{{喜欢。}}","{{不喜欢。}}"],["{{你有哥哥吗？}}","{{有。}}","{{没有。}}"]],"title":"Answer with the verb"},{"type":"tip","kind":"tip","text":"{{对}} (duì) means 'right, correct' and {{好}} (hǎo) means 'OK'. They're handy for agreeing, but repeating the verb is the most natural answer."},{"type":"rule","name":"A-not-A questions","color":"purple","desc":"Another way to ask: say the verb, then {{不}} + the verb. No {{吗}} needed!","examples":[{"t":"你忙不忙？","tr":"Nǐ máng bu máng?","hl":"忙不忙"},{"t":"你是不是老师？","tr":"Nǐ shì bu shì lǎoshī?","hl":"是不是"},{"t":"你去不去？","tr":"Nǐ qù bu qù?","hl":"去不去"}]},{"type":"tip","kind":"warn","text":"Never use both: ✗ 你忙不忙吗？ Choose {{你忙吗？}} or {{你忙不忙？}}"},{"type":"examples","items":[{"t":"我很好，你呢？","tr":"Wǒ hěn hǎo, nǐ ne?","mean":"I'm fine, and you?","hl":"呢"},{"t":"我是学生，他呢？","tr":"Wǒ shì xuésheng, tā ne?","mean":"I'm a student. What about him?","hl":"呢"},{"t":"我的手机呢？","tr":"Wǒ de shǒujī ne?","mean":"Where's my phone?","hl":"呢","note":"On its own, noun + 呢 asks 'where is…?'"}],"title":"Bounce it back with 呢"},{"type":"dialogue","lines":[{"who":"Nora","t":"你喜欢中国菜吗？","tr":"Nǐ xǐhuan Zhōngguó cài ma?","mean":"Do you like Chinese food?"},{"who":"Kai","t":"喜欢！你呢？","tr":"Xǐhuan! Nǐ ne?","mean":"Yes! And you?"},{"who":"Nora","t":"我也喜欢。你吃不吃辣？","tr":"Wǒ yě xǐhuan. Nǐ chī bu chī là?","mean":"Me too. Do you eat spicy food?"},{"who":"Kai","t":"不吃，我怕辣。","tr":"Bù chī, wǒ pà là.","mean":"No, I'm afraid of spicy food."},{"who":"Nora","t":"那我们吃饺子，好吗？","tr":"Nà wǒmen chī jiǎozi, hǎo ma?","mean":"Then let's have dumplings, OK?"},{"who":"Kai","t":"好！","tr":"Hǎo!","mean":"OK!"}]},{"type":"practice","text":"Ask these questions aloud, then answer them about yourself.","lines":["你忙吗？","你是学生吗？","你喜欢茶吗？","你有妹妹吗？","你去不去？"]},{"type":"quiz","items":[{"q":"Turn {{你是学生}} into a question.","options":["是你学生吗？","你是学生吗？","你吗是学生？","吗你是学生？"],"answer":1},{"q":"Someone asks {{你忙吗？}} You're not busy. You say…","options":["没忙。","不忙。","忙吗。","不是。"],"answer":1},{"q":"Listen. What is the question?","say":"你喜欢猫吗","options":["Do you like cats?","Where is the cat?","Do you have a cat?","Is this your cat?"],"answer":0},{"q":"Which question is WRONG?","options":["你是不是老师？","你去不去？","你去吗？","你去不去吗？"],"answer":3},{"q":"{{你呢？}} means…","options":["Is it you?","Are you OK?","And you?","Who are you?"],"answer":2},{"q":"{{你有哥哥吗？}} The answer is no. You say…","options":["不有。","没有。","没是。","不是。"],"answer":1},{"q":"Someone asks {{你喜欢茶吗？}} Listen to the answer. What does it mean?","say":"喜欢","options":["Yes, I like it.","I don't know.","Maybe.","No, I don't."],"answer":0}],"title":"Quick quiz"}]},{"id":"u4-question-words","icon":"谁","title":"Question Words","subtitle":"What, who, where, how many, how","minutes":15,"goals":["Use 什么, 谁, 哪儿, 几, 多少, 怎么","Keep the question word in the answer's place","Choose between 几 and 多少","Ask how to say something in Chinese"],"blocks":[{"type":"text","text":"English moves question words to the front: 'Where are you going?' Chinese doesn't! Put the question word exactly where the answer will go. That's the whole secret."},{"type":"table","head":["Word","Pinyin","Meaning","Example"],"rows":[["{{什么}}","shénme","what","{{这是什么？}}"],["{{谁}}","shéi","who","{{他是谁？}}"],["{{哪儿}} / {{哪里}}","nǎr / nǎlǐ","where","{{你去哪儿？}}"],["{{几}}","jǐ","how many (small numbers)","{{你有几个孩子？}}"],["{{多少}}","duōshao","how many, how much","{{多少钱？}}"],["{{怎么}}","zěnme","how","{{你怎么去？}}"],["{{什么时候}}","shénme shíhou","when","{{你什么时候来？}}"],["{{为什么}}","wèishénme","why","{{你为什么学中文？}}"]],"title":"The question words"},{"type":"rule","name":"Stay in place","color":"green","desc":"Write the answer sentence, then swap the answer for a question word. No change of order, and no {{吗}}.","examples":[{"t":"你去哪儿？","tr":"Nǐ qù nǎr?","hl":"哪儿"},{"t":"他是谁？","tr":"Tā shì shéi?","hl":"谁"},{"t":"你吃什么？","tr":"Nǐ chī shénme?","hl":"什么"}]},{"type":"examples","items":[{"t":"我去北京。","tr":"Wǒ qù Běijīng.","mean":"I'm going to Beijing.","hl":"北京","note":"Answers 你去哪儿？ — 北京 takes the place of 哪儿."},{"t":"他是我哥哥。","tr":"Tā shì wǒ gēge.","mean":"He's my older brother.","hl":"我哥哥","note":"Answers 他是谁？"},{"t":"我吃面条。","tr":"Wǒ chī miàntiáo.","mean":"I'm eating noodles.","hl":"面条","note":"Answers 你吃什么？"}],"title":"Questions and answers line up"},{"type":"sentence","t":"你什么时候去中国？","tr":"Nǐ shénme shíhou qù Zhōngguó?","mean":"When are you going to China?","words":[{"t":"你","mean":"you"},{"t":"什么时候","mean":"when"},{"t":"去","mean":"go"},{"t":"中国","mean":"China"}],"note":"Answer: 我明天去中国 — 'tomorrow' sits right where 'when' was."},{"type":"tip","kind":"warn","text":"Question words already make a question, so don't add {{吗}}: ✗ 你去哪儿吗？"},{"type":"tip","kind":"tip","text":"{{谁}} is usually said shéi in everyday speech; you may also hear shuí."},{"type":"rule","name":"几 or 多少?","color":"orange","desc":"Use {{几}} when you expect a small number (about 1–10) and add a measure word. Use {{多少}} for any number; the measure word is optional.","examples":[{"t":"你家有几口人？","tr":"Nǐ jiā yǒu jǐ kǒu rén?","hl":"几"},{"t":"你们学校有多少学生？","tr":"Nǐmen xuéxiào yǒu duōshao xuésheng?","hl":"多少"},{"t":"现在几点？","tr":"Xiànzài jǐ diǎn?","hl":"几"}]},{"type":"tip","kind":"culture","text":"To ask a child's age, say {{你几岁？}} To ask an adult, say {{你多大？}} (Nǐ duō dà?). For an older person, {{您多大年纪？}} (Nín duō dà niánjì?) is most polite."},{"type":"examples","items":[{"t":"这个用中文怎么说？","tr":"Zhège yòng Zhōngwén zěnme shuō?","mean":"How do you say this in Chinese?","hl":"怎么说"},{"t":"去火车站怎么走？","tr":"Qù huǒchēzhàn zěnme zǒu?","mean":"How do I get to the train station?","hl":"怎么走"},{"t":"这个菜怎么样？","tr":"Zhège cài zěnmeyàng?","mean":"How is this dish?","hl":"怎么样"},{"t":"你为什么学中文？","tr":"Nǐ wèishénme xué Zhōngwén?","mean":"Why are you learning Chinese?","hl":"为什么"}],"title":"怎么 and friends"},{"type":"tip","kind":"memory","text":"{{怎么}} + verb = 'how to do it': {{怎么说}} (how to say), {{怎么走}} (how to get there), {{怎么写}} (how to write)."},{"type":"dialogue","lines":[{"who":"Lily","t":"你叫什么名字？","tr":"Nǐ jiào shénme míngzi?","mean":"What's your name?"},{"who":"Sam","t":"我叫山姆。你是哪里人？","tr":"Wǒ jiào Shānmǔ. Nǐ shì nǎlǐ rén?","mean":"I'm Sam. Where are you from?"},{"who":"Lily","t":"我是上海人。你为什么学中文？","tr":"Wǒ shì Shànghǎi rén. Nǐ wèishénme xué Zhōngwén?","mean":"I'm from Shanghai. Why are you learning Chinese?"},{"who":"Sam","t":"因为我喜欢中国菜！","tr":"Yīnwèi wǒ xǐhuan Zhōngguó cài!","mean":"Because I love Chinese food!"},{"who":"Lily","t":"哈哈！你什么时候来上海？","tr":"Hāha! Nǐ shénme shíhou lái Shànghǎi?","mean":"Haha! When are you coming to Shanghai?"},{"who":"Sam","t":"我八月去。","tr":"Wǒ bāyuè qù.","mean":"I'm going in August."}]},{"type":"practice","text":"Ask these questions aloud, then answer each one.","lines":["你叫什么名字？","他是谁？","你去哪儿？","现在几点？","这个多少钱？","你怎么去学校？"]},{"type":"quiz","items":[{"q":"{{谁}} means…","options":["what","when","who","where"],"answer":2},{"q":"Answer {{你去哪儿？}} with 'the bank':","options":["我去银行。","去银行吗。","我去哪儿银行。","银行我去。"],"answer":0},{"q":"Listen. What is the question?","say":"多少钱","options":["What time is it?","Where is it?","Who is it?","How much is it?"],"answer":3},{"q":"Which question is WRONG?","options":["你吃什么吗？","他是谁？","你去哪儿？","你吃什么？"],"answer":0,"explain":"Question words don't take 吗."},{"q":"How do you ask a child's age?","options":["你哪儿岁？","你几岁？","你什么岁？","你多少岁吗？"],"answer":1},{"q":"Listen. What is the speaker asking?","say":"这个用中文怎么说","options":["how to say something","why you study","when you arrive","where to go"],"answer":0},{"q":"{{为什么}} means…","options":["when","why","which","how"],"answer":1},{"q":"To ask how many students a big school has, use…","options":["怎么","几","哪","多少"],"answer":3}],"title":"Quick quiz"}]},{"id":"u4-bu-mei","icon":"不","title":"Saying No: 不 vs 没","subtitle":"Two little words for 'not'","minutes":13,"goals":["Use 不 for habits, wishes, the future and adjectives","Use 没 for things that didn't happen","Always say 没有, never 不有","Hear the tone change of 不"],"blocks":[{"type":"text","text":"Chinese has two words for 'not': {{不}} (bù) and {{没}} (méi). Choosing the right one is easier than it looks: ask yourself 'Did it happen?' and 'Is it 有?'"},{"type":"compare","items":[{"t":"不","label":"bù — don't, won't, am not","desc":"Habits, wishes, the future, adjectives and 是."},{"t":"没","label":"méi — didn't, haven't","desc":"Things that did not happen, and 没有 (don't have)."}],"title":"Two kinds of 'not'"},{"type":"rule","name":"不 + verb / adjective","color":"red","desc":"For what you normally do, want to do, will do, or what something is like.","examples":[{"t":"我不吃肉。","tr":"Wǒ bù chī ròu.","hl":"不"},{"t":"明天我不去。","tr":"Míngtiān wǒ bú qù.","hl":"不"},{"t":"今天不冷。","tr":"Jīntiān bù lěng.","hl":"不"},{"t":"他不是老师。","tr":"Tā bú shì lǎoshī.","hl":"不"}]},{"type":"rule","name":"没 + verb","color":"orange","desc":"For something that did not happen (yet).","examples":[{"t":"我没吃早饭。","tr":"Wǒ méi chī zǎofàn.","hl":"没"},{"t":"他昨天没来。","tr":"Tā zuótiān méi lái.","hl":"没"},{"t":"我还没去过。","tr":"Wǒ hái méi qù guo.","hl":"没"}]},{"type":"sentence","t":"我今天没喝咖啡。","tr":"Wǒ jīntiān méi hē kāfēi.","mean":"I didn't drink coffee today.","words":[{"t":"我","mean":"I"},{"t":"今天","mean":"today"},{"t":"没","mean":"didn't"},{"t":"喝","mean":"drink"},{"t":"咖啡","mean":"coffee"}]},{"type":"examples","items":[{"t":"我不喝咖啡。","tr":"Wǒ bù hē kāfēi.","mean":"I don't drink coffee.","hl":"不","note":"A habit: I never drink it."},{"t":"我没喝咖啡。","tr":"Wǒ méi hē kāfēi.","mean":"I didn't drink coffee.","hl":"没","note":"A fact: it didn't happen."}],"title":"Feel the difference"},{"type":"tip","kind":"warn","text":"{{有}} (to have) is always made negative with {{没}}: {{我没有钱。}} (I have no money.) ✗ 我不有钱。"},{"type":"tip","kind":"tip","text":"Remember: {{不}} becomes bú before a fourth tone: {{不去}} bú qù, {{不是}} bú shì, {{不要}} bú yào. Before other tones it stays bù: {{不吃}} bù chī."},{"type":"tip","kind":"memory","text":"Think of {{没}} as 'no event'. If you could have taken a photo of it happening and you can't, use {{没}}."},{"type":"examples","items":[{"t":"你吃饭了吗？","tr":"Nǐ chī fàn le ma?","mean":"Have you eaten?"},{"t":"还没吃。","tr":"Hái méi chī.","mean":"Not yet.","hl":"没"},{"t":"你明天来吗？","tr":"Nǐ míngtiān lái ma?","mean":"Are you coming tomorrow?"},{"t":"不来。","tr":"Bù lái.","mean":"No, I'm not.","hl":"不"}],"title":"Short answers"},{"type":"practice","text":"Read each pair aloud and think about the difference.","lines":["我不吃肉。","我没吃肉。","他不来。","他没来。","我没有钱。"]},{"type":"quiz","items":[{"q":"'I don't eat meat' (I'm vegetarian):","options":["我没吃肉。","我不有肉。","我没有吃。","我不吃肉。"],"answer":3},{"q":"'He didn't come yesterday':","options":["他昨天没来。","他昨天不有来。","他昨天不来。","他没昨天来。"],"answer":0},{"q":"Which is correct for 'I don't have a car'?","options":["我不车有。","我不有车。","我没有车。","我没是车。"],"answer":2},{"q":"Listen. What does it mean?","say":"我没吃早饭","options":["I don't eat breakfast.","I want breakfast.","I didn't eat breakfast.","I'll eat breakfast."],"answer":2},{"q":"How is {{不去}} pronounced?","options":["bù qù","bú qù","bǔ qù","bū qù"],"answer":1},{"q":"'It isn't cold today':","options":["今天不冷。","今天不有冷。","今天没冷。","今天冷不。"],"answer":0},{"q":"Listen. Is the speaker coming?","say":"我明天不来","options":["Yes, coming","Came yesterday","Didn't come","No, not coming"],"answer":3}],"title":"Quick quiz"}]},{"id":"u4-measure-words","icon":"个","title":"Measure Words","subtitle":"个, 本, 杯, 张, 只, 件 and friends","minutes":14,"goals":["Use number + measure word + noun","Choose the right measure word","Use 这/那/哪 with measure words","Use 两, not 二, before measure words"],"blocks":[{"type":"text","text":"You met measure words in Unit 3. Now let's master them. Every time you count something, or say 'this one' or 'that one', a measure word slips in between."},{"type":"rule","name":"Number / 这 / 那 / 哪 + measure word + noun","color":"purple","desc":"The measure word always sits right before the noun.","examples":[{"t":"三个人","tr":"sān gè rén","hl":"个"},{"t":"这本书","tr":"zhè běn shū","hl":"本"},{"t":"那杯咖啡","tr":"nà bēi kāfēi","hl":"杯"},{"t":"哪件衣服？","tr":"nǎ jiàn yīfu?","hl":"件"}]},{"type":"table","head":["Measure word","Pinyin","Used for","Examples"],"rows":[["{{个}}","gè","people and general things","{{一个人}}, {{两个苹果}}"],["{{本}}","běn","books, magazines, notebooks","{{三本书}}"],["{{杯}}","bēi","cups and glasses of a drink","{{一杯水}}, {{两杯茶}}"],["{{张}}","zhāng","flat things: paper, tickets, photos, beds, tables","{{一张床}}"],["{{只}}","zhī","most animals; one of a pair","{{一只猫}}, {{一只手}}"],["{{件}}","jiàn","clothes for the top half; matters","{{一件衬衫}}, {{一件事}}"],["{{条}}","tiáo","long, bendy things: fish, roads, trousers","{{一条鱼}}, {{一条裤子}}"],["{{辆}}","liàng","vehicles","{{一辆车}}"],["{{位}}","wèi","people (polite)","{{三位老师}}"]],"title":"The most useful measure words"},{"type":"tip","kind":"memory","text":"Picture them: {{张}} = a flat sheet, {{条}} = a ribbon, {{只}} = a single little animal, {{本}} = a book with a spine, {{杯}} = a cup ({{木}}: cups were once wooden)."},{"type":"rule","name":"2 = 两 before a measure word","color":"red","desc":"Counting things, use {{两}} (liǎng). Use {{二}} (èr) in counting, phone numbers and in 12, 20, 22…","examples":[{"t":"两个人","tr":"liǎng gè rén","hl":"两"},{"t":"两本书","tr":"liǎng běn shū","hl":"两"},{"t":"十二个人","tr":"shí'èr gè rén","hl":"二"}]},{"type":"sentence","t":"我买两本书。","tr":"Wǒ mǎi liǎng běn shū.","mean":"I'm buying two books.","words":[{"t":"我","mean":"I"},{"t":"买","mean":"buy"},{"t":"两","mean":"two"},{"t":"本","mean":"(measure word for books)"},{"t":"书","mean":"books"}]},{"type":"sentence","t":"这只猫很可爱。","tr":"Zhè zhī māo hěn kě'ài.","mean":"This cat is very cute.","words":[{"t":"这","mean":"this"},{"t":"只","mean":"(measure word for animals)"},{"t":"猫","mean":"cat"},{"t":"很","mean":"very"},{"t":"可爱","mean":"cute"}]},{"type":"tip","kind":"tip","text":"In fast speech {{个}} is often said with a light, neutral tone: 'ge'. And if you forget a measure word, {{个}} will usually still be understood."},{"type":"tip","kind":"warn","text":"{{只}} (zhī) and {{支}} (zhī, for pens) sound the same. {{一只狗}} = a dog, {{一支笔}} = a pen. You may also hear {{一条狗}} for a dog."},{"type":"examples","items":[{"t":"我要一杯咖啡。","tr":"Wǒ yào yì bēi kāfēi.","mean":"I'd like a coffee.","hl":"杯"},{"t":"这张照片很漂亮。","tr":"Zhè zhāng zhàopiàn hěn piàoliang.","mean":"This photo is beautiful.","hl":"张"},{"t":"我有一件事。","tr":"Wǒ yǒu yí jiàn shì.","mean":"There's something I need to tell you.","hl":"件"},{"t":"这条路很长。","tr":"Zhè tiáo lù hěn cháng.","mean":"This road is very long.","hl":"条"},{"t":"你要哪个？","tr":"Nǐ yào nǎge?","mean":"Which one do you want?","hl":"哪个"}]},{"type":"practice","text":"Count the things around you with the right measure word.","lines":["一个人","两本书","三杯水","四张纸","五只猫","一件衣服","一条鱼"]},{"type":"quiz","items":[{"q":"Fill the gap: {{一 ___ 书}}","options":["只","件","张","本"],"answer":3},{"q":"Fill the gap: {{一 ___ 猫}}","options":["只","本","杯","张"],"answer":0},{"q":"Fill the gap: {{两 ___ 衣服}}","options":["辆","本","件","张"],"answer":2},{"q":"Choose the correct way to say 'two people'.","options":["二人们","两人个","两个人","二个人"],"answer":2},{"q":"Fill the gap: {{三 ___ 咖啡}}","options":["张","本","杯","只"],"answer":2},{"q":"Listen. What is it?","say":"一辆车","options":["a book","a car","a cat","a fish"],"answer":1},{"q":"Which measure word is for long, bendy things like fish and trousers?","options":["杯","张","位","条"],"answer":3},{"q":"Listen. How many tickets?","say":"两张票","options":["3","10","2","4"],"answer":2}],"title":"Quick quiz"}]},{"id":"u4-de","icon":"的","title":"的: Possession & Description","subtitle":"My, your, the teacher's… and 'the red one'","minutes":12,"goals":["Show possession with 的","Know when to drop 的","Use adjective + 的 + noun","Ask 'Whose is it?'"],"blocks":[{"type":"text","text":"{{的}} (de) is the most common character in Chinese. Its main job is just like English **'s**: {{老师的书}} = the teacher's book."},{"type":"rule","name":"A 的 B = A's B","color":"blue","desc":"The owner comes first, then {{的}}, then the thing.","examples":[{"t":"我的书","tr":"wǒ de shū","hl":"的"},{"t":"老师的电脑","tr":"lǎoshī de diànnǎo","hl":"的"},{"t":"妈妈的车","tr":"māma de chē","hl":"的"},{"t":"中国的茶","tr":"Zhōngguó de chá","hl":"的"}]},{"type":"sentence","t":"这是我朋友的手机。","tr":"Zhè shì wǒ péngyou de shǒujī.","mean":"This is my friend's phone.","words":[{"t":"这","mean":"this"},{"t":"是","mean":"is"},{"t":"我","mean":"my"},{"t":"朋友","mean":"friend"},{"t":"的","mean":"'s"},{"t":"手机","mean":"phone"}]},{"type":"table","head":["Chinese","Pinyin","Meaning"],"rows":[["{{我的}}","wǒ de","my, mine"],["{{你的}}","nǐ de","your, yours"],["{{他的}} / {{她的}}","tā de","his / her, hers"],["{{我们的}}","wǒmen de","our, ours"],["{{你们的}}","nǐmen de","your, yours (plural)"],["{{他们的}}","tāmen de","their, theirs"]],"title":"My, your, his…"},{"type":"tip","kind":"memory","text":"Pronoun + {{的}} gives both 'my' AND 'mine': {{我的书}} (my book), {{这是我的。}} (This is mine.)"},{"type":"rule","name":"Drop 的 for close people and groups","color":"gray","desc":"With family, close friends, and groups you belong to, {{的}} is usually left out.","examples":[{"t":"我妈妈","tr":"wǒ māma"},{"t":"我朋友","tr":"wǒ péngyou"},{"t":"我们学校","tr":"wǒmen xuéxiào"},{"t":"我家","tr":"wǒ jiā"}]},{"type":"rule","name":"Adjective + 的 + noun","color":"green","desc":"Longer adjectives, or adjectives with {{很}}, take {{的}} before the noun. Short one-character adjectives usually don't.","examples":[{"t":"很好的朋友","tr":"hěn hǎo de péngyou","hl":"的"},{"t":"漂亮的衣服","tr":"piàoliang de yīfu","hl":"的"},{"t":"好朋友","tr":"hǎo péngyou"},{"t":"新手机","tr":"xīn shǒujī"}]},{"type":"tip","kind":"tip","text":"Leave out the noun and {{的}} means 'the … one': {{红的}} = the red one, {{我的}} = mine, {{贵的}} = the expensive one."},{"type":"examples","items":[{"t":"这本书是谁的？","tr":"Zhè běn shū shì shéi de?","mean":"Whose book is this?","hl":"谁的"},{"t":"是我的。","tr":"Shì wǒ de.","mean":"It's mine.","hl":"我的"},{"t":"我要红的。","tr":"Wǒ yào hóng de.","mean":"I want the red one.","hl":"红的"},{"t":"她是我最好的朋友。","tr":"Tā shì wǒ zuì hǎo de péngyou.","mean":"She's my best friend.","hl":"的"}]},{"type":"dialogue","lines":[{"who":"Teacher","t":"这是谁的杯子？","tr":"Zhè shì shéi de bēizi?","mean":"Whose cup is this?"},{"who":"Amy","t":"不是我的。我的杯子是红的。","tr":"Bú shì wǒ de. Wǒ de bēizi shì hóng de.","mean":"It's not mine. My cup is the red one."},{"who":"Ben","t":"是我的！谢谢老师。","tr":"Shì wǒ de! Xièxie lǎoshī.","mean":"It's mine! Thank you, teacher."},{"who":"Teacher","t":"那这本书呢？","tr":"Nà zhè běn shū ne?","mean":"And this book?"},{"who":"Amy","t":"那是我哥哥的。","tr":"Nà shì wǒ gēge de.","mean":"That's my brother's."}],"title":"Lost property"},{"type":"practice","text":"Point at things and say whose they are.","lines":["我的手机","你的书","老师的电脑","我妈妈","这是谁的？","是我的。"]},{"type":"quiz","items":[{"q":"How do you say 'the teacher's car'?","options":["的老师车","老师车的","车的老师","老师的车"],"answer":3},{"q":"Listen. What is the question?","say":"这是谁的","options":["Where is this?","Who is this?","What is this?","Whose is this?"],"answer":3},{"q":"Which is most natural for 'my mum'?","options":["妈妈我的","我妈妈","妈妈的我","我的的妈妈"],"answer":1,"explain":"With close family 的 is usually dropped."},{"q":"{{红的}} means…","options":["the red one","red tea","very red","not red"],"answer":0},{"q":"Which one needs 的?","options":["我___妈妈","新___手机","好___朋友","很好___朋友"],"answer":3},{"q":"{{这是我的。}} means…","options":["I am here.","It's my turn.","This is mine.","This is me."],"answer":2}],"title":"Quick quiz"}]},{"id":"u4-zai","icon":"在","title":"在: Where & What's Happening","subtitle":"Location, place of action, and actions in progress","minutes":14,"goals":["Say where someone or something is","Use place words like 上, 里, 旁边","Say where you do something","Talk about actions in progress"],"blocks":[{"type":"text","text":"{{在}} (zài) is a hard-working little word with three jobs: 'to be at', 'at/in (a place)' and '-ing' (doing right now). Let's take them one at a time."},{"type":"rule","name":"Job 1: X 在 place","color":"blue","desc":"{{在}} is the verb 'to be at / in'.","examples":[{"t":"我在家。","tr":"Wǒ zài jiā.","hl":"在"},{"t":"书在桌子上。","tr":"Shū zài zhuōzi shang.","hl":"在"},{"t":"我妈妈在上海。","tr":"Wǒ māma zài Shànghǎi.","hl":"在"}]},{"type":"vocab","items":[{"t":"上","tr":"shàng","mean":"on, above","root":"一 one"},{"t":"下","tr":"xià","mean":"under, below","root":"一 one"},{"t":"里","tr":"lǐ","mean":"inside","root":"里 village"},{"t":"外","tr":"wài","mean":"outside","root":"夕 evening"},{"t":"旁边","tr":"pángbiān","mean":"next to","root":"方 square"},{"t":"前面","tr":"qiánmiàn","mean":"in front","root":"刂 knife"},{"t":"后面","tr":"hòumiàn","mean":"behind","root":"口 mouth"},{"t":"这儿","tr":"zhèr","mean":"here","root":"辶 walk"},{"t":"那儿","tr":"nàr","mean":"there","root":"阝 city"}],"title":"Place words"},{"type":"tip","kind":"warn","text":"The place word comes AFTER the thing: {{桌子上}} = 'table-on' = on the table; {{包里}} = 'bag-inside' = in the bag. English does it the other way round."},{"type":"rule","name":"Job 2: 在 + place + verb","color":"green","desc":"To say WHERE you do something, put {{在}} + place before the verb.","examples":[{"t":"我在银行工作。","tr":"Wǒ zài yínháng gōngzuò.","hl":"在银行"},{"t":"他在家看电视。","tr":"Tā zài jiā kàn diànshì.","hl":"在家"}]},{"type":"sentence","t":"我在学校吃午饭。","tr":"Wǒ zài xuéxiào chī wǔfàn.","mean":"I have lunch at school.","words":[{"t":"我","mean":"I"},{"t":"在","mean":"at"},{"t":"学校","mean":"school"},{"t":"吃","mean":"eat"},{"t":"午饭","mean":"lunch"}],"note":"English: I eat lunch AT SCHOOL. Chinese: I AT SCHOOL eat lunch."},{"type":"rule","name":"Job 3: 在 + verb = doing now","color":"purple","desc":"Put {{在}} (or {{正在}}) right before the verb for an action in progress. {{呢}} at the end makes it sound natural.","examples":[{"t":"我在吃饭。","tr":"Wǒ zài chī fàn.","hl":"在"},{"t":"他在看电视。","tr":"Tā zài kàn diànshì.","hl":"在"},{"t":"她正在睡觉呢。","tr":"Tā zhèngzài shuìjiào ne.","hl":"正在"}]},{"type":"sentence","t":"你在做什么？","tr":"Nǐ zài zuò shénme?","mean":"What are you doing?","words":[{"t":"你","mean":"you"},{"t":"在","mean":"(doing now)"},{"t":"做","mean":"do"},{"t":"什么","mean":"what"}]},{"type":"tip","kind":"tip","text":"Negatives: {{不在}} = not at a place ({{他不在家。}} He's not home). {{没在}} = not doing it right now ({{我没在看电视。}} I'm not watching TV)."},{"type":"dialogue","lines":[{"who":"Xiaoli","t":"喂，你在哪儿？","tr":"Wéi, nǐ zài nǎr?","mean":"Hello, where are you?"},{"who":"Dan","t":"我在家。","tr":"Wǒ zài jiā.","mean":"I'm at home."},{"who":"Xiaoli","t":"你在做什么？","tr":"Nǐ zài zuò shénme?","mean":"What are you doing?"},{"who":"Dan","t":"我在做饭。你呢？","tr":"Wǒ zài zuò fàn. Nǐ ne?","mean":"I'm cooking. And you?"},{"who":"Xiaoli","t":"我在超市买东西。","tr":"Wǒ zài chāoshì mǎi dōngxi.","mean":"I'm shopping at the supermarket."},{"who":"Dan","t":"那你买一点儿水果吧！","tr":"Nà nǐ mǎi yìdiǎnr shuǐguǒ ba!","mean":"Then buy some fruit!"}],"title":"On the phone"},{"type":"tip","kind":"culture","text":"On the phone, Chinese people answer with {{喂？}} (wéi), a 'hello' used only for calls."},{"type":"practice","text":"Say where you are and what you're doing right now.","lines":["我在家。","我在学中文。","手机在桌子上。","钥匙在包里。","你在做什么？"]},{"type":"quiz","items":[{"q":"How do you say 'The book is on the table'?","options":["书在桌子上。","在桌子上书。","书上在桌子。","书在上桌子。"],"answer":0},{"q":"Listen. What is he doing?","say":"他在看电视","options":["sleeping","watching TV","working","eating"],"answer":1},{"q":"Choose the correct order: 'I work at a bank.'","options":["我银行在工作。","在我银行工作。","我在银行工作。","我工作在银行。"],"answer":2},{"q":"{{你在做什么？}} means…","options":["What do you want?","What do you do?","What are you doing?","Where are you?"],"answer":2},{"q":"{{里}} means…","options":["inside","behind","outside","on"],"answer":0},{"q":"Listen. Where is the speaker?","say":"我在家","options":["at the shop","at work","at school","at home"],"answer":3},{"q":"'He's not at home' is…","options":["他不在家。","他没是家。","他不有家。","他在不家。"],"answer":0}],"title":"Quick quiz"}]},{"id":"u4-le","icon":"了","title":"了: Completed Actions","subtitle":"Done, finished, and things that have changed","minutes":14,"goals":["Use verb + 了 for completed actions","Ask 'Have you…?' with 了吗","Make negatives with 没 (no 了)","Use 了 at the end for a change"],"blocks":[{"type":"text","text":"Chinese verbs have no past tense. Instead, a tiny word {{了}} (le) tells you an action is **done**. It's not exactly 'past', it's 'completed'."},{"type":"rule","name":"Verb + 了","color":"green","desc":"{{了}} after a verb shows the action is complete. It is very common with a number or amount.","examples":[{"t":"我吃了。","tr":"Wǒ chī le.","hl":"了"},{"t":"我买了三本书。","tr":"Wǒ mǎi le sān běn shū.","hl":"了"},{"t":"他喝了两杯咖啡。","tr":"Tā hē le liǎng bēi kāfēi.","hl":"了"}]},{"type":"sentence","t":"我昨天看了一个电影。","tr":"Wǒ zuótiān kàn le yí gè diànyǐng.","mean":"I watched a film yesterday.","words":[{"t":"我","mean":"I"},{"t":"昨天","mean":"yesterday"},{"t":"看","mean":"watch"},{"t":"了","mean":"(done)"},{"t":"一","mean":"one"},{"t":"个","mean":"(measure word)"},{"t":"电影","mean":"film"}]},{"type":"rule","name":"Questions and negatives","color":"orange","desc":"Ask with {{了吗？}} or {{了没有？}} Answer yes with verb + {{了}}. For no, use {{没}} + verb, and drop {{了}}!","examples":[{"t":"你吃饭了吗？","tr":"Nǐ chī fàn le ma?","hl":"了吗"},{"t":"吃了。","tr":"Chī le.","hl":"了"},{"t":"我没吃。","tr":"Wǒ méi chī.","hl":"没"},{"t":"还没吃。","tr":"Hái méi chī.","hl":"还没"}]},{"type":"tip","kind":"warn","text":"✗ 我没吃了。 ✓ {{我没吃。}} {{没}} and {{了}} don't go together."},{"type":"tip","kind":"memory","text":"Think of {{了}} as a tick ✓ on your to-do list: {{我买了}} = 'buy ✓'."},{"type":"rule","name":"了 at the end: something changed","color":"purple","desc":"At the end of a sentence, {{了}} shows a new situation: 'now…'.","examples":[{"t":"我饿了。","tr":"Wǒ è le.","hl":"了"},{"t":"下雨了！","tr":"Xià yǔ le!","hl":"了"},{"t":"我二十岁了。","tr":"Wǒ èrshí suì le.","hl":"了"},{"t":"他是老师了。","tr":"Tā shì lǎoshī le.","hl":"了"}]},{"type":"tip","kind":"tip","text":"Not every past sentence needs {{了}}. Descriptions and habits in the past don't take it: {{昨天很冷。}} (It was cold yesterday.) {{我以前是老师。}} (I used to be a teacher.)"},{"type":"vocab","items":[{"t":"电影","tr":"diànyǐng","mean":"film, movie","root":"彡 hair"},{"t":"早饭","tr":"zǎofàn","mean":"breakfast","root":"饣 food"},{"t":"午饭","tr":"wǔfàn","mean":"lunch","root":"饣 food"},{"t":"晚饭","tr":"wǎnfàn","mean":"dinner","root":"饣 food"},{"t":"下雨","tr":"xià yǔ","mean":"to rain","root":"雨 rain"},{"t":"还没","tr":"hái méi","mean":"not yet"}],"title":"Words for this lesson"},{"type":"dialogue","lines":[{"who":"Mum","t":"你吃早饭了吗？","tr":"Nǐ chī zǎofàn le ma?","mean":"Have you had breakfast?"},{"who":"Leo","t":"吃了。我吃了两个包子。","tr":"Chī le. Wǒ chī le liǎng gè bāozi.","mean":"Yes. I had two steamed buns."},{"who":"Mum","t":"你做作业了吗？","tr":"Nǐ zuò zuòyè le ma?","mean":"Have you done your homework?"},{"who":"Leo","t":"还没做……","tr":"Hái méi zuò…","mean":"Not yet…"},{"who":"Mum","t":"快做吧！八点了！","tr":"Kuài zuò ba! Bā diǎn le!","mean":"Do it quickly! It's eight o'clock already!"}],"title":"Morning at home"},{"type":"practice","text":"Read aloud. Then say three things you did today.","lines":["我吃了。","我买了一本书。","你吃饭了吗？","还没吃。","下雨了！","我饿了。"]},{"type":"quiz","items":[{"q":"How do you say 'I bought three books'?","options":["我买三了本书。","我了买三本书。","我买了三本书。","我买三本书了了。"],"answer":2},{"q":"Which sentence is WRONG?","options":["我没吃。","我吃了。","我还没吃。","我没吃了。"],"answer":3},{"q":"Listen. What happened?","say":"下雨了","options":["It's sunny.","It stopped raining.","It will rain.","It started raining."],"answer":3},{"q":"Someone asks {{你吃饭了吗？}} You haven't eaten yet. You say…","options":["吃了没。","没吃了。","不吃了。","还没吃。"],"answer":3},{"q":"{{我饿了}} means…","options":["I was hungry.","I ate.","I'm not hungry.","I'm hungry (now)."],"answer":3},{"q":"Listen. What did the speaker do?","say":"我看了一个电影","options":["ate breakfast","watched a film","bought a book","drank coffee"],"answer":1},{"q":"Which sentence does NOT need 了?","options":["我吃___两个包子。","下雨___！","我买___三本书。","昨天很冷___。"],"answer":3}],"title":"Quick quiz"}]},{"id":"u4-modals","icon":"想","title":"Want, Can, May: 想 要 会 能 可以","subtitle":"Wishes, skills, abilities and permission","minutes":16,"goals":["Say what you want with 想 and 要","Say what you can do with 会 and 能","Ask permission with 可以","Choose the right negative"],"blocks":[{"type":"text","text":"These five little verbs go right before another verb, like 'want to', 'can' and 'may' in English. English has one 'can'; Chinese has three! Let's sort them out."},{"type":"table","head":["Word","Pinyin","Meaning","Example","Negative"],"rows":[["{{想}}","xiǎng","would like to, want to","{{我想喝水。}}","{{不想}}"],["{{要}}","yào","want to (firmly); will; need to","{{我要去北京。}}","{{不想}} / {{不用}}"],["{{会}}","huì","can (learned skill); will probably","{{我会说中文。}}","{{不会}}"],["{{能}}","néng","can (able, possible)","{{你能来吗？}}","{{不能}}"],["{{可以}}","kěyǐ","may, can (allowed)","{{我可以坐这儿吗？}}","{{不可以}}"]],"title":"The five helpers"},{"type":"rule","name":"想: would like to","color":"blue","desc":"Soft and polite. It also means 'to miss' and 'to think'.","examples":[{"t":"我想去中国。","tr":"Wǒ xiǎng qù Zhōngguó.","hl":"想"},{"t":"你想吃什么？","tr":"Nǐ xiǎng chī shénme?","hl":"想"},{"t":"我想你。","tr":"Wǒ xiǎng nǐ.","hl":"想"}]},{"type":"rule","name":"要: want / going to / need to","color":"orange","desc":"Stronger than {{想}}. With a noun it means 'I'll have…'.","examples":[{"t":"我要一杯咖啡。","tr":"Wǒ yào yì bēi kāfēi.","hl":"要"},{"t":"明天我要考试。","tr":"Míngtiān wǒ yào kǎoshì.","hl":"要"},{"t":"你要多喝水。","tr":"Nǐ yào duō hē shuǐ.","hl":"要"}]},{"type":"tip","kind":"warn","text":"{{不要}} doesn't mean 'don't want'. It means **Don't!** {{不要说话！}} = Don't talk! For 'don't want to' say {{不想}}; for 'no need' say {{不用}}."},{"type":"sentence","t":"你会说中文吗？","tr":"Nǐ huì shuō Zhōngwén ma?","mean":"Can you speak Chinese?","words":[{"t":"你","mean":"you"},{"t":"会","mean":"can (know how to)"},{"t":"说","mean":"speak"},{"t":"中文","mean":"Chinese"},{"t":"吗","mean":"(question)"}],"note":"Perfect reply for now: 会一点儿 (Huì yìdiǎnr, a little)."},{"type":"compare","items":[{"t":"我会游泳。","label":"会: a skill you learned","desc":"I can swim (I know how)."},{"t":"我今天能游泳。","label":"能: able / possible now","desc":"I can swim today (I'm well, the pool is open)."},{"t":"这儿可以游泳。","label":"可以: allowed","desc":"You may swim here (it's permitted)."}],"title":"会, 能 or 可以?"},{"type":"examples","items":[{"t":"你会开车吗？","tr":"Nǐ huì kāichē ma?","mean":"Can you drive?","hl":"会"},{"t":"明天会下雨。","tr":"Míngtiān huì xià yǔ.","mean":"It will probably rain tomorrow.","hl":"会"},{"t":"你能帮我吗？","tr":"Nǐ néng bāng wǒ ma?","mean":"Can you help me?","hl":"能"},{"t":"我感冒了，不能去。","tr":"Wǒ gǎnmào le, bù néng qù.","mean":"I've got a cold, so I can't go.","hl":"不能"},{"t":"我可以进来吗？","tr":"Wǒ kěyǐ jìnlái ma?","mean":"May I come in?","hl":"可以"},{"t":"这儿不可以抽烟。","tr":"Zhèr bù kěyǐ chōuyān.","mean":"Smoking is not allowed here.","hl":"不可以"}]},{"type":"tip","kind":"memory","text":"{{会}}: you went to class and learned it. {{能}}: your body or the situation lets you. {{可以}}: someone says it's OK."},{"type":"tip","kind":"tip","text":"To answer, just use the helper word: {{你会游泳吗？}} → {{会。}} / {{不会。}}"},{"type":"dialogue","lines":[{"who":"Coach","t":"你会游泳吗？","tr":"Nǐ huì yóuyǒng ma?","mean":"Can you swim?"},{"who":"Yan","t":"会，可是今天不能游。","tr":"Huì, kěshì jīntiān bù néng yóu.","mean":"Yes, but I can't swim today."},{"who":"Coach","t":"为什么？","tr":"Wèishénme?","mean":"Why?"},{"who":"Yan","t":"我感冒了。我可以明天来吗？","tr":"Wǒ gǎnmào le. Wǒ kěyǐ míngtiān lái ma?","mean":"I've got a cold. Can I come tomorrow?"},{"who":"Coach","t":"可以。你要多喝水，多休息！","tr":"Kěyǐ. Nǐ yào duō hē shuǐ, duō xiūxi!","mean":"Sure. You need to drink lots of water and rest!"}],"title":"At the swimming pool"},{"type":"practice","text":"Say what you want, can and may do.","lines":["我想去中国。","我要一杯茶。","我会说一点儿中文。","你能帮我吗？","我可以坐这儿吗？"]},{"type":"quiz","items":[{"q":"'I can speak Chinese' (I learned it):","options":["我可以说中文。","我要说中文。","我会说中文。","我说会中文。"],"answer":2},{"q":"'May I come in?'","options":["我想进来吗？","我可以进来吗？","我进来可以吗了？","我会进来吗？"],"answer":1},{"q":"Listen. What does it mean?","say":"不要说话","options":["Don't talk!","Can't talk now.","I don't want to talk.","No need to talk."],"answer":0},{"q":"'I don't want to go' is…","options":["我不要去。","我没想去。","我不会去。","我不想去。"],"answer":3,"explain":"不要去 sounds like 'Don't go!'"},{"q":"Listen. What is the speaker asking?","say":"你能帮我吗","options":["Can I help you?","Do you want help?","Do you know him?","Can you help me?"],"answer":3},{"q":"Which helper means 'allowed'?","options":["要","会","可以","想"],"answer":2},{"q":"{{我想你}} means…","options":["I think so.","I want you to go.","I miss you.","I know you."],"answer":2}],"title":"Quick quiz"}]},{"id":"u4-bi","icon":"比","title":"Comparisons with 比","subtitle":"Taller, cheaper, colder… and the same","minutes":13,"goals":["Compare with A 比 B + adjective","Say how much more","Say 'not as … as' with 没有","Say 'the same' with 一样"],"blocks":[{"type":"text","text":"Comparing things in Chinese uses one magic word: {{比}} (bǐ, compared with). No '-er' endings, no 'more'. Just A 比 B + adjective."},{"type":"rule","name":"A 比 B + adjective","color":"blue","desc":"Read it as 'A, compared with B, is …'.","examples":[{"t":"我比我哥哥高。","tr":"Wǒ bǐ wǒ gēge gāo.","hl":"比"},{"t":"今天比昨天冷。","tr":"Jīntiān bǐ zuótiān lěng.","hl":"比"},{"t":"茶比咖啡便宜。","tr":"Chá bǐ kāfēi piányi.","hl":"比"}]},{"type":"sentence","t":"冬天，北京比上海冷。","tr":"Dōngtiān, Běijīng bǐ Shànghǎi lěng.","mean":"In winter, Beijing is colder than Shanghai.","words":[{"t":"冬天","mean":"winter"},{"t":"北京","mean":"Beijing"},{"t":"比","mean":"compared with"},{"t":"上海","mean":"Shanghai"},{"t":"冷","mean":"cold"}]},{"type":"tip","kind":"warn","text":"No {{很}} in a {{比}} sentence! ✗ 我比他很高。 ✓ {{我比他高。}}"},{"type":"rule","name":"How much more?","color":"green","desc":"Add the amount AFTER the adjective: {{一点儿}} (a bit), {{得多}} or {{多了}} (much).","examples":[{"t":"我比他高一点儿。","tr":"Wǒ bǐ tā gāo yìdiǎnr.","hl":"一点儿"},{"t":"这个比那个贵得多。","tr":"Zhège bǐ nàge guì de duō.","hl":"得多"},{"t":"地铁比公交车快多了。","tr":"Dìtiě bǐ gōngjiāochē kuài duō le.","hl":"多了"}]},{"type":"tip","kind":"tip","text":"To say 'even more', put {{更}} (gèng) or {{还}} (hái) before the adjective: {{她比我更忙。}} (She's even busier than me.)"},{"type":"rule","name":"A 没有 B + adjective","color":"red","desc":"'A is not as … as B'.","examples":[{"t":"我没有他高。","tr":"Wǒ méiyǒu tā gāo.","hl":"没有"},{"t":"今天没有昨天热。","tr":"Jīntiān méiyǒu zuótiān rè.","hl":"没有"}]},{"type":"rule","name":"A 跟 B 一样 (+ adjective)","color":"purple","desc":"'A is the same (as B)'.","examples":[{"t":"我跟你一样大。","tr":"Wǒ gēn nǐ yíyàng dà.","hl":"一样"},{"t":"这两个一样。","tr":"Zhè liǎng gè yíyàng.","hl":"一样"}]},{"type":"tip","kind":"memory","text":"{{比}} looks like two people standing side by side, being compared. Who's taller?"},{"type":"vocab","items":[{"t":"快","tr":"kuài","mean":"fast","root":"忄 heart"},{"t":"慢","tr":"màn","mean":"slow","root":"忄 heart"},{"t":"长","tr":"cháng","mean":"long"},{"t":"短","tr":"duǎn","mean":"short (length)","root":"矢 arrow"},{"t":"矮","tr":"ǎi","mean":"short (height)","root":"矢 arrow"},{"t":"新","tr":"xīn","mean":"new","root":"斤 axe"},{"t":"旧","tr":"jiù","mean":"old (things)","root":"日 sun"},{"t":"一样","tr":"yíyàng","mean":"the same"}],"title":"Adjectives for comparing"},{"type":"dialogue","lines":[{"who":"Shopper","t":"这件多少钱？","tr":"Zhè jiàn duōshao qián?","mean":"How much is this one?"},{"who":"Seller","t":"两百块。","tr":"Liǎng bǎi kuài.","mean":"Two hundred kuai."},{"who":"Shopper","t":"那件呢？","tr":"Nà jiàn ne?","mean":"And that one?"},{"who":"Seller","t":"那件比这件便宜，一百五。","tr":"Nà jiàn bǐ zhè jiàn piányi, yìbǎi wǔ.","mean":"That one is cheaper: a hundred and fifty."},{"who":"Shopper","t":"可是这件比那件漂亮多了。","tr":"Kěshì zhè jiàn bǐ nà jiàn piàoliang duō le.","mean":"But this one is much prettier than that one."},{"who":"Seller","t":"对！一分钱一分货。","tr":"Duì! Yì fēn qián yì fēn huò.","mean":"Right! You get what you pay for."}],"title":"Clothes shopping"},{"type":"practice","text":"Compare yourself with someone in your family.","lines":["我比我妹妹高。","我没有我爸爸高。","我跟我哥哥一样大。","今天比昨天热。"]},{"type":"quiz","items":[{"q":"'I am taller than him':","options":["我高比他。","我比他高。","我比他很高。","他比我高。"],"answer":1},{"q":"Which sentence is WRONG?","options":["今天没有昨天冷。","今天比昨天很冷。","今天比昨天冷一点儿。","今天比昨天冷。"],"answer":1},{"q":"Listen. What does it mean?","say":"我没有他高","options":["I'm not as tall as him.","We're the same height.","He's not tall.","I'm taller than him."],"answer":0},{"q":"{{我跟你一样大}} means…","options":["We're both tall.","I'm older than you.","You're bigger than me.","We're the same age."],"answer":3},{"q":"'The subway is much faster than the bus':","options":["地铁比公交车快多了。","公交车比地铁快多了。","地铁比公交车多快了。","地铁多了比公交车快。"],"answer":0},{"q":"Listen. Which is cheaper?","say":"茶比咖啡便宜","options":["the same","neither","tea","coffee"],"answer":2}],"title":"Quick quiz"}]},{"id":"u4-time-words","icon":"时","title":"Where Do Time Words Go?","subtitle":"When comes early in a Chinese sentence","minutes":12,"goals":["Put time words before the verb","Order time, place and action","Go from big to small in time phrases","Put 'how long' after the verb"],"blocks":[{"type":"text","text":"In English, we often put the time at the end: 'I'm going to Beijing **tomorrow**.' Chinese puts it early, before the verb: 'I **tomorrow** go to Beijing.'"},{"type":"rule","name":"Subject + time + place + verb","color":"blue","desc":"Time comes first, then place, then the action.","examples":[{"t":"我明天去北京。","tr":"Wǒ míngtiān qù Běijīng.","hl":"明天"},{"t":"我每天早上七点起床。","tr":"Wǒ měitiān zǎoshang qī diǎn qǐchuáng.","hl":"每天早上七点"},{"t":"他下午在图书馆看书。","tr":"Tā xiàwǔ zài túshūguǎn kàn shū.","hl":"下午"}]},{"type":"rule","name":"Or time at the very front","color":"green","desc":"You can also start the sentence with the time. Both are correct.","examples":[{"t":"明天我去北京。","tr":"Míngtiān wǒ qù Běijīng.","hl":"明天"},{"t":"周末我们去公园。","tr":"Zhōumò wǒmen qù gōngyuán.","hl":"周末"}]},{"type":"tip","kind":"warn","text":"✗ 我去北京明天。 Time never goes at the end like in English."},{"type":"tip","kind":"memory","text":"**When → Where → What.** First set the time, then the place, then the action, like setting a scene in a film."},{"type":"sentence","t":"我晚上八点在家吃饭。","tr":"Wǒ wǎnshang bā diǎn zài jiā chī fàn.","mean":"I have dinner at home at 8 p.m.","words":[{"t":"我","mean":"I"},{"t":"晚上","mean":"evening"},{"t":"八点","mean":"eight o'clock"},{"t":"在","mean":"at"},{"t":"家","mean":"home"},{"t":"吃饭","mean":"eat (a meal)"}]},{"type":"rule","name":"Big to small","color":"purple","desc":"Time phrases start with the biggest unit, like dates do.","examples":[{"t":"明天上午十点","tr":"míngtiān shàngwǔ shí diǎn"},{"t":"下个星期五晚上","tr":"xià gè xīngqīwǔ wǎnshang"},{"t":"二〇二五年八月","tr":"èr líng èr wǔ nián bāyuè"}]},{"type":"vocab","items":[{"t":"每天","tr":"měitiān","mean":"every day"},{"t":"以前","tr":"yǐqián","mean":"before, in the past"},{"t":"以后","tr":"yǐhòu","mean":"after, later, in future"},{"t":"去年","tr":"qùnián","mean":"last year"},{"t":"明年","tr":"míngnián","mean":"next year","root":"日 sun"},{"t":"上个星期","tr":"shàng gè xīngqī","mean":"last week"},{"t":"下个月","tr":"xià gè yuè","mean":"next month"},{"t":"刚才","tr":"gāngcái","mean":"just now","root":"刂 knife"},{"t":"起床","tr":"qǐchuáng","mean":"to get up","root":"广 shelter"},{"t":"图书馆","tr":"túshūguǎn","mean":"library"}],"title":"Time words"},{"type":"tip","kind":"tip","text":"**How long** you do something is different: it goes AFTER the verb. {{我学了两年中文。}} (I studied Chinese for two years.) {{我每天学习一个小时。}} (I study for an hour every day.)"},{"type":"examples","items":[{"t":"我去年去了中国。","tr":"Wǒ qùnián qù le Zhōngguó.","mean":"I went to China last year.","hl":"去年"},{"t":"你明天几点来？","tr":"Nǐ míngtiān jǐ diǎn lái?","mean":"What time are you coming tomorrow?","hl":"明天几点"},{"t":"我们下个月在上海见。","tr":"Wǒmen xià gè yuè zài Shànghǎi jiàn.","mean":"We'll meet in Shanghai next month.","hl":"下个月"}]},{"type":"practice","text":"Describe your day in order: when → where → what.","lines":["我每天七点起床。","我八点在学校学习。","我中午在饭馆吃饭。","我晚上在家看书。"]},{"type":"quiz","items":[{"q":"'I'm going to Beijing tomorrow':","options":["去北京我明天。","我去明天北京。","我去北京明天。","我明天去北京。"],"answer":3},{"q":"Put it in order: 'I eat at home at 7 p.m.'","options":["我吃饭在家晚上七点。","我晚上七点在家吃饭。","晚上七点吃饭我在家。","我在家吃饭晚上七点。"],"answer":1},{"q":"Listen. When is the speaker going?","say":"我下个月去上海","options":["next week","tomorrow","last month","next month"],"answer":3},{"q":"Which time phrase is in the right order?","options":["明天上午十点","十点明天上午","上午明天十点","十点上午明天"],"answer":0},{"q":"'I studied Chinese for two years': where does 'two years' go?","options":["After the verb","Before the subject","At the very start","Before the verb"],"answer":0},{"q":"{{刚才}} means…","options":["last year","every day","just now","later on"],"answer":2}],"title":"Quick quiz"}]},{"id":"u4-guo","icon":"过","title":"过: Have You Ever…?","subtitle":"Talking about experiences","minutes":12,"goals":["Say what you have done before with 过","Ask 'Have you ever…?'","Make negatives with 没…过","Tell 了 and 过 apart"],"blocks":[{"type":"text","text":"Have you ever eaten Peking duck? Been to Shanghai? To talk about experiences, put {{过}} (guo) right after the verb."},{"type":"rule","name":"Verb + 过 = have done (before)","color":"green","desc":"{{过}} says you have had this experience at least once.","examples":[{"t":"我去过中国。","tr":"Wǒ qù guo Zhōngguó.","hl":"过"},{"t":"我吃过北京烤鸭。","tr":"Wǒ chī guo Běijīng kǎoyā.","hl":"过"},{"t":"他看过这个电影。","tr":"Tā kàn guo zhège diànyǐng.","hl":"过"}]},{"type":"sentence","t":"你去过上海吗？","tr":"Nǐ qù guo Shànghǎi ma?","mean":"Have you ever been to Shanghai?","words":[{"t":"你","mean":"you"},{"t":"去","mean":"go"},{"t":"过","mean":"(have ever)"},{"t":"上海","mean":"Shanghai"},{"t":"吗","mean":"(question)"}]},{"type":"examples","items":[{"t":"吃过。","tr":"Chī guo.","mean":"Yes, I have (eaten it).","hl":"过"},{"t":"没吃过。","tr":"Méi chī guo.","mean":"No, I've never eaten it.","hl":"没"}],"title":"Answering 你吃过饺子吗？"},{"type":"rule","name":"没 + verb + 过","color":"red","desc":"For 'have never', use {{没}} and KEEP {{过}}. Add {{从来}} (cónglái) for 'never ever'.","examples":[{"t":"我没去过日本。","tr":"Wǒ méi qù guo Rìběn.","hl":"没"},{"t":"我从来没吃过榴莲。","tr":"Wǒ cónglái méi chī guo liúlián.","hl":"从来没"}]},{"type":"tip","kind":"warn","text":"The negative of {{了}} drops {{了}} ({{我没吃}}), but the negative of {{过}} keeps {{过}} ({{我没吃过}})."},{"type":"compare","items":[{"t":"我去了北京。","label":"了: it happened","desc":"I went to Beijing (maybe I'm still there)."},{"t":"我去过北京。","label":"过: an experience","desc":"I've been to Beijing before (and came back)."}],"title":"了 or 过?"},{"type":"tip","kind":"memory","text":"{{过}} also means 'to pass, to cross'. An experience is something you have 'passed through'."},{"type":"vocab","items":[{"t":"北京烤鸭","tr":"Běijīng kǎoyā","mean":"Peking duck","root":"火 fire"},{"t":"榴莲","tr":"liúlián","mean":"durian (a very smelly fruit)","root":"木 tree"},{"t":"从来","tr":"cónglái","mean":"ever, always (从来没 = never)"},{"t":"次","tr":"cì","mean":"time(s), occasion","example":{"t":"我去过两次。","tr":"Wǒ qù guo liǎng cì.","mean":"I've been twice."}},{"t":"爬","tr":"pá","mean":"to climb","root":"爪 claw"},{"t":"长城","tr":"Chángchéng","mean":"the Great Wall","root":"土 earth"}],"title":"Words for this lesson"},{"type":"dialogue","lines":[{"who":"Hong","t":"你来过中国吗？","tr":"Nǐ lái guo Zhōngguó ma?","mean":"Have you been to China?"},{"who":"Eva","t":"来过一次。我去过北京。","tr":"Lái guo yí cì. Wǒ qù guo Běijīng.","mean":"Once. I've been to Beijing."},{"who":"Hong","t":"你爬过长城吗？","tr":"Nǐ pá guo Chángchéng ma?","mean":"Have you climbed the Great Wall?"},{"who":"Eva","t":"爬过！也吃过北京烤鸭。","tr":"Pá guo! Yě chī guo Běijīng kǎoyā.","mean":"Yes! And I've eaten Peking duck too."},{"who":"Hong","t":"你吃过榴莲吗？","tr":"Nǐ chī guo liúlián ma?","mean":"Have you ever eaten durian?"},{"who":"Eva","t":"没吃过，我不敢！","tr":"Méi chī guo, wǒ bù gǎn!","mean":"Never. I don't dare!"}],"title":"Travel stories"},{"type":"practice","text":"Say three things you have done and one you have never done.","lines":["我去过……","我吃过饺子。","我看过中国电影。","我没去过中国。","我从来没吃过榴莲。"]},{"type":"selfcheck","items":["I can build subject–verb–object sentences.","I use 很 (not 是) with adjectives.","I can ask questions with 吗 and question words.","I know when to use 不 and when to use 没.","I can use measure words, 的 and 在.","I can talk about the past with 了 and 过.","I can compare with 比 and put time words in the right place."],"title":"Unit check"},{"type":"quiz","items":[{"q":"'I have been to China':","options":["我去中国过。","我过去中国。","我去过中国。","过我去中国。"],"answer":2},{"q":"'I have never eaten durian':","options":["我没吃榴莲了。","我不吃过榴莲。","我没吃过榴莲。","我吃没过榴莲。"],"answer":2},{"q":"Listen. What is the question?","say":"你去过上海吗","options":["Do you live in Shanghai?","Where is Shanghai?","Are you going to Shanghai?","Have you been to Shanghai?"],"answer":3},{"q":"Which sentence talks about an EXPERIENCE?","options":["我要看电影。","我在看电影。","我看过这个电影。","我想看电影。"],"answer":2},{"q":"Listen. How many times?","say":"我去过两次","options":["three times","once","twice","never"],"answer":2},{"q":"{{从来没}} means…","options":["already","never ever","sometimes","always"],"answer":1}],"title":"Quick quiz"}]}]});
LC.units.push({"id":"talk","order":5,"icon":"说","color":"rose","title":"Everyday Conversations","subtitle":"Real-life Mandarin for restaurants, shops, travel, phones, plans, the doctor and work.","lessons":[{"id":"u5-restaurant","icon":"饭","title":"Ordering at a Restaurant","subtitle":"Get a table, order dishes, ask about spice and pay the bill.","minutes":15,"goals":["Answer “How many people?” and ask for the menu","Order dishes with 来 and 要","Ask if a dish is spicy","Ask for the bill and take leftovers away"],"blocks":[{"type":"text","text":"Eating out is one of the best parts of life in China. Food is cheap, tasty and shared by the whole table. In this lesson you will get a table, order, ask about spice and pay."},{"type":"vocab","title":"Key words","items":[{"t":"服务员","tr":"fúwùyuán","mean":"waiter, waitress","example":{"t":"服务员，菜单！","tr":"Fúwùyuán, càidān!","mean":"Excuse me, the menu please!"}},{"t":"菜单","tr":"càidān","mean":"menu"},{"t":"点菜","tr":"diǎn cài","mean":"to order (dishes)","example":{"t":"我们点菜吧。","tr":"Wǒmen diǎn cài ba.","mean":"Let's order."}},{"t":"米饭","tr":"mǐfàn","mean":"(cooked) rice"},{"t":"饺子","tr":"jiǎozi","mean":"dumplings"},{"t":"碗","tr":"wǎn","mean":"bowl (also a measure word)","example":{"t":"一碗面","tr":"yì wǎn miàn","mean":"a bowl of noodles"}},{"t":"辣","tr":"là","mean":"spicy, hot"},{"t":"好吃","tr":"hǎochī","mean":"tasty, delicious"},{"t":"买单","tr":"mǎidān","mean":"to pay the bill; “The bill, please!”"},{"t":"打包","tr":"dǎbāo","mean":"to pack (leftovers) to take away"}]},{"type":"dialogue","title":"At a Sichuan restaurant","lines":[{"who":"Waiter","t":"您好！几位？","tr":"Nín hǎo! Jǐ wèi?","mean":"Hello! How many people?"},{"who":"Anna","t":"两位。","tr":"Liǎng wèi.","mean":"Two."},{"who":"Waiter","t":"这边请。这是菜单。","tr":"Zhèbiān qǐng. Zhè shì càidān.","mean":"This way, please. Here is the menu."},{"who":"Anna","t":"你们这儿有什么好吃的？","tr":"Nǐmen zhèr yǒu shénme hǎochī de?","mean":"What's good here?"},{"who":"Waiter","t":"我们的宫保鸡丁很有名。","tr":"Wǒmen de gōngbǎo jīdīng hěn yǒumíng.","mean":"Our kung pao chicken is famous."},{"who":"Anna","t":"辣不辣？","tr":"Là bu là?","mean":"Is it spicy?"},{"who":"Waiter","t":"有一点儿辣。","tr":"Yǒu yìdiǎnr là.","mean":"A little spicy."},{"who":"Anna","t":"好，来一个宫保鸡丁，两碗米饭，一壶茶。","tr":"Hǎo, lái yí ge gōngbǎo jīdīng, liǎng wǎn mǐfàn, yì hú chá.","mean":"OK, one kung pao chicken, two bowls of rice and a pot of tea."},{"who":"Waiter","t":"好的，请稍等。","tr":"Hǎo de, qǐng shāo děng.","mean":"Sure, one moment please."},{"who":"Anna","t":"服务员，买单！","tr":"Fúwùyuán, mǎidān!","mean":"Excuse me, the bill please!"}]},{"type":"tip","kind":"tip","text":"To order, say {{来}} (lái, ‘bring’) or {{要}} (yào, ‘want’) + number + measure word + dish: {{来一盘饺子}} = ‘a plate of dumplings, please’."},{"type":"sentence","t":"我要一碗牛肉面。","tr":"Wǒ yào yì wǎn niúròu miàn.","mean":"I'd like a bowl of beef noodles.","words":[{"t":"我","mean":"I"},{"t":"要","mean":"want"},{"t":"一","mean":"one"},{"t":"碗","mean":"bowl (measure word)"},{"t":"牛肉","mean":"beef"},{"t":"面","mean":"noodles"}]},{"type":"sentence","t":"请不要放辣椒。","tr":"Qǐng bú yào fàng làjiāo.","mean":"Please don't add chilli.","words":[{"t":"请","mean":"please"},{"t":"不要","mean":"don't"},{"t":"放","mean":"put in"},{"t":"辣椒","mean":"chilli pepper"}]},{"type":"sentence","t":"可以用手机付钱吗？","tr":"Kěyǐ yòng shǒujī fù qián ma?","mean":"Can I pay with my phone?","words":[{"t":"可以","mean":"can"},{"t":"用","mean":"use"},{"t":"手机","mean":"mobile phone"},{"t":"付钱","mean":"pay"},{"t":"吗","mean":"(question word)"}]},{"type":"tip","kind":"culture","text":"Dishes are shared. Everyone orders together, the plates go in the middle and each person has a small bowl of rice. Tipping is not expected in mainland China."},{"type":"tip","kind":"culture","text":"Calling {{服务员！}} across the room is normal and not rude. Many restaurants also have a QR code on the table: you scan it to order and pay on your phone."},{"type":"steps","title":"Role-play: dinner for two","items":[{"title":"Get a table","t":"两位。","tr":"Liǎng wèi.","mean":"Two people.","desc":"Answer the question {{几位？}} (How many people?)."},{"title":"Ask for the menu","t":"请给我菜单。","tr":"Qǐng gěi wǒ càidān.","mean":"Please give me the menu."},{"title":"Ask what's good","t":"有什么推荐的？","tr":"Yǒu shénme tuījiàn de?","mean":"What do you recommend?"},{"title":"Order","t":"来一盘饺子，两碗米饭。","tr":"Lái yì pán jiǎozi, liǎng wǎn mǐfàn.","mean":"A plate of dumplings and two bowls of rice."},{"title":"Pay","t":"买单！","tr":"Mǎidān!","mean":"The bill, please!","desc":"Then try {{打包}} if there is food left."}]},{"type":"practice","title":"Say it aloud","text":"Read each line aloud. Tap any word to hear it.","lines":["服务员，菜单！","我要一碗米饭。","辣不辣？","不要太辣。","太好吃了！","买单！"]},{"type":"quiz","title":"Quick quiz","items":[{"q":"What does {{买单}} mean?","options":["The menu, please!","One more bowl!","The bill, please!","Not spicy, please!"],"answer":2},{"q":"Listen. What is being asked?","say":"辣不辣？","options":["Is it tasty?","Is it expensive?","Is the soup hot enough?","Is it spicy?"],"answer":3},{"q":"The waiter greets you at the door. Which question means “How many people?”","options":["几位？","多少钱？","几点？","哪里？"],"answer":0},{"q":"Which word means “menu”?","options":["米饭","菜单","服务员","打包"],"answer":1},{"q":"You want to take the leftovers home. Which word do you need?","options":["买单","点菜","好吃","打包"],"answer":3},{"q":"Is tipping expected in most restaurants in mainland China?","options":["Yes, about 10%","Yes, always 20 percent","No, not usually","Only for big groups at dinner"],"answer":2}]}]},{"id":"u5-shopping","icon":"买","title":"Shopping & Bargaining","subtitle":"Ask prices, try things on and bargain with a smile.","minutes":15,"goals":["Ask “How much?” and understand prices","Say “too expensive” and ask for a lower price","Ask to try something on","Know where bargaining is normal"],"blocks":[{"type":"text","text":"Shopping in China ranges from huge malls to busy street markets. In this lesson you will ask prices, try things on and practise friendly bargaining."},{"type":"vocab","title":"Key words","items":[{"t":"多少钱","tr":"duōshao qián","mean":"how much (money)?","example":{"t":"这个多少钱？","tr":"Zhège duōshao qián?","mean":"How much is this?"}},{"t":"块","tr":"kuài","mean":"yuan (spoken word for money)"},{"t":"贵","tr":"guì","mean":"expensive"},{"t":"便宜","tr":"piányi","mean":"cheap"},{"t":"一点儿","tr":"yìdiǎnr","mean":"a little, a bit","example":{"t":"便宜一点儿吧。","tr":"Piányi yìdiǎnr ba.","mean":"Make it a bit cheaper."}},{"t":"试","tr":"shì","mean":"to try (on)"},{"t":"件","tr":"jiàn","mean":"measure word for tops and jackets","example":{"t":"一件衣服","tr":"yí jiàn yīfu","mean":"a piece of clothing"}},{"t":"衣服","tr":"yīfu","mean":"clothes"},{"t":"颜色","tr":"yánsè","mean":"colour"},{"t":"买","tr":"mǎi","mean":"to buy"},{"t":"卖","tr":"mài","mean":"to sell"}]},{"type":"table","head":["Spoken","Written / on price tags","Value"],"rows":[["{{块}} kuài","{{元}} yuán","1 yuan"],["{{毛}} máo","{{角}} jiǎo","0.1 yuan"],["{{两块五}} liǎng kuài wǔ","{{2.5元}}","2.50 yuan"]],"title":"Talking about money"},{"type":"dialogue","title":"At a clothes market","lines":[{"who":"Ben","t":"老板，这件衣服多少钱？","tr":"Lǎobǎn, zhè jiàn yīfu duōshao qián?","mean":"Excuse me (boss), how much is this top?"},{"who":"Seller","t":"两百块。","tr":"Liǎngbǎi kuài.","mean":"200 yuan."},{"who":"Ben","t":"我可以试一下吗？","tr":"Wǒ kěyǐ shì yíxià ma?","mean":"Can I try it on?"},{"who":"Seller","t":"可以，那边可以试。","tr":"Kěyǐ, nàbiān kěyǐ shì.","mean":"Sure, you can try it over there."},{"who":"Ben","t":"有点儿贵，便宜一点儿吧。","tr":"Yǒudiǎnr guì, piányi yìdiǎnr ba.","mean":"It's a bit expensive. Make it a little cheaper."},{"who":"Seller","t":"一百八，怎么样？","tr":"Yìbǎi bā, zěnmeyàng?","mean":"180, how about that?"},{"who":"Ben","t":"一百块，可以吗？","tr":"Yìbǎi kuài, kěyǐ ma?","mean":"100 yuan, OK?"},{"who":"Seller","t":"不行不行，一百五，最低了。","tr":"Bù xíng bù xíng, yìbǎi wǔ, zuì dī le.","mean":"No way. 150 is my lowest."},{"who":"Ben","t":"一百二吧，不行我就走了。","tr":"Yìbǎi èr ba, bù xíng wǒ jiù zǒu le.","mean":"Say 120. If not, I'll go."},{"who":"Seller","t":"好吧好吧，一百二，给你。","tr":"Hǎo ba hǎo ba, yìbǎi èr, gěi nǐ.","mean":"Fine, fine. 120, it's yours."}]},{"type":"tip","kind":"memory","text":"Short prices drop the last unit: {{一百八}} = 180 (not 108!) and {{两块五}} = 2.50 yuan."},{"type":"sentence","t":"这个多少钱？","tr":"Zhège duōshao qián?","mean":"How much is this?","words":[{"t":"这个","mean":"this"},{"t":"多少","mean":"how much"},{"t":"钱","mean":"money"}]},{"type":"sentence","t":"有没有大一点儿的？","tr":"Yǒu méiyǒu dà yìdiǎnr de?","mean":"Do you have a bigger one?","words":[{"t":"有没有","mean":"do you have"},{"t":"大","mean":"big"},{"t":"一点儿","mean":"a bit"},{"t":"的","mean":"one (thing)"}]},{"type":"sentence","t":"我只是看看。","tr":"Wǒ zhǐshì kànkan.","mean":"I'm just looking.","words":[{"t":"我","mean":"I"},{"t":"只是","mean":"just"},{"t":"看看","mean":"have a look"}]},{"type":"tip","kind":"culture","text":"Bargaining is normal at street markets and small stalls, and in tourist markets the first price can be far too high. In malls, supermarkets and chain stores prices are fixed, so don't bargain there."},{"type":"tip","kind":"tip","text":"Stay friendly and smile. Walking away politely is the strongest move: the seller may call you back with a better price."},{"type":"steps","title":"Role-play: bargain for a souvenir","items":[{"title":"Ask the price","t":"这个多少钱？","tr":"Zhège duōshao qián?","mean":"How much is this?"},{"title":"React","t":"太贵了！","tr":"Tài guì le!","mean":"Too expensive!"},{"title":"Make an offer","t":"五十块，可以吗？","tr":"Wǔshí kuài, kěyǐ ma?","mean":"50 yuan, OK?"},{"title":"Meet in the middle","t":"六十吧。","tr":"Liùshí ba.","mean":"Let's say 60."},{"title":"Close the deal","t":"好，我买了。","tr":"Hǎo, wǒ mǎi le.","mean":"OK, I'll take it."}]},{"type":"practice","title":"Say it aloud","text":"Read each line aloud, like a real shopper.","lines":["多少钱？","太贵了！","便宜一点儿吧。","我可以试一下吗？","有没有小一点儿的？","好，我买了。"]},{"type":"quiz","title":"Quick quiz","items":[{"q":"Listen. What does the speaker think?","say":"太贵了！","options":["It's very cheap","It's too expensive","It's too small","It's the wrong colour for me"],"answer":1},{"q":"In everyday speech, the word for “yuan” is…","options":["块 (kuài)","件 (jiàn)","毛 (máo)","个 (gè)"],"answer":0},{"q":"Where is bargaining normal?","options":["At a street market","In a supermarket","At a big chain store","In a shopping mall shop"],"answer":0},{"q":"{{便宜}} means…","options":["expensive","pretty","cheap","new"],"answer":2},{"q":"How do you say “I'm just looking”?","options":["我可以试一下吗？","我只是看看。","我买了。","太贵了！"],"answer":1},{"q":"The seller says {{一百二}}. What is the price?","options":["102 yuan","112 yuan","1,200 yuan","120 yuan"],"answer":3}]}]},{"id":"u5-directions","icon":"路","title":"Asking for Directions","subtitle":"Find your way with left, right, straight on and landmarks.","minutes":15,"goals":["Ask where a place is and how to get there","Understand left, right, straight and turn","Describe where things are with position words"],"blocks":[{"type":"text","text":"Even with a map app, it helps to ask a real person. Learn to ask where something is, follow simple directions and check that you understood."},{"type":"vocab","title":"Key words","items":[{"t":"在哪儿","tr":"zài nǎr","mean":"where is…?","example":{"t":"地铁站在哪儿？","tr":"Dìtiězhàn zài nǎr?","mean":"Where is the subway station?"}},{"t":"怎么走","tr":"zěnme zǒu","mean":"how do I get there?"},{"t":"一直走","tr":"yìzhí zǒu","mean":"go straight on"},{"t":"往左拐","tr":"wǎng zuǒ guǎi","mean":"turn left"},{"t":"往右拐","tr":"wǎng yòu guǎi","mean":"turn right"},{"t":"路口","tr":"lùkǒu","mean":"intersection, crossing"},{"t":"红绿灯","tr":"hónglǜdēng","mean":"traffic lights"},{"t":"远","tr":"yuǎn","mean":"far"},{"t":"近","tr":"jìn","mean":"near, close"},{"t":"旁边","tr":"pángbiān","mean":"next to, beside"},{"t":"对面","tr":"duìmiàn","mean":"opposite"}]},{"type":"dialogue","title":"Looking for the subway","lines":[{"who":"Lily","t":"请问，地铁站在哪儿？","tr":"Qǐngwèn, dìtiězhàn zài nǎr?","mean":"Excuse me, where is the subway station?"},{"who":"Mr Li","t":"地铁站？离这儿不远。","tr":"Dìtiězhàn? Lí zhèr bù yuǎn.","mean":"The subway station? It's not far from here."},{"who":"Lily","t":"怎么走？","tr":"Zěnme zǒu?","mean":"How do I get there?"},{"who":"Mr Li","t":"你一直往前走，到第二个路口往右拐。","tr":"Nǐ yìzhí wǎng qián zǒu, dào dì-èr ge lùkǒu wǎng yòu guǎi.","mean":"Go straight ahead and turn right at the second intersection."},{"who":"Lily","t":"第二个路口往右拐，对吗？","tr":"Dì-èr ge lùkǒu wǎng yòu guǎi, duì ma?","mean":"Turn right at the second intersection, right?"},{"who":"Mr Li","t":"对。地铁站就在银行旁边。","tr":"Duì. Dìtiězhàn jiù zài yínháng pángbiān.","mean":"Yes. The station is right next to the bank."},{"who":"Lily","t":"走路要多长时间？","tr":"Zǒulù yào duō cháng shíjiān?","mean":"How long does it take on foot?"},{"who":"Mr Li","t":"大概五分钟。","tr":"Dàgài wǔ fēnzhōng.","mean":"About five minutes."},{"who":"Lily","t":"太好了，谢谢您！","tr":"Tài hǎo le, xièxie nín!","mean":"Great, thank you!"},{"who":"Mr Li","t":"不客气。","tr":"Bú kèqi.","mean":"You're welcome."}]},{"type":"rule","name":"Saying where something is","color":"blue","desc":"Thing + {{在}} + landmark + position word.","examples":[{"t":"学校在公园旁边。","tr":"Xuéxiào zài gōngyuán pángbiān.","hl":"旁边"},{"t":"书在桌子上。","tr":"Shū zài zhuōzi shang.","hl":"上"},{"t":"咖啡店在银行对面。","tr":"Kāfēidiàn zài yínháng duìmiàn.","hl":"对面"}],"how":"The position word comes AFTER the landmark, the opposite of English: ‘the bank’s opposite’, not ‘opposite the bank’."},{"type":"sentence","t":"请问，洗手间在哪儿？","tr":"Qǐngwèn, xǐshǒujiān zài nǎr?","mean":"Excuse me, where is the restroom?","words":[{"t":"请问","mean":"excuse me (may I ask)"},{"t":"洗手间","mean":"restroom"},{"t":"在","mean":"is at"},{"t":"哪儿","mean":"where"}]},{"type":"sentence","t":"银行在超市对面。","tr":"Yínháng zài chāoshì duìmiàn.","mean":"The bank is opposite the supermarket.","words":[{"t":"银行","mean":"bank"},{"t":"在","mean":"is at"},{"t":"超市","mean":"supermarket"},{"t":"对面","mean":"opposite"}]},{"type":"sentence","t":"到红绿灯往左拐。","tr":"Dào hónglǜdēng wǎng zuǒ guǎi.","mean":"Turn left at the traffic lights.","words":[{"t":"到","mean":"when you reach"},{"t":"红绿灯","mean":"traffic lights"},{"t":"往","mean":"towards"},{"t":"左","mean":"left"},{"t":"拐","mean":"turn"}]},{"type":"tip","kind":"culture","text":"In Beijing and other northern cities, people often give directions with compass points: {{往东走}} (wǎng dōng zǒu, go east) or {{往北走}} (wǎng běi zǒu, go north). Further south, left and right are more common."},{"type":"tip","kind":"culture","text":"Start with {{请问}} (‘may I ask’) to stop someone politely. To older strangers you can say {{阿姨}} (āyí, auntie) or {{叔叔}} (shūshu, uncle). It sounds warm and friendly."},{"type":"steps","title":"Role-play: find the train station","items":[{"title":"Get attention","t":"不好意思，请问一下。","tr":"Bù hǎoyìsi, qǐngwèn yíxià.","mean":"Sorry, may I ask something?"},{"title":"Ask where","t":"火车站在哪儿？","tr":"Huǒchēzhàn zài nǎr?","mean":"Where is the train station?"},{"title":"Ask how","t":"怎么走？","tr":"Zěnme zǒu?","mean":"How do I get there?"},{"title":"Check you understood","t":"往左拐，对吗？","tr":"Wǎng zuǒ guǎi, duì ma?","mean":"Turn left, right?","desc":"Repeating the key words is a great way to check."},{"title":"Ask the distance","t":"远不远？","tr":"Yuǎn bu yuǎn?","mean":"Is it far?"},{"title":"Thank them","t":"谢谢您！","tr":"Xièxie nín!","mean":"Thank you!"}]},{"type":"practice","title":"Say it aloud","text":"Read each direction aloud. Point the way with your hand as you say it!","lines":["一直往前走。","往左拐。","往右拐。","在银行旁边。","离这儿不远。","远不远？"]},{"type":"quiz","title":"Quick quiz","items":[{"q":"{{往右拐}} means…","options":["turn left","go straight","turn right","go back"],"answer":2},{"q":"Listen. What should you do?","say":"一直往前走。","options":["Turn at the lights","Go straight ahead","It's next to the bank","It's very far from here"],"answer":1},{"q":"Which sentence means “The bank is opposite the supermarket”?","options":["银行对面在超市。","在超市银行对面。","超市在银行旁边。","银行在超市对面。"],"answer":3},{"q":"Which word means “near”?","options":["近","远","左","右"],"answer":0},{"q":"What is a {{路口}}?","options":["an intersection","a traffic light","a subway station","a restroom"],"answer":0},{"q":"In Beijing someone says {{往北走}}. Which way do you go?","options":["South","North","East","West"],"answer":1}]}]},{"id":"u5-transport","icon":"车","title":"Taxi & Subway","subtitle":"Tell a driver where to go and find your way on the metro.","minutes":15,"goals":["Give a taxi driver a destination","Ask which subway line to take and where to change","Pay and get off politely"],"blocks":[{"type":"text","text":"Chinese cities have huge subway systems and plenty of taxis. Learn the words you need to ride, change lines and pay."},{"type":"vocab","title":"Key words","items":[{"t":"出租车","tr":"chūzūchē","mean":"taxi"},{"t":"打车","tr":"dǎchē","mean":"to take a taxi"},{"t":"师傅","tr":"shīfu","mean":"driver (polite word for skilled workers)"},{"t":"地铁","tr":"dìtiě","mean":"subway, metro"},{"t":"号线","tr":"hào xiàn","mean":"(subway) line","example":{"t":"二号线","tr":"èr hào xiàn","mean":"Line 2"}},{"t":"站","tr":"zhàn","mean":"station, stop"},{"t":"换乘","tr":"huànchéng","mean":"to change lines, transfer"},{"t":"上车","tr":"shàng chē","mean":"to get on"},{"t":"下车","tr":"xià chē","mean":"to get off"},{"t":"堵车","tr":"dǔchē","mean":"traffic jam"},{"t":"票","tr":"piào","mean":"ticket"}]},{"type":"dialogue","title":"In a taxi","lines":[{"who":"Tom","t":"师傅，去北京站。","tr":"Shīfu, qù Běijīng Zhàn.","mean":"Driver, to Beijing Railway Station, please."},{"who":"Driver","t":"好的。您赶时间吗？","tr":"Hǎo de. Nín gǎn shíjiān ma?","mean":"OK. Are you in a hurry?"},{"who":"Tom","t":"有点儿急。大概要多长时间？","tr":"Yǒudiǎnr jí. Dàgài yào duō cháng shíjiān?","mean":"A bit. About how long will it take?"},{"who":"Driver","t":"不堵车的话，二十分钟。","tr":"Bù dǔchē dehuà, èrshí fēnzhōng.","mean":"If there's no traffic, twenty minutes."},{"who":"Tom","t":"师傅，前面停一下就行。","tr":"Shīfu, qiánmiàn tíng yíxià jiù xíng.","mean":"Driver, just stop up ahead, that's fine."},{"who":"Driver","t":"好，到了。一共三十五块。","tr":"Hǎo, dào le. Yígòng sānshíwǔ kuài.","mean":"OK, we're here. 35 yuan in total."},{"who":"Tom","t":"我用手机付。","tr":"Wǒ yòng shǒujī fù.","mean":"I'll pay with my phone."},{"who":"Driver","t":"行，扫这个码。","tr":"Xíng, sǎo zhège mǎ.","mean":"Sure, scan this code."},{"who":"Tom","t":"好了。谢谢师傅！","tr":"Hǎo le. Xièxie shīfu!","mean":"Done. Thank you!"}]},{"type":"sentence","t":"去天安门坐几号线？","tr":"Qù Tiān'ānmén zuò jǐ hào xiàn?","mean":"Which line goes to Tiananmen?","words":[{"t":"去","mean":"go to"},{"t":"天安门","mean":"Tiananmen"},{"t":"坐","mean":"take (ride)"},{"t":"几","mean":"which number"},{"t":"号线","mean":"line"}]},{"type":"sentence","t":"在下一站换乘二号线。","tr":"Zài xià yí zhàn huànchéng èr hào xiàn.","mean":"Change to Line 2 at the next stop.","words":[{"t":"在","mean":"at"},{"t":"下一站","mean":"the next stop"},{"t":"换乘","mean":"change to"},{"t":"二号线","mean":"Line 2"}]},{"type":"sentence","t":"我在这儿下车。","tr":"Wǒ zài zhèr xià chē.","mean":"I'll get off here.","words":[{"t":"我","mean":"I"},{"t":"在","mean":"at"},{"t":"这儿","mean":"here"},{"t":"下车","mean":"get off"}]},{"type":"tip","kind":"culture","text":"Taxi drivers are usually called {{师傅}} (shīfu, ‘master’), a respectful word for people with a skill. Most people now book rides with an app and pay by phone."},{"type":"tip","kind":"culture","text":"Subways in big Chinese cities are fast and cheap, and stops are announced in Chinese and English. At most entrances your bag goes through a security scanner, just like at an airport."},{"type":"steps","title":"Role-play: ride the subway to the airport","items":[{"title":"Ask which line","t":"去机场坐几号线？","tr":"Qù jīchǎng zuò jǐ hào xiàn?","mean":"Which line goes to the airport?"},{"title":"Buy a ticket","t":"我要一张去西单的票。","tr":"Wǒ yào yì zhāng qù Xīdān de piào.","mean":"I'd like a ticket to Xidan."},{"title":"Ask where to change","t":"在哪儿换乘？","tr":"Zài nǎr huànchéng?","mean":"Where do I change?"},{"title":"Ask how many stops","t":"还有几站？","tr":"Hái yǒu jǐ zhàn?","mean":"How many more stops?"},{"title":"Get off","t":"不好意思，我下车。","tr":"Bù hǎoyìsi, wǒ xià chē.","mean":"Excuse me, I'm getting off.","desc":"Say this to people near the door."}]},{"type":"practice","title":"Say it aloud","text":"Read each line aloud.","lines":["师傅，去机场。","前面停一下。","一共多少钱？","坐几号线？","在哪儿换乘？","我在这儿下车。"]},{"type":"quiz","title":"Quick quiz","items":[{"q":"What do people usually call a taxi driver?","options":["老师 (lǎoshī)","服务员 (fúwùyuán)","老板 (lǎobǎn)","师傅 (shīfu)"],"answer":3},{"q":"Listen. What should you do?","say":"在下一站换乘。","options":["Get off at the last stop on this line","Buy a ticket here","Change lines at the next stop","Take a taxi"],"answer":2},{"q":"{{堵车}} means…","options":["a car park","a traffic jam","a bus stop","a very fast train"],"answer":1},{"q":"How do you say “I'll get off here”?","options":["我在这儿上车。","我去这儿。","我在这儿下车。","我在这儿换乘。"],"answer":2},{"q":"Which line is {{四号线}}?","options":["Line 4","Line 10","Line 14","Line 40"],"answer":0},{"q":"The driver says {{一共三十五块}}. How much do you pay?","options":["53 yuan","30 yuan","350 yuan","35 yuan"],"answer":3}]}]},{"id":"u5-hotel","icon":"住","title":"At the Hotel","subtitle":"Check in, ask about breakfast and Wi-Fi, and check out.","minutes":15,"goals":["Check in with a reservation","Ask about breakfast, Wi-Fi and check-out time","Read room numbers the Chinese way"],"blocks":[{"type":"text","text":"A smooth check-in makes the whole trip easier. Here are the phrases you'll use at the front desk ({{前台}}, qiántái)."},{"type":"vocab","title":"Key words","items":[{"t":"酒店","tr":"jiǔdiàn","mean":"hotel"},{"t":"前台","tr":"qiántái","mean":"front desk, reception"},{"t":"预订","tr":"yùdìng","mean":"to book, reserve"},{"t":"房间","tr":"fángjiān","mean":"room"},{"t":"单人间","tr":"dānrénjiān","mean":"single room"},{"t":"双人间","tr":"shuāngrénjiān","mean":"twin room"},{"t":"护照","tr":"hùzhào","mean":"passport"},{"t":"押金","tr":"yājīn","mean":"deposit"},{"t":"早餐","tr":"zǎocān","mean":"breakfast"},{"t":"密码","tr":"mìmǎ","mean":"password"},{"t":"退房","tr":"tuì fáng","mean":"to check out"}]},{"type":"dialogue","title":"Checking in","lines":[{"who":"Reception","t":"您好，欢迎光临！","tr":"Nín hǎo, huānyíng guānglín!","mean":"Hello, welcome!"},{"who":"Anna","t":"你好，我预订了一个房间。","tr":"Nǐ hǎo, wǒ yùdìng le yí ge fángjiān.","mean":"Hi, I booked a room."},{"who":"Reception","t":"请问您贵姓？","tr":"Qǐngwèn nín guìxìng?","mean":"May I have your surname?"},{"who":"Anna","t":"我姓史密斯，叫安娜。","tr":"Wǒ xìng Shǐmìsī, jiào Ānnà.","mean":"My surname is Smith, first name Anna."},{"who":"Reception","t":"好的，请给我看一下您的护照。","tr":"Hǎo de, qǐng gěi wǒ kàn yíxià nín de hùzhào.","mean":"OK, please show me your passport."},{"who":"Anna","t":"给您。早餐几点开始？","tr":"Gěi nín. Zǎocān jǐ diǎn kāishǐ?","mean":"Here you are. What time does breakfast start?"},{"who":"Reception","t":"早上七点到十点，在二楼。","tr":"Zǎoshang qī diǎn dào shí diǎn, zài èr lóu.","mean":"From 7 to 10 a.m., on the second floor."},{"who":"Anna","t":"明天几点退房？","tr":"Míngtiān jǐ diǎn tuì fáng?","mean":"What time is check-out tomorrow?"},{"who":"Reception","t":"中午十二点以前。这是您的房卡，八零六房间。","tr":"Zhōngwǔ shí'èr diǎn yǐqián. Zhè shì nín de fángkǎ, bā líng liù fángjiān.","mean":"Before 12 noon. Here is your key card, room 806."}]},{"type":"sentence","t":"无线网的密码是多少？","tr":"Wúxiànwǎng de mìmǎ shì duōshao?","mean":"What's the Wi-Fi password?","words":[{"t":"无线网","mean":"Wi-Fi"},{"t":"的","mean":"('s)"},{"t":"密码","mean":"password"},{"t":"是","mean":"is"},{"t":"多少","mean":"what (number)"}]},{"type":"sentence","t":"房间里没有热水。","tr":"Fángjiān li méiyǒu rè shuǐ.","mean":"There's no hot water in the room.","words":[{"t":"房间","mean":"room"},{"t":"里","mean":"in"},{"t":"没有","mean":"there isn't"},{"t":"热水","mean":"hot water"}]},{"type":"sentence","t":"可以帮我叫一辆出租车吗？","tr":"Kěyǐ bāng wǒ jiào yí liàng chūzūchē ma?","mean":"Could you call a taxi for me?","words":[{"t":"可以","mean":"can"},{"t":"帮","mean":"help"},{"t":"我","mean":"me"},{"t":"叫","mean":"call"},{"t":"一","mean":"one"},{"t":"辆","mean":"(measure word for vehicles)"},{"t":"出租车","mean":"taxi"},{"t":"吗","mean":"(question word)"}]},{"type":"tip","kind":"memory","text":"Room and phone numbers are read digit by digit, and 1 is often said {{幺}} (yāo) so it isn't confused with 7 (qī). Room 618 = liù yāo bā."},{"type":"tip","kind":"culture","text":"Hotels in China must register every guest, so the front desk will always ask for your passport. A refundable deposit ({{押金}}) is also common at check-in."},{"type":"steps","title":"Role-play: check in and out","items":[{"title":"Say you booked","t":"我预订了一个房间。","tr":"Wǒ yùdìng le yí ge fángjiān.","mean":"I booked a room."},{"title":"Give your name","t":"我姓林。","tr":"Wǒ xìng Lín.","mean":"My surname is Lin.","desc":"Use your own surname."},{"title":"Hand over your passport","t":"这是我的护照。","tr":"Zhè shì wǒ de hùzhào.","mean":"Here is my passport."},{"title":"Ask about breakfast","t":"有早餐吗？","tr":"Yǒu zǎocān ma?","mean":"Is there breakfast?"},{"title":"Ask for the Wi-Fi","t":"无线网的密码是多少？","tr":"Wúxiànwǎng de mìmǎ shì duōshao?","mean":"What's the Wi-Fi password?"},{"title":"Check out","t":"我要退房。","tr":"Wǒ yào tuì fáng.","mean":"I'd like to check out."}]},{"type":"practice","title":"Say it aloud","text":"Read each line aloud.","lines":["我预订了一个房间。","这是我的护照。","早餐几点开始？","密码是多少？","我要退房。"]},{"type":"quiz","title":"Quick quiz","items":[{"q":"{{退房}} means…","options":["to check in","to book a room","to change rooms","to check out"],"answer":3},{"q":"Listen. What does the receptionist want?","say":"请给我看一下您的护照。","options":["Your phone number","Your passport","The room key card","Your breakfast order"],"answer":1},{"q":"How would hotel staff usually read room 618?","options":["liù yāo bā","liùbǎi yīshíbā","liù bǎi bā","bā yāo liù"],"answer":0},{"q":"Why does the front desk ask for your passport?","options":["To keep it until you check out","To check your online booking app","Guests must be registered","To give you a discount"],"answer":2},{"q":"A {{单人间}} is…","options":["a twin room","a suite","a single room","a dormitory bed"],"answer":2},{"q":"{{押金}} is a…","options":["deposit","discount","receipt","room service menu"],"answer":0}]}]},{"id":"u5-phone","icon":"话","title":"Phone Calls & Messaging","subtitle":"Answer the phone, leave a message and swap WeChat contacts.","minutes":15,"goals":["Start and end a phone call","Say phone numbers correctly","Talk about messages, WeChat and batteries"],"blocks":[{"type":"text","text":"Phones are at the centre of daily life in China. Learn how to answer a call, ask for someone, give your number and add friends on WeChat."},{"type":"vocab","title":"Key words","items":[{"t":"打电话","tr":"dǎ diànhuà","mean":"to make a phone call"},{"t":"喂","tr":"wéi","mean":"hello? (on the phone only)"},{"t":"手机号","tr":"shǒujīhào","mean":"mobile number"},{"t":"微信","tr":"Wēixìn","mean":"WeChat"},{"t":"加微信","tr":"jiā Wēixìn","mean":"to add someone on WeChat"},{"t":"扫一扫","tr":"sǎo yi sǎo","mean":"to scan (a QR code)"},{"t":"发","tr":"fā","mean":"to send","example":{"t":"我发给你。","tr":"Wǒ fā gěi nǐ.","mean":"I'll send it to you."}},{"t":"语音","tr":"yǔyīn","mean":"voice message"},{"t":"回电话","tr":"huí diànhuà","mean":"to call back"},{"t":"打错了","tr":"dǎcuò le","mean":"wrong number"},{"t":"没电了","tr":"méi diàn le","mean":"the battery is dead"}]},{"type":"dialogue","title":"Calling a teacher","lines":[{"who":"Xiao Lin","t":"喂，你好！请问是王老师吗？","tr":"Wéi, nǐ hǎo! Qǐngwèn shì Wáng lǎoshī ma?","mean":"Hello! Is this Teacher Wang?"},{"who":"Mr Wang","t":"我就是。您是哪位？","tr":"Wǒ jiù shì. Nín shì nǎ wèi?","mean":"Speaking. Who's calling?"},{"who":"Xiao Lin","t":"我是小林，是您的学生。","tr":"Wǒ shì Xiǎo Lín, shì nín de xuésheng.","mean":"It's Xiao Lin, your student."},{"who":"Mr Wang","t":"哦，小林！有什么事？","tr":"Ò, Xiǎo Lín! Yǒu shénme shì?","mean":"Oh, Xiao Lin! What's up?"},{"who":"Xiao Lin","t":"我明天不能来上课，我感冒了。","tr":"Wǒ míngtiān bù néng lái shàngkè, wǒ gǎnmào le.","mean":"I can't come to class tomorrow. I've caught a cold."},{"who":"Mr Wang","t":"没关系，好好休息。","tr":"Méi guānxi, hǎohǎo xiūxi.","mean":"That's OK. Get plenty of rest."},{"who":"Xiao Lin","t":"您能把作业发到我的微信上吗？","tr":"Nín néng bǎ zuòyè fā dào wǒ de Wēixìn shang ma?","mean":"Could you send the homework to my WeChat?"},{"who":"Mr Wang","t":"可以。你的手机号是多少？","tr":"Kěyǐ. Nǐ de shǒujīhào shì duōshao?","mean":"Sure. What's your mobile number?"},{"who":"Xiao Lin","t":"一三九，八八六七，二零五四。","tr":"Yāo sān jiǔ, bā bā liù qī, èr líng wǔ sì.","mean":"139 8867 2054."},{"who":"Mr Wang","t":"好，我一会儿加你。","tr":"Hǎo, wǒ yíhuìr jiā nǐ.","mean":"OK, I'll add you in a moment."}]},{"type":"sentence","t":"你打错了。","tr":"Nǐ dǎcuò le.","mean":"You've got the wrong number.","words":[{"t":"你","mean":"you"},{"t":"打错","mean":"dialled wrongly"},{"t":"了","mean":"(done)"}]},{"type":"sentence","t":"我手机没电了。","tr":"Wǒ shǒujī méi diàn le.","mean":"My phone battery is dead.","words":[{"t":"我","mean":"my"},{"t":"手机","mean":"mobile phone"},{"t":"没","mean":"has no more"},{"t":"电","mean":"power"},{"t":"了","mean":"(change)"}]},{"type":"sentence","t":"我们加个微信吧。","tr":"Wǒmen jiā ge Wēixìn ba.","mean":"Let's add each other on WeChat.","words":[{"t":"我们","mean":"we"},{"t":"加","mean":"add"},{"t":"个","mean":"(measure word)"},{"t":"微信","mean":"WeChat"},{"t":"吧","mean":"(suggestion)"}]},{"type":"tip","kind":"tip","text":"On the phone, {{喂}} is usually said with a rising tone (wéi) and means ‘hello?’. Face to face it sounds like ‘hey, you!’, so don't use it to greet people in person."},{"type":"tip","kind":"culture","text":"WeChat ({{微信}}) is used for almost everything in China: chatting, voice messages, paying, booking and work groups. When people meet, they often scan each other's QR code instead of swapping numbers."},{"type":"steps","title":"Role-play: call an office","items":[{"title":"Answer or start","t":"喂，你好！","tr":"Wéi, nǐ hǎo!","mean":"Hello?"},{"title":"Ask for someone","t":"请问李经理在吗？","tr":"Qǐngwèn Lǐ jīnglǐ zài ma?","mean":"Is Manager Li there, please?"},{"title":"Ask who is calling","t":"请问您是哪位？","tr":"Qǐngwèn nín shì nǎ wèi?","mean":"May I ask who's calling?"},{"title":"Leave a message","t":"请他给我回电话。","tr":"Qǐng tā gěi wǒ huí diànhuà.","mean":"Please ask him to call me back."},{"title":"Say goodbye","t":"好的，再见！","tr":"Hǎo de, zàijiàn!","mean":"OK, goodbye!"}]},{"type":"practice","title":"Say it aloud","text":"Read each line aloud. Then say your own phone number in Chinese!","lines":["喂，你好！","您是哪位？","你的手机号是多少？","我们加个微信吧。","我手机没电了。","请给我回电话。"]},{"type":"quiz","title":"Quick quiz","items":[{"q":"On the phone, {{喂}} means…","options":["Goodbye","Hello?","Thank you","Wrong number"],"answer":1},{"q":"Listen. What is the problem?","say":"你打错了。","options":["The phone is off","Please call me back later this evening","The signal is bad","Wrong number"],"answer":3},{"q":"How is the 1 in a phone number like 139 usually said?","options":["yāo","yī","yí","shí"],"answer":0},{"q":"{{我手机没电了}} means…","options":["I don't have a phone","My phone is new","I lost my mobile phone yesterday","My battery is dead"],"answer":3},{"q":"How do people often add each other on WeChat?","options":["Exchange business cards","Write an email","Scan a QR code","Send a letter"],"answer":2},{"q":"{{回电话}} means…","options":["to hang up","to call back","to make a video call","to send a text"],"answer":1}]}]},{"id":"u5-plans","icon":"约","title":"Making Plans","subtitle":"Invite a friend, agree on a time and place, or say no politely.","minutes":15,"goals":["Ask if someone is free","Suggest activities with 吧","Set a time and place to meet","Decline an invitation politely"],"blocks":[{"type":"text","text":"Making plans with friends is great practice. Learn to invite, suggest, agree on a time and place, and politely say no."},{"type":"vocab","title":"Key words","items":[{"t":"有空","tr":"yǒu kòng","mean":"to be free (have time)"},{"t":"周末","tr":"zhōumò","mean":"weekend"},{"t":"一起","tr":"yìqǐ","mean":"together"},{"t":"看电影","tr":"kàn diànyǐng","mean":"to see a film"},{"t":"见面","tr":"jiànmiàn","mean":"to meet"},{"t":"约","tr":"yuē","mean":"to arrange (to meet)"},{"t":"门口","tr":"ménkǒu","mean":"entrance, at the door"},{"t":"怎么样","tr":"zěnmeyàng","mean":"how about it?"},{"t":"改天","tr":"gǎitiān","mean":"another day"},{"t":"不见不散","tr":"bú jiàn bú sàn","mean":"see you there! (we won't leave until we meet)"}]},{"type":"dialogue","title":"A weekend plan","lines":[{"who":"Xiao Zhang","t":"米娅，这个周末你有空吗？","tr":"Mǐyà, zhège zhōumò nǐ yǒu kòng ma?","mean":"Mia, are you free this weekend?"},{"who":"Mia","t":"星期六有事，星期天有空。怎么了？","tr":"Xīngqīliù yǒu shì, xīngqītiān yǒu kòng. Zěnme le?","mean":"I'm busy on Saturday, free on Sunday. Why?"},{"who":"Xiao Zhang","t":"我们一起去看电影吧！","tr":"Wǒmen yìqǐ qù kàn diànyǐng ba!","mean":"Let's go and see a film together!"},{"who":"Mia","t":"好啊！看什么电影？","tr":"Hǎo a! Kàn shénme diànyǐng?","mean":"Sure! Which film?"},{"who":"Xiao Zhang","t":"有一个新的中国电影，听说很好看。","tr":"Yǒu yí ge xīn de Zhōngguó diànyǐng, tīngshuō hěn hǎokàn.","mean":"There's a new Chinese film. I hear it's really good."},{"who":"Mia","t":"几点见面？在哪儿见？","tr":"Jǐ diǎn jiànmiàn? Zài nǎr jiàn?","mean":"What time shall we meet? Where?"},{"who":"Xiao Zhang","t":"下午两点，在电影院门口，怎么样？","tr":"Xiàwǔ liǎng diǎn, zài diànyǐngyuàn ménkǒu, zěnmeyàng?","mean":"2 p.m. at the cinema entrance, how's that?"},{"who":"Mia","t":"没问题。看完电影一起吃饭吧。","tr":"Méi wèntí. Kàn wán diànyǐng yìqǐ chī fàn ba.","mean":"No problem. Let's eat together after the film."},{"who":"Xiao Zhang","t":"好主意！星期天见，不见不散！","tr":"Hǎo zhǔyi! Xīngqītiān jiàn, bú jiàn bú sàn!","mean":"Good idea! See you Sunday. Be there!"},{"who":"Mia","t":"不见不散！","tr":"Bú jiàn bú sàn!","mean":"See you there!"}]},{"type":"rule","name":"Suggest with 吧 (ba)","color":"green","desc":"Put {{吧}} at the end of a sentence to make a friendly suggestion: ‘Let's…’.","examples":[{"t":"我们走吧。","tr":"Wǒmen zǒu ba.","hl":"吧"},{"t":"一起去吧！","tr":"Yìqǐ qù ba!","hl":"吧"},{"t":"我们喝咖啡吧。","tr":"Wǒmen hē kāfēi ba.","hl":"吧"}]},{"type":"sentence","t":"你明天晚上有空吗？","tr":"Nǐ míngtiān wǎnshang yǒu kòng ma?","mean":"Are you free tomorrow evening?","words":[{"t":"你","mean":"you"},{"t":"明天","mean":"tomorrow"},{"t":"晚上","mean":"evening"},{"t":"有空","mean":"are free"},{"t":"吗","mean":"(question word)"}]},{"type":"sentence","t":"不好意思，我那天有事。","tr":"Bù hǎoyìsi, wǒ nà tiān yǒu shì.","mean":"Sorry, I'm busy that day.","words":[{"t":"不好意思","mean":"sorry"},{"t":"我","mean":"I"},{"t":"那天","mean":"that day"},{"t":"有事","mean":"have something on"}]},{"type":"sentence","t":"我们改天再约吧。","tr":"Wǒmen gǎitiān zài yuē ba.","mean":"Let's make it another day.","words":[{"t":"我们","mean":"we"},{"t":"改天","mean":"another day"},{"t":"再","mean":"again"},{"t":"约","mean":"arrange"},{"t":"吧","mean":"(suggestion)"}]},{"type":"tip","kind":"culture","text":"A direct ‘no’ can feel harsh. People often decline with {{我那天有事}} (‘I have something on that day’) or {{下次吧}} (‘next time’). If someone says {{改天吧}} without naming a day, it may simply be a polite no."},{"type":"tip","kind":"culture","text":"Whoever invites often pays, and friends may playfully ‘fight’ over the bill. Among young people, splitting the bill is also common: it's called {{AA制}} (AA zhì)."},{"type":"steps","title":"Role-play: invite a friend hiking","items":[{"title":"Ask if they're free","t":"你周六有空吗？","tr":"Nǐ zhōuliù yǒu kòng ma?","mean":"Are you free on Saturday?"},{"title":"Suggest an activity","t":"我们去爬山吧！","tr":"Wǒmen qù pá shān ba!","mean":"Let's go hiking!"},{"title":"Set a time","t":"早上九点怎么样？","tr":"Zǎoshang jiǔ diǎn zěnmeyàng?","mean":"How about 9 a.m.?"},{"title":"Set a place","t":"在地铁站见。","tr":"Zài dìtiězhàn jiàn.","mean":"Let's meet at the subway station."},{"title":"Confirm","t":"不见不散！","tr":"Bú jiàn bú sàn!","mean":"See you there!"}]},{"type":"practice","title":"Say it aloud","text":"Read each line aloud.","lines":["你周末有空吗？","我们一起去吧！","几点见面？","在门口见。","不好意思，我有事。","不见不散！"]},{"type":"quiz","title":"Quick quiz","items":[{"q":"{{有空}} means…","options":["to be busy","to be late","to be free","to be hungry"],"answer":2},{"q":"Listen. What is your friend suggesting?","say":"我们一起去看电影吧！","options":["Did you see the film?","Seeing a film together","Shall we watch TV at my place tonight?","The cinema is closed"],"answer":1},{"q":"What does {{吧}} add to {{我们走吧}}?","options":["a question","past tense","makes it a negative sentence","a suggestion (let's)"],"answer":3},{"q":"People say {{不见不散}} when…","options":["confirming a plan to meet","turning down an invite","apologising for being late","saying goodbye forever"],"answer":0},{"q":"A friend says {{改天吧}} with no date. It probably means…","options":["yes, tomorrow","let's meet right now","maybe not this time","I'll pay for everything"],"answer":2},{"q":"Which word means “weekend”?","options":["周六","周末","晚上","明天"],"answer":1}]}]},{"id":"u5-doctor","icon":"医","title":"At the Doctor","subtitle":"Say what's wrong, understand advice and get medicine.","minutes":15,"goals":["Say how you feel and what hurts","Say how long you've been ill and mention allergies","Understand how to take medicine"],"blocks":[{"type":"text","text":"Nobody wants to get sick abroad, but knowing a few phrases makes it much less stressful. Learn to explain your symptoms and understand the doctor."},{"type":"vocab","title":"Key words","items":[{"t":"医院","tr":"yīyuàn","mean":"hospital"},{"t":"医生","tr":"yīshēng","mean":"doctor"},{"t":"不舒服","tr":"bù shūfu","mean":"unwell, not feeling well"},{"t":"疼","tr":"téng","mean":"to hurt, ache","example":{"t":"头疼","tr":"tóuténg","mean":"headache"}},{"t":"发烧","tr":"fāshāo","mean":"to have a fever"},{"t":"咳嗽","tr":"késou","mean":"to cough"},{"t":"感冒","tr":"gǎnmào","mean":"a cold; to catch a cold"},{"t":"过敏","tr":"guòmǐn","mean":"allergic; allergy"},{"t":"药","tr":"yào","mean":"medicine"},{"t":"药店","tr":"yàodiàn","mean":"pharmacy"},{"t":"挂号","tr":"guàhào","mean":"to register (at a hospital)"}]},{"type":"dialogue","title":"Seeing the doctor","lines":[{"who":"Doctor","t":"你好，哪儿不舒服？","tr":"Nǐ hǎo, nǎr bù shūfu?","mean":"Hello, what's the problem?"},{"who":"David","t":"我头疼，还有点儿发烧。","tr":"Wǒ tóuténg, hái yǒudiǎnr fāshāo.","mean":"I have a headache and a slight fever."},{"who":"Doctor","t":"几天了？","tr":"Jǐ tiān le?","mean":"For how many days?"},{"who":"David","t":"两天了。晚上一直咳嗽。","tr":"Liǎng tiān le. Wǎnshang yìzhí késou.","mean":"Two days. I keep coughing at night."},{"who":"Doctor","t":"我看看。张开嘴，说“啊”。","tr":"Wǒ kànkan. Zhāngkāi zuǐ, shuō “ā”.","mean":"Let me see. Open your mouth and say “ah”."},{"who":"Doctor","t":"你感冒了，不太严重。你对什么药过敏吗？","tr":"Nǐ gǎnmào le, bú tài yánzhòng. Nǐ duì shénme yào guòmǐn ma?","mean":"You have a cold, not too serious. Are you allergic to any medicine?"},{"who":"David","t":"没有。","tr":"Méiyǒu.","mean":"No."},{"who":"Doctor","t":"这个药一天吃三次，一次两片。","tr":"Zhège yào yì tiān chī sān cì, yí cì liǎng piàn.","mean":"Take this medicine three times a day, two tablets each time."},{"who":"David","t":"我明天能上班吗？","tr":"Wǒ míngtiān néng shàngbān ma?","mean":"Can I go to work tomorrow?"},{"who":"Doctor","t":"最好在家休息两天，多喝热水。","tr":"Zuìhǎo zài jiā xiūxi liǎng tiān, duō hē rè shuǐ.","mean":"Better rest at home for two days, and drink plenty of hot water."}]},{"type":"table","head":["Chinese","Pinyin","Meaning"],"rows":[["{{头疼}}","tóuténg","headache"],["{{牙疼}}","yá téng","toothache"],["{{肚子疼}}","dùzi téng","stomach ache"],["{{嗓子疼}}","sǎngzi téng","sore throat"],["{{腿疼}}","tuǐ téng","my leg hurts"]],"title":"Body part + 疼 = it hurts"},{"type":"sentence","t":"我肚子疼。","tr":"Wǒ dùzi téng.","mean":"I have a stomach ache.","words":[{"t":"我","mean":"I"},{"t":"肚子","mean":"stomach"},{"t":"疼","mean":"hurts"}]},{"type":"sentence","t":"我对花生过敏。","tr":"Wǒ duì huāshēng guòmǐn.","mean":"I'm allergic to peanuts.","words":[{"t":"我","mean":"I"},{"t":"对","mean":"to"},{"t":"花生","mean":"peanuts"},{"t":"过敏","mean":"allergic"}]},{"type":"sentence","t":"附近有药店吗？","tr":"Fùjìn yǒu yàodiàn ma?","mean":"Is there a pharmacy nearby?","words":[{"t":"附近","mean":"nearby"},{"t":"有","mean":"there is"},{"t":"药店","mean":"pharmacy"},{"t":"吗","mean":"(question word)"}]},{"type":"tip","kind":"culture","text":"In China people usually go to a hospital ({{医院}}) even for small problems, rather than to a family doctor. First you register ({{挂号}}), often on an app or a machine, then wait for your number to be called."},{"type":"tip","kind":"fun","text":"‘Drink more hot water’ ({{多喝热水}}) is the classic Chinese advice for almost any illness. It's a caring thing to say, and a popular joke too!"},{"type":"tip","kind":"warn","text":"In an emergency in mainland China, call {{120}} for an ambulance (110 is the police, 119 the fire service)."},{"type":"steps","title":"Role-play: at the clinic","items":[{"title":"Say you feel unwell","t":"我不舒服。","tr":"Wǒ bù shūfu.","mean":"I don't feel well."},{"title":"Say what hurts","t":"我嗓子疼。","tr":"Wǒ sǎngzi téng.","mean":"My throat hurts."},{"title":"Say how long","t":"三天了。","tr":"Sān tiān le.","mean":"For three days."},{"title":"Mention allergies","t":"我对青霉素过敏。","tr":"Wǒ duì qīngméisù guòmǐn.","mean":"I'm allergic to penicillin.","desc":"Learn the name of anything you are allergic to before you travel."},{"title":"Ask about the medicine","t":"这个药怎么吃？","tr":"Zhège yào zěnme chī?","mean":"How do I take this medicine?"}]},{"type":"practice","title":"Say it aloud","text":"Read each line aloud.","lines":["我不舒服。","我头疼。","我发烧了。","我对花生过敏。","这个药怎么吃？","多喝热水！"]},{"type":"quiz","title":"Quick quiz","items":[{"q":"{{发烧}} means…","options":["to cough","to have a headache","to sneeze","to have a fever"],"answer":3},{"q":"Listen. What's wrong?","say":"我头疼。","options":["I have a headache","My stomach hurts","I have a fever","I'm allergic to peanuts"],"answer":0},{"q":"{{一天吃三次}} means take it…","options":["for three days","three times a day","three tablets at once","once every three days"],"answer":1},{"q":"Which number calls an ambulance in mainland China?","options":["110","119","120","999"],"answer":2},{"q":"{{我对花生过敏}} means…","options":["I love eating peanuts","I ate peanuts","Peanuts are good for you","I'm allergic to peanuts"],"answer":3},{"q":"How do you ask “Is there a pharmacy nearby?”","options":["附近有药店吗？","医院在哪儿？","你哪儿不舒服？","这个药怎么吃？"],"answer":0}]}]},{"id":"u5-smalltalk","icon":"天","title":"Small Talk & the Weather","subtitle":"Chat with neighbours about the weather and daily life.","minutes":15,"goals":["Talk about the weather and temperature","Use everyday greetings like 你吃了吗","Handle personal questions with a smile"],"blocks":[{"type":"text","text":"Small talk builds friendships. Chinese small talk is often about food, work and daily life, and of course the weather."},{"type":"vocab","title":"Key words","items":[{"t":"天气","tr":"tiānqì","mean":"weather"},{"t":"晴天","tr":"qíngtiān","mean":"sunny day"},{"t":"下雨","tr":"xià yǔ","mean":"to rain"},{"t":"下雪","tr":"xià xuě","mean":"to snow"},{"t":"刮风","tr":"guā fēng","mean":"to be windy"},{"t":"冷","tr":"lěng","mean":"cold"},{"t":"热","tr":"rè","mean":"hot"},{"t":"度","tr":"dù","mean":"degree(s)"},{"t":"天气预报","tr":"tiānqì yùbào","mean":"weather forecast"},{"t":"伞","tr":"sǎn","mean":"umbrella"},{"t":"最近","tr":"zuìjìn","mean":"recently, lately"}]},{"type":"dialogue","title":"A cold morning","lines":[{"who":"Auntie Liu","t":"山姆，早啊！去哪儿啊？","tr":"Shānmǔ, zǎo a! Qù nǎr a?","mean":"Morning, Sam! Where are you off to?"},{"who":"Sam","t":"刘阿姨，早！我去上班。","tr":"Liú āyí, zǎo! Wǒ qù shàngbān.","mean":"Morning, Auntie Liu! I'm going to work."},{"who":"Auntie Liu","t":"今天真冷啊！你穿得太少了。","tr":"Jīntiān zhēn lěng a! Nǐ chuān de tài shǎo le.","mean":"It's so cold today! You're not wearing enough."},{"who":"Sam","t":"是啊，昨天还挺暖和的。","tr":"Shì a, zuótiān hái tǐng nuǎnhuo de.","mean":"Yes, yesterday it was still quite warm."},{"who":"Auntie Liu","t":"天气预报说下午要下雪。","tr":"Tiānqì yùbào shuō xiàwǔ yào xià xuě.","mean":"The forecast says it will snow this afternoon."},{"who":"Sam","t":"真的吗？那我带把伞吧。","tr":"Zhēn de ma? Nà wǒ dài bǎ sǎn ba.","mean":"Really? Then I'll take an umbrella."},{"who":"Auntie Liu","t":"最近工作忙不忙？","tr":"Zuìjìn gōngzuò máng bu máng?","mean":"Is work busy these days?"},{"who":"Sam","t":"挺忙的，不过还好。您身体好吗？","tr":"Tǐng máng de, búguò hái hǎo. Nín shēntǐ hǎo ma?","mean":"Quite busy, but OK. Are you keeping well?"},{"who":"Auntie Liu","t":"好着呢！快去吧，别迟到了。","tr":"Hǎo zhe ne! Kuài qù ba, bié chídào le.","mean":"Very well! Off you go, don't be late."},{"who":"Sam","t":"好，回头见！","tr":"Hǎo, huítóu jiàn!","mean":"OK, see you later!"}]},{"type":"sentence","t":"今天多少度？","tr":"Jīntiān duōshao dù?","mean":"What's the temperature today?","words":[{"t":"今天","mean":"today"},{"t":"多少","mean":"how many"},{"t":"度","mean":"degrees"}]},{"type":"sentence","t":"明天会下雨吗？","tr":"Míngtiān huì xià yǔ ma?","mean":"Will it rain tomorrow?","words":[{"t":"明天","mean":"tomorrow"},{"t":"会","mean":"will"},{"t":"下雨","mean":"rain"},{"t":"吗","mean":"(question word)"}]},{"type":"sentence","t":"你吃了吗？","tr":"Nǐ chī le ma?","mean":"Have you eaten?","words":[{"t":"你","mean":"you"},{"t":"吃","mean":"eat"},{"t":"了","mean":"(done)"},{"t":"吗","mean":"(question word)"}],"note":"A friendly greeting, especially from older people. Just answer {{吃了}} (chī le). It is not an invitation to lunch!"},{"type":"tip","kind":"culture","text":"Many everyday greetings are really comments on what you're doing: {{去哪儿啊？}} (Where are you off to?), {{上班啊？}} (Off to work?), {{你吃了吗？}} (Have you eaten?). They are greetings, not real questions, so a short answer is fine."},{"type":"tip","kind":"culture","text":"Chinese friends may ask your age, salary or whether you're married. This is usually friendly curiosity. If you'd rather not answer, smile and say {{保密！}} (bǎomì, ‘It's a secret!’)."},{"type":"tip","kind":"fun","text":"Temperatures are given in Celsius. {{零下五度}} (língxià wǔ dù) means −5 °C."},{"type":"steps","title":"Role-play: chat with a neighbour","items":[{"title":"Greet them","t":"早啊！","tr":"Zǎo a!","mean":"Morning!"},{"title":"Comment on the weather","t":"今天真热啊！","tr":"Jīntiān zhēn rè a!","mean":"It's so hot today!"},{"title":"Ask about the forecast","t":"明天会下雨吗？","tr":"Míngtiān huì xià yǔ ma?","mean":"Will it rain tomorrow?"},{"title":"Ask about their life","t":"最近忙吗？","tr":"Zuìjìn máng ma?","mean":"Busy lately?"},{"title":"Leave politely","t":"我先走了，回头见！","tr":"Wǒ xiān zǒu le, huítóu jiàn!","mean":"I'll be off, see you later!"}]},{"type":"practice","title":"Say it aloud","text":"Read each line aloud with feeling.","lines":["今天真冷啊！","今天真热啊！","明天会下雨吗？","你吃了吗？","最近忙不忙？","回头见！"]},{"type":"quiz","title":"Quick quiz","items":[{"q":"{{下雪}} means…","options":["to rain","to snow","to be windy","to be sunny"],"answer":1},{"q":"Listen. What is the speaker saying?","say":"今天真冷啊！","options":["It's really hot today","It will rain today","Today is very busy","It's really cold today"],"answer":3},{"q":"A neighbour greets you with {{你吃了吗？}}. A good reply is…","options":["吃了，你呢？","我不饿。","请我吃饭吧！","不要。"],"answer":0},{"q":"{{零下五度}} is…","options":["5 °C","15 °C","−5 °C","50 °C"],"answer":2},{"q":"You'd rather not say your salary. You can smile and say…","options":["保密！","没问题！","不客气！","再见！"],"answer":0},{"q":"{{天气预报}} is…","options":["an umbrella","a sunny day","the weather forecast","the temperature in degrees Celsius"],"answer":2}]}]},{"id":"u5-school-work","icon":"学","title":"At School & Work","subtitle":"Introduce yourself to classmates and colleagues and talk about your day.","minutes":15,"goals":["Introduce yourself at a new class or job","Talk about timetables, meetings and exams","Use titles and polite set phrases"],"blocks":[{"type":"text","text":"Starting at a new school or office? These words and phrases help you fit in from day one."},{"type":"vocab","title":"Key words","items":[{"t":"学校","tr":"xuéxiào","mean":"school"},{"t":"同学","tr":"tóngxué","mean":"classmate"},{"t":"上课","tr":"shàngkè","mean":"to have class; class starts"},{"t":"作业","tr":"zuòyè","mean":"homework"},{"t":"考试","tr":"kǎoshì","mean":"exam"},{"t":"公司","tr":"gōngsī","mean":"company"},{"t":"同事","tr":"tóngshì","mean":"colleague"},{"t":"上班","tr":"shàngbān","mean":"to go to work, start work"},{"t":"下班","tr":"xiàbān","mean":"to finish work"},{"t":"开会","tr":"kāihuì","mean":"to have a meeting"},{"t":"加班","tr":"jiābān","mean":"to work overtime"},{"t":"请假","tr":"qǐngjià","mean":"to ask for time off"}]},{"type":"dialogue","title":"First day at the office","lines":[{"who":"Manager Chen","t":"大家好，这位是新同事李乐。","tr":"Dàjiā hǎo, zhè wèi shì xīn tóngshì Lǐ Lè.","mean":"Hi everyone, this is our new colleague, Li Le."},{"who":"Li Le","t":"大家好！我叫李乐，请多关照！","tr":"Dàjiā hǎo! Wǒ jiào Lǐ Lè, qǐng duō guānzhào!","mean":"Hello everyone! I'm Li Le. I look forward to working with you!"},{"who":"Zhou Ting","t":"欢迎欢迎！我叫周婷，坐你旁边。","tr":"Huānyíng huānyíng! Wǒ jiào Zhōu Tíng, zuò nǐ pángbiān.","mean":"Welcome! I'm Zhou Ting. I sit next to you."},{"who":"Li Le","t":"你好！我们几点上班？","tr":"Nǐ hǎo! Wǒmen jǐ diǎn shàngbān?","mean":"Hi! What time do we start work?"},{"who":"Zhou Ting","t":"九点上班，六点下班，中午休息一个小时。","tr":"Jiǔ diǎn shàngbān, liù diǎn xiàbān, zhōngwǔ xiūxi yí ge xiǎoshí.","mean":"We start at 9 and finish at 6, with an hour's break at noon."},{"who":"Li Le","t":"经常加班吗？","tr":"Jīngcháng jiābān ma?","mean":"Do we often work overtime?"},{"who":"Zhou Ting","t":"有时候。对了，下午三点要开会。","tr":"Yǒu shíhou. Duì le, xiàwǔ sān diǎn yào kāihuì.","mean":"Sometimes. Oh, and there's a meeting at 3 p.m."},{"who":"Li Le","t":"在哪个会议室？","tr":"Zài nǎge huìyìshì?","mean":"In which meeting room?"},{"who":"Zhou Ting","t":"三楼的大会议室。中午一起去食堂吃饭吧！","tr":"Sān lóu de dà huìyìshì. Zhōngwǔ yìqǐ qù shítáng chī fàn ba!","mean":"The big one on the third floor. Let's go to the canteen together at lunch!"},{"who":"Li Le","t":"好啊，谢谢你！","tr":"Hǎo a, xièxie nǐ!","mean":"Great, thank you!"}]},{"type":"sentence","t":"老师，我可以问一个问题吗？","tr":"Lǎoshī, wǒ kěyǐ wèn yí ge wèntí ma?","mean":"Teacher, may I ask a question?","words":[{"t":"老师","mean":"teacher"},{"t":"我","mean":"I"},{"t":"可以","mean":"may"},{"t":"问","mean":"ask"},{"t":"一","mean":"one"},{"t":"个","mean":"(measure word)"},{"t":"问题","mean":"question"},{"t":"吗","mean":"(question word)"}]},{"type":"sentence","t":"明天有考试，我得复习。","tr":"Míngtiān yǒu kǎoshì, wǒ děi fùxí.","mean":"There's an exam tomorrow, so I have to revise.","words":[{"t":"明天","mean":"tomorrow"},{"t":"有","mean":"there is"},{"t":"考试","mean":"exam"},{"t":"我","mean":"I"},{"t":"得","mean":"have to"},{"t":"复习","mean":"revise"}]},{"type":"sentence","t":"我想请一天假。","tr":"Wǒ xiǎng qǐng yì tiān jià.","mean":"I'd like to take a day off.","words":[{"t":"我","mean":"I"},{"t":"想","mean":"would like"},{"t":"请","mean":"ask for"},{"t":"一","mean":"one"},{"t":"天","mean":"day"},{"t":"假","mean":"leave"}],"note":"{{请假}} splits around the length of time: {{请两天假}} = take two days off."},{"type":"tip","kind":"culture","text":"{{请多关照}} (qǐng duō guānzhào, ‘please look after me’) is a polite set phrase for a first day at work or school. Saying it makes a great first impression."},{"type":"tip","kind":"culture","text":"Use titles: surname + job title, like {{王经理}} (Manager Wang) or {{李老师}} (Teacher Li). Calling a teacher or boss by their given name alone can sound too casual."},{"type":"tip","kind":"culture","text":"The {{高考}} (gāokǎo), the national university entrance exam, takes place every June. It's a huge event: families plan around it and even traffic is kept quiet near exam halls."},{"type":"steps","title":"Role-play: your first day","items":[{"title":"Greet everyone","t":"大家好！","tr":"Dàjiā hǎo!","mean":"Hello everyone!"},{"title":"Say your name","t":"我叫马克。","tr":"Wǒ jiào Mǎkè.","mean":"My name is Mark.","desc":"Use your own name."},{"title":"Say who you are","t":"我是新来的同事。","tr":"Wǒ shì xīn lái de tóngshì.","mean":"I'm the new colleague.","desc":"At school, say {{新同学}} (new classmate) instead."},{"title":"Ask something practical","t":"请问，打印机在哪儿？","tr":"Qǐngwèn, dǎyìnjī zài nǎr?","mean":"Excuse me, where's the printer?"},{"title":"Finish politely","t":"请多关照！","tr":"Qǐng duō guānzhào!","mean":"I look forward to working with you!"}]},{"type":"practice","title":"Say it aloud","text":"Read each line aloud.","lines":["大家好！","请多关照！","几点上班？","下午要开会。","明天有考试。","我想请一天假。"]},{"type":"quiz","title":"Quick quiz","items":[{"q":"{{下班}} means…","options":["to start work","to work overtime","to have a meeting","to finish work"],"answer":3},{"q":"Listen. What's happening this afternoon?","say":"下午三点要开会。","options":["Work ends at 3 p.m.","A meeting at 3","Class starts at 3 p.m.","The exam is at 3 p.m."],"answer":1},{"q":"What do you say when you join a new team?","options":["请多关照！","多少钱？","不见不散！","买单！"],"answer":0},{"q":"How should you address Manager Wang?","options":["王","经理王","小王经理","王经理"],"answer":3},{"q":"{{同学}} means…","options":["colleague","classmate","teacher","manager"],"answer":1},{"q":"{{请假}} means…","options":["to take an exam","to work late overtime","to ask for leave","to do homework"],"answer":2}]}]}]});
LC.units.push({"id":"read","order":6,"icon":"读","color":"violet","title":"Reading & Culture","subtitle":"Graded stories, a Tang poem, chengyu, festivals and customs.","lessons":[{"id":"u6-story-sunday","icon":"日","title":"Story 1: Xiao Ming's Sunday","subtitle":"A first graded story (HSK 1): one boy, one relaxing day.","minutes":15,"goals":["Read a short story in characters","Understand time words: morning, afternoon, evening","Answer questions about the story"],"blocks":[{"type":"text","text":"Time for your first story! It uses only beginner (HSK 1) words. Read one sentence at a time, tap words you don't know, then read the whole story aloud."},{"type":"vocab","title":"Words in this story","items":[{"t":"星期天","tr":"xīngqītiān","mean":"Sunday"},{"t":"起床","tr":"qǐchuáng","mean":"to get up"},{"t":"早饭","tr":"zǎofàn","mean":"breakfast"},{"t":"包子","tr":"bāozi","mean":"steamed bun (with filling)"},{"t":"商店","tr":"shāngdiàn","mean":"shop"},{"t":"东西","tr":"dōngxi","mean":"thing(s), stuff"},{"t":"电视","tr":"diànshì","mean":"TV"},{"t":"累","tr":"lèi","mean":"tired"},{"t":"睡觉","tr":"shuìjiào","mean":"to sleep, go to bed"}]},{"type":"tip","kind":"tip","text":"Time words like {{早上}}, {{下午}} and {{晚上}} come at the start of the sentence or right after the subject, never at the end as in English."},{"type":"text","text":"**小明的星期天** (Xiǎo Míng de Xīngqītiān): Xiao Ming's Sunday","title":"The story"},{"type":"sentence","t":"今天是星期天。","tr":"Jīntiān shì xīngqītiān.","mean":"Today is Sunday.","words":[{"t":"今天","mean":"today"},{"t":"是","mean":"is"},{"t":"星期天","mean":"Sunday"}]},{"type":"sentence","t":"小明早上八点起床。","tr":"Xiǎo Míng zǎoshang bā diǎn qǐchuáng.","mean":"Xiao Ming gets up at eight in the morning.","words":[{"t":"小明","mean":"Xiao Ming"},{"t":"早上","mean":"in the morning"},{"t":"八点","mean":"eight o'clock"},{"t":"起床","mean":"gets up"}]},{"type":"sentence","t":"他和妈妈一起吃早饭。","tr":"Tā hé māma yìqǐ chī zǎofàn.","mean":"He has breakfast with his mum.","words":[{"t":"他","mean":"he"},{"t":"和","mean":"with"},{"t":"妈妈","mean":"mum"},{"t":"一起","mean":"together"},{"t":"吃","mean":"eat"},{"t":"早饭","mean":"breakfast"}]},{"type":"sentence","t":"他们吃包子，喝牛奶。","tr":"Tāmen chī bāozi, hē niúnǎi.","mean":"They eat steamed buns and drink milk.","words":[{"t":"他们","mean":"they"},{"t":"吃","mean":"eat"},{"t":"包子","mean":"steamed buns"},{"t":"喝","mean":"drink"},{"t":"牛奶","mean":"milk"}]},{"type":"sentence","t":"上午，小明去商店买东西。","tr":"Shàngwǔ, Xiǎo Míng qù shāngdiàn mǎi dōngxi.","mean":"In the morning, Xiao Ming goes to the shop to buy things.","words":[{"t":"上午","mean":"in the morning"},{"t":"小明","mean":"Xiao Ming"},{"t":"去","mean":"goes to"},{"t":"商店","mean":"shop"},{"t":"买","mean":"buy"},{"t":"东西","mean":"things"}]},{"type":"sentence","t":"他买了一个苹果和三本书。","tr":"Tā mǎi le yí ge píngguǒ hé sān běn shū.","mean":"He buys an apple and three books.","words":[{"t":"他","mean":"he"},{"t":"买了","mean":"bought"},{"t":"一个","mean":"one"},{"t":"苹果","mean":"apple"},{"t":"和","mean":"and"},{"t":"三","mean":"three"},{"t":"本","mean":"(measure word for books)"},{"t":"书","mean":"books"}]},{"type":"sentence","t":"下午，他的朋友来他家。","tr":"Xiàwǔ, tā de péngyou lái tā jiā.","mean":"In the afternoon, his friend comes to his home.","words":[{"t":"下午","mean":"in the afternoon"},{"t":"他的","mean":"his"},{"t":"朋友","mean":"friend"},{"t":"来","mean":"comes to"},{"t":"他","mean":"his"},{"t":"家","mean":"home"}]},{"type":"sentence","t":"他们一起看电视，很高兴。","tr":"Tāmen yìqǐ kàn diànshì, hěn gāoxìng.","mean":"They watch TV together and are very happy.","words":[{"t":"他们","mean":"they"},{"t":"一起","mean":"together"},{"t":"看","mean":"watch"},{"t":"电视","mean":"TV"},{"t":"很","mean":"very"},{"t":"高兴","mean":"happy"}]},{"type":"sentence","t":"晚上，小明很累，九点就睡觉了。","tr":"Wǎnshang, Xiǎo Míng hěn lèi, jiǔ diǎn jiù shuìjiào le.","mean":"In the evening Xiao Ming is tired, and he's asleep by nine.","words":[{"t":"晚上","mean":"in the evening"},{"t":"小明","mean":"Xiao Ming"},{"t":"很","mean":"very"},{"t":"累","mean":"tired"},{"t":"九点","mean":"nine o'clock"},{"t":"就","mean":"already"},{"t":"睡觉","mean":"sleep"},{"t":"了","mean":"(done)"}]},{"type":"practice","title":"Read the whole story","text":"Now read the whole story aloud without looking at the English.","lines":["今天是星期天。","小明早上八点起床。","他和妈妈一起吃早饭。","他们吃包子，喝牛奶。","上午，小明去商店买东西。","他买了一个苹果和三本书。","下午，他的朋友来他家。","他们一起看电视，很高兴。","晚上，小明很累，九点就睡觉了。"]},{"type":"quiz","title":"Did you understand?","items":[{"q":"What day is it in the story?","options":["Saturday","Monday","Sunday","Friday"],"answer":2},{"q":"What time does Xiao Ming get up?","options":["9:00","7:00","10:00","8:00"],"answer":3},{"q":"What do they have for breakfast?","options":["Steamed buns and milk","Fried rice and green tea","Noodles and juice","Dumplings and coffee"],"answer":0},{"q":"What does he buy at the shop?","options":["Three apples and a book","An apple and three books","Some bread and two pens for school","A TV"],"answer":1},{"q":"Listen. What are they doing?","say":"他们一起看电视。","options":["Reading books","Eating breakfast","Going to the shop","Watching TV"],"answer":3},{"q":"Why does he go to bed at nine?","options":["He is ill","He is sad","He is tired","He has school"],"answer":2}]}]},{"id":"u6-story-umbrella","icon":"伞","title":"Story 2: The Umbrella","subtitle":"A graded story (HSK 1–2) about a rainy day and a new friend.","minutes":15,"goals":["Read a longer story with past events","Learn the pattern 一边…一边… (while…)","Answer comprehension questions"],"blocks":[{"type":"text","text":"This story is a little longer and uses some HSK 2 words. Many Chinese names have a meaning: the girl's name, 小雨 (Xiǎoyǔ), means ‘light rain’."},{"type":"vocab","title":"Words in this story","items":[{"t":"大学生","tr":"dàxuéshēng","mean":"university student"},{"t":"名字","tr":"míngzi","mean":"name"},{"t":"可是","tr":"kěshì","mean":"but"},{"t":"带","tr":"dài","mean":"to take, bring along"},{"t":"伞","tr":"sǎn","mean":"umbrella"},{"t":"下课","tr":"xiàkè","mean":"class is over"},{"t":"外边","tr":"wàibian","mean":"outside"},{"t":"怎么办","tr":"zěnme bàn","mean":"what to do?"},{"t":"聊天","tr":"liáotiān","mean":"to chat"},{"t":"开始","tr":"kāishǐ","mean":"to begin, start"}]},{"type":"rule","name":"一边…一边… (while…)","color":"purple","desc":"Two actions happening at the same time: Subject + {{一边}} + action 1 + {{一边}} + action 2.","examples":[{"t":"他们一边走一边聊天。","tr":"Tāmen yìbiān zǒu yìbiān liáotiān.","hl":"一边"},{"t":"我一边吃饭一边看电视。","tr":"Wǒ yìbiān chī fàn yìbiān kàn diànshì.","hl":"一边"}]},{"type":"text","text":"**一把雨伞** (Yì bǎ yǔsǎn): The Umbrella","title":"The story"},{"type":"sentence","t":"王小雨是大学生。","tr":"Wáng Xiǎoyǔ shì dàxuéshēng.","mean":"Wang Xiaoyu is a university student.","words":[{"t":"王小雨","mean":"Wang Xiaoyu (a name)"},{"t":"是","mean":"is"},{"t":"大学生","mean":"university student"}]},{"type":"sentence","t":"她的名字里有“雨”，可是她不喜欢下雨。","tr":"Tā de míngzi li yǒu “yǔ”, kěshì tā bù xǐhuan xià yǔ.","mean":"Her name has “rain” in it, but she doesn't like rain.","words":[{"t":"她的","mean":"her"},{"t":"名字","mean":"name"},{"t":"里","mean":"in"},{"t":"有","mean":"has"},{"t":"雨","mean":"rain"},{"t":"可是","mean":"but"},{"t":"她","mean":"she"},{"t":"不","mean":"doesn't"},{"t":"喜欢","mean":"like"},{"t":"下雨","mean":"raining"}]},{"type":"sentence","t":"星期一早上天气很好，她没带伞就去上课了。","tr":"Xīngqīyī zǎoshang tiānqì hěn hǎo, tā méi dài sǎn jiù qù shàngkè le.","mean":"On Monday morning the weather was lovely, so she went to class without an umbrella.","words":[{"t":"星期一","mean":"Monday"},{"t":"早上","mean":"morning"},{"t":"天气","mean":"weather"},{"t":"很","mean":"very"},{"t":"好","mean":"good"},{"t":"她","mean":"she"},{"t":"没","mean":"didn't"},{"t":"带","mean":"take"},{"t":"伞","mean":"umbrella"},{"t":"就","mean":"then"},{"t":"去","mean":"go"},{"t":"上课","mean":"to class"},{"t":"了","mean":"(done)"}]},{"type":"sentence","t":"下午下课的时候，外边下大雨了。","tr":"Xiàwǔ xiàkè de shíhou, wàibian xià dà yǔ le.","mean":"In the afternoon, when class ended, it was pouring outside.","words":[{"t":"下午","mean":"afternoon"},{"t":"下课","mean":"class ends"},{"t":"的时候","mean":"when"},{"t":"外边","mean":"outside"},{"t":"下","mean":"falls"},{"t":"大雨","mean":"heavy rain"},{"t":"了","mean":"(now)"}]},{"type":"sentence","t":"小雨站在门口，不知道怎么办。","tr":"Xiǎoyǔ zhàn zài ménkǒu, bù zhīdào zěnme bàn.","mean":"Xiaoyu stood at the door, not knowing what to do.","words":[{"t":"小雨","mean":"Xiaoyu"},{"t":"站","mean":"stood"},{"t":"在","mean":"at"},{"t":"门口","mean":"the door"},{"t":"不","mean":"not"},{"t":"知道","mean":"know"},{"t":"怎么办","mean":"what to do"}]},{"type":"sentence","t":"这时候，一个男同学走了过来。","tr":"Zhè shíhou, yí ge nán tóngxué zǒu le guòlai.","mean":"Just then, a classmate came over.","words":[{"t":"这时候","mean":"just then"},{"t":"一个","mean":"a"},{"t":"男","mean":"male"},{"t":"同学","mean":"classmate"},{"t":"走","mean":"walked"},{"t":"了","mean":"(done)"},{"t":"过来","mean":"over (here)"}]},{"type":"sentence","t":"他说：“我的伞很大，我们一起走吧！”","tr":"Tā shuō: “Wǒ de sǎn hěn dà, wǒmen yìqǐ zǒu ba!”","mean":"He said: “My umbrella is big. Let's walk together!”","words":[{"t":"他","mean":"he"},{"t":"说","mean":"said"},{"t":"我的","mean":"my"},{"t":"伞","mean":"umbrella"},{"t":"很","mean":"very"},{"t":"大","mean":"big"},{"t":"我们","mean":"we"},{"t":"一起","mean":"together"},{"t":"走","mean":"walk"},{"t":"吧","mean":"(let's)"}]},{"type":"sentence","t":"他叫林阳，是她的同班同学。","tr":"Tā jiào Lín Yáng, shì tā de tóngbān tóngxué.","mean":"His name was Lin Yang, a classmate from her class.","words":[{"t":"他","mean":"he"},{"t":"叫","mean":"is called"},{"t":"林阳","mean":"Lin Yang"},{"t":"是","mean":"is"},{"t":"她的","mean":"her"},{"t":"同班","mean":"same class"},{"t":"同学","mean":"classmate"}]},{"type":"sentence","t":"他们一边走一边聊天，路好像变短了。","tr":"Tāmen yìbiān zǒu yìbiān liáotiān, lù hǎoxiàng biàn duǎn le.","mean":"They chatted as they walked, and the way home seemed to get shorter.","words":[{"t":"他们","mean":"they"},{"t":"一边","mean":"while"},{"t":"走","mean":"walk"},{"t":"一边","mean":"while"},{"t":"聊天","mean":"chat"},{"t":"路","mean":"road"},{"t":"好像","mean":"seemed to"},{"t":"变","mean":"become"},{"t":"短","mean":"short"},{"t":"了","mean":"(change)"}]},{"type":"sentence","t":"从那天起，小雨开始喜欢下雨天了。","tr":"Cóng nà tiān qǐ, Xiǎoyǔ kāishǐ xǐhuan xià yǔ tiān le.","mean":"From that day on, Xiaoyu began to like rainy days.","words":[{"t":"从","mean":"from"},{"t":"那天","mean":"that day"},{"t":"起","mean":"on"},{"t":"小雨","mean":"Xiaoyu"},{"t":"开始","mean":"began"},{"t":"喜欢","mean":"to like"},{"t":"下雨天","mean":"rainy days"},{"t":"了","mean":"(change)"}]},{"type":"practice","title":"Read the whole story","text":"Read the whole story aloud. Try to keep a smooth rhythm.","lines":["王小雨是大学生。","她的名字里有“雨”，可是她不喜欢下雨。","星期一早上天气很好，她没带伞就去上课了。","下午下课的时候，外边下大雨了。","小雨站在门口，不知道怎么办。","这时候，一个男同学走了过来。","他说：“我的伞很大，我们一起走吧！”","他叫林阳，是她的同班同学。","他们一边走一边聊天，路好像变短了。","从那天起，小雨开始喜欢下雨天了。"]},{"type":"quiz","title":"Did you understand?","items":[{"q":"What does {{雨}} in Xiaoyu's name mean?","options":["snow","rain","sun","wind"],"answer":1},{"q":"Why didn't she take an umbrella?","options":["The morning was sunny","Her umbrella was broken at home","She lost it on the bus","She doesn't own one"],"answer":0},{"q":"When did it start to pour?","options":["In the afternoon","Early on Monday morning","Late on Sunday night","During her lunch break"],"answer":0},{"q":"What did Lin Yang offer?","options":["To lend her his coat","To call a taxi","To share his umbrella","To wait inside until the rain stopped"],"answer":2},{"q":"Listen. What did he say?","say":"我们一起走吧！","options":["Let's take a taxi","Let's walk together","Let's wait here","Let's go home separately"],"answer":1},{"q":"{{一边走一边聊天}}: they walked and chatted…","options":["one after the other","only on rainy days","in different places","at the same time"],"answer":3},{"q":"How does Xiaoyu feel about rainy days at the end?","options":["She still hated them","She was afraid of them","She began to like them","She never thought about them again"],"answer":2}]}]},{"id":"u6-story-gift","icon":"礼","title":"Story 3: The Birthday Present","subtitle":"A graded story (HSK 2) about choosing a gift in China.","minutes":18,"goals":["Read a longer HSK 2 story","Learn why some gifts are avoided in China","Answer comprehension questions"],"blocks":[{"type":"text","text":"Your third story mixes reading with real culture. Anna wants to find the perfect birthday present for a Chinese friend, but some gifts are not what they seem!"},{"type":"vocab","title":"Words in this story","items":[{"t":"汉语","tr":"Hànyǔ","mean":"Chinese (language)"},{"t":"已经","tr":"yǐjīng","mean":"already"},{"t":"生日","tr":"shēngrì","mean":"birthday"},{"t":"送","tr":"sòng","mean":"to give (as a gift)"},{"t":"礼物","tr":"lǐwù","mean":"present, gift"},{"t":"钟","tr":"zhōng","mean":"clock"},{"t":"告诉","tr":"gàosu","mean":"to tell"},{"t":"蛋糕","tr":"dàngāo","mean":"cake"},{"t":"卡片","tr":"kǎpiàn","mean":"card"},{"t":"感动","tr":"gǎndòng","mean":"moved, touched"}]},{"type":"text","text":"**生日礼物** (Shēngrì lǐwù): The Birthday Present","title":"The story"},{"type":"sentence","t":"安娜在北京学习汉语已经一年了。","tr":"Ānnà zài Běijīng xuéxí Hànyǔ yǐjīng yì nián le.","mean":"Anna has been studying Chinese in Beijing for a year now.","words":[{"t":"安娜","mean":"Anna"},{"t":"在","mean":"in"},{"t":"北京","mean":"Beijing"},{"t":"学习","mean":"study"},{"t":"汉语","mean":"Chinese"},{"t":"已经","mean":"already"},{"t":"一年","mean":"one year"},{"t":"了","mean":"(so far)"}]},{"type":"sentence","t":"下个星期六是她的中国朋友小美的生日。","tr":"Xià ge xīngqīliù shì tā de Zhōngguó péngyou Xiǎoměi de shēngrì.","mean":"Next Saturday is her Chinese friend Xiaomei's birthday.","words":[{"t":"下个","mean":"next"},{"t":"星期六","mean":"Saturday"},{"t":"是","mean":"is"},{"t":"她的","mean":"her"},{"t":"中国","mean":"Chinese"},{"t":"朋友","mean":"friend"},{"t":"小美","mean":"Xiaomei"},{"t":"的","mean":"('s)"},{"t":"生日","mean":"birthday"}]},{"type":"sentence","t":"安娜想送她一个礼物，可是不知道送什么。","tr":"Ānnà xiǎng sòng tā yí ge lǐwù, kěshì bù zhīdào sòng shénme.","mean":"Anna wants to give her a present, but she doesn't know what to give.","words":[{"t":"安娜","mean":"Anna"},{"t":"想","mean":"wants"},{"t":"送","mean":"give"},{"t":"她","mean":"her"},{"t":"一个","mean":"a"},{"t":"礼物","mean":"present"},{"t":"可是","mean":"but"},{"t":"不","mean":"doesn't"},{"t":"知道","mean":"know"},{"t":"送","mean":"give"},{"t":"什么","mean":"what"}]},{"type":"sentence","t":"她想买一个漂亮的钟。","tr":"Tā xiǎng mǎi yí ge piàoliang de zhōng.","mean":"She thinks of buying a pretty clock.","words":[{"t":"她","mean":"she"},{"t":"想","mean":"wants"},{"t":"买","mean":"buy"},{"t":"一个","mean":"a"},{"t":"漂亮的","mean":"pretty"},{"t":"钟","mean":"clock"}]},{"type":"sentence","t":"可是同学告诉她：“在中国，不能送钟。”","tr":"Kěshì tóngxué gàosu tā: “Zài Zhōngguó, bù néng sòng zhōng.”","mean":"But a classmate tells her: “In China, you can't give a clock.”","words":[{"t":"可是","mean":"but"},{"t":"同学","mean":"classmate"},{"t":"告诉","mean":"tells"},{"t":"她","mean":"her"},{"t":"在","mean":"in"},{"t":"中国","mean":"China"},{"t":"不能","mean":"can't"},{"t":"送","mean":"give"},{"t":"钟","mean":"clock"}],"note":"{{送钟}} (sòng zhōng, give a clock) sounds just like {{送终}} (sòngzhōng), caring for someone at their death."},{"type":"sentence","t":"安娜又想送一把伞，同学说这也不太好。","tr":"Ānnà yòu xiǎng sòng yì bǎ sǎn, tóngxué shuō zhè yě bú tài hǎo.","mean":"Then Anna thinks of an umbrella, but her classmate says that's not great either.","words":[{"t":"安娜","mean":"Anna"},{"t":"又","mean":"then (again)"},{"t":"想","mean":"thinks of"},{"t":"送","mean":"giving"},{"t":"一把","mean":"an"},{"t":"伞","mean":"umbrella"},{"t":"同学","mean":"classmate"},{"t":"说","mean":"says"},{"t":"这","mean":"this"},{"t":"也","mean":"also"},{"t":"不太","mean":"not very"},{"t":"好","mean":"good"}],"note":"{{伞}} (sǎn) sounds like {{散}} (sàn), ‘to break up, separate’."},{"type":"sentence","t":"最后，安娜自己做了一个蛋糕，还写了一张中文卡片。","tr":"Zuìhòu, Ānnà zìjǐ zuò le yí ge dàngāo, hái xiě le yì zhāng Zhōngwén kǎpiàn.","mean":"In the end, Anna bakes a cake herself and writes a card in Chinese.","words":[{"t":"最后","mean":"in the end"},{"t":"安娜","mean":"Anna"},{"t":"自己","mean":"herself"},{"t":"做了","mean":"made"},{"t":"一个","mean":"a"},{"t":"蛋糕","mean":"cake"},{"t":"还","mean":"also"},{"t":"写了","mean":"wrote"},{"t":"一张","mean":"a (measure word for flat things)"},{"t":"中文","mean":"Chinese"},{"t":"卡片","mean":"card"}]},{"type":"sentence","t":"卡片上写着：“祝你生日快乐，天天开心！”","tr":"Kǎpiàn shang xiězhe: “Zhù nǐ shēngrì kuàilè, tiāntiān kāixīn!”","mean":"The card says: “Happy birthday! Be happy every day!”","words":[{"t":"卡片","mean":"card"},{"t":"上","mean":"on"},{"t":"写着","mean":"is written"},{"t":"祝","mean":"wish"},{"t":"你","mean":"you"},{"t":"生日","mean":"birthday"},{"t":"快乐","mean":"happy"},{"t":"天天","mean":"every day"},{"t":"开心","mean":"happy"}]},{"type":"sentence","t":"小美看了很感动：“这是我最喜欢的礼物！”","tr":"Xiǎoměi kàn le hěn gǎndòng: “Zhè shì wǒ zuì xǐhuan de lǐwù!”","mean":"Xiaomei reads it and is very touched: “This is my favourite present!”","words":[{"t":"小美","mean":"Xiaomei"},{"t":"看了","mean":"read it"},{"t":"很","mean":"very"},{"t":"感动","mean":"touched"},{"t":"这","mean":"this"},{"t":"是","mean":"is"},{"t":"我","mean":"my"},{"t":"最","mean":"most"},{"t":"喜欢","mean":"liked"},{"t":"的","mean":"(that)"},{"t":"礼物","mean":"present"}]},{"type":"tip","kind":"culture","text":"Hand-made gifts and cards written in Chinese are always appreciated. Your effort matters more than the price."},{"type":"practice","title":"Read the whole story","text":"Read the whole story aloud.","lines":["安娜在北京学习汉语已经一年了。","下个星期六是她的中国朋友小美的生日。","安娜想送她一个礼物，可是不知道送什么。","她想买一个漂亮的钟。","可是同学告诉她：“在中国，不能送钟。”","安娜又想送一把伞，同学说这也不太好。","最后，安娜自己做了一个蛋糕，还写了一张中文卡片。","卡片上写着：“祝你生日快乐，天天开心！”","小美看了很感动：“这是我最喜欢的礼物！”"]},{"type":"quiz","title":"Did you understand?","items":[{"q":"How long has Anna studied Chinese in Beijing?","options":["One month","One year","Two years","Six months"],"answer":1},{"q":"Why shouldn't you give a clock?","options":["Clocks are too cheap","Clocks are much too expensive","Nobody uses clocks now","It sounds unlucky"],"answer":3},{"q":"What's the problem with giving an umbrella?","options":["It sounds like “split up”","It's only a gift for old people","It means bad weather","It's too big"],"answer":0},{"q":"What does Anna give in the end?","options":["A cake she made and a card","An expensive clock from a shop","A big red umbrella and a hat","A book"],"answer":0},{"q":"Listen. What does the card say?","say":"祝你生日快乐！","options":["Happy New Year","Happy birthday to you","Thank you for the present","Good luck in your exam"],"answer":1},{"q":"{{感动}} means…","options":["a little bit angry","very surprised","really tired","moved, touched"],"answer":3}]}]},{"id":"u6-poem","icon":"月","title":"Poem: Quiet Night Thoughts","subtitle":"Li Bai's famous Tang poem 《静夜思》, line by line.","minutes":15,"goals":["Read and understand 《静夜思》 line by line","Recite the poem with a natural rhythm","Compare poetic words with modern ones"],"blocks":[{"type":"text","text":"《静夜思》 (Jìng Yè Sī, ‘Quiet Night Thoughts’) was written by **Li Bai** ({{李白}}, 701–762), one of the greatest poets of the Tang dynasty. Almost every Chinese child learns it by heart. It's short, simple and beautiful: a traveller sees moonlight and misses home."},{"type":"vocab","title":"Words in the poem","items":[{"t":"李白","tr":"Lǐ Bái","mean":"Li Bai, Tang dynasty poet"},{"t":"明月","tr":"míngyuè","mean":"bright moon"},{"t":"光","tr":"guāng","mean":"light"},{"t":"霜","tr":"shuāng","mean":"frost"},{"t":"举头","tr":"jǔ tóu","mean":"to raise your head"},{"t":"低头","tr":"dī tóu","mean":"to lower your head"},{"t":"故乡","tr":"gùxiāng","mean":"hometown (literary)"}]},{"type":"text","text":"**静夜思** · 李白 (Jìng Yè Sī · Lǐ Bái)","title":"The poem, line by line"},{"type":"sentence","t":"床前明月光，","tr":"Chuáng qián míng yuè guāng,","mean":"Before my bed, the bright moonlight shines;","words":[{"t":"床","mean":"bed"},{"t":"前","mean":"in front of"},{"t":"明","mean":"bright"},{"t":"月","mean":"moon"},{"t":"光","mean":"light"}]},{"type":"sentence","t":"疑是地上霜。","tr":"yí shì dì shàng shuāng.","mean":"I wonder if it's frost upon the ground.","words":[{"t":"疑","mean":"wonder, suspect"},{"t":"是","mean":"is"},{"t":"地","mean":"ground"},{"t":"上","mean":"on"},{"t":"霜","mean":"frost"}]},{"type":"sentence","t":"举头望明月，","tr":"Jǔ tóu wàng míng yuè,","mean":"I raise my head and gaze at the bright moon;","words":[{"t":"举","mean":"raise"},{"t":"头","mean":"head"},{"t":"望","mean":"gaze at"},{"t":"明","mean":"bright"},{"t":"月","mean":"moon"}]},{"type":"sentence","t":"低头思故乡。","tr":"dī tóu sī gùxiāng.","mean":"I lower my head and think of home.","words":[{"t":"低","mean":"lower"},{"t":"头","mean":"head"},{"t":"思","mean":"think of, miss"},{"t":"故乡","mean":"hometown"}]},{"type":"compare","title":"Poetic vs everyday words","items":[{"t":"望","label":"wàng (poetic)","desc":"To gaze into the distance. In everyday speech: {{看}} (kàn)."},{"t":"思","label":"sī (literary)","desc":"To think of, to miss. In everyday speech: {{想}} (xiǎng)."},{"t":"故乡","label":"gùxiāng (literary)","desc":"Hometown. In everyday speech: {{老家}} (lǎojiā)."}]},{"type":"tip","kind":"fun","text":"The poem has 4 lines of 5 characters, a form called {{五言绝句}} (wǔyán juéjù). Lines 1, 2 and 4 rhyme: guāng, shuāng, xiāng."},{"type":"tip","kind":"culture","text":"Scholars still debate what {{床}} means here. Today it means ‘bed’, but some think Li Bai meant a folding seat or the railing around a well. Either way, the feeling of homesickness is the same."},{"type":"tip","kind":"culture","text":"The poem is a favourite at the Mid-Autumn Festival, when the moon is full and people think of family far away."},{"type":"steps","title":"How to recite it","items":[{"title":"Read slowly in 2 + 3 beats","t":"床前，明月光，","tr":"Chuáng qián, míng yuè guāng,","mean":"Before my bed, bright moonlight,","desc":"Make a tiny pause after the second character of every line."},{"title":"Stretch the rhyme","t":"疑是地上霜。","tr":"Yí shì dì shàng shuāng.","mean":"I wonder if it's frost on the ground.","desc":"Let the last syllable of lines 1, 2 and 4 ring a little longer."},{"title":"Look up as you say line 3","t":"举头望明月，","tr":"Jǔ tóu wàng míng yuè,","mean":"I raise my head and gaze at the moon,","desc":"Acting it out helps you remember."},{"title":"Look down for line 4","t":"低头思故乡。","tr":"Dī tóu sī gùxiāng.","mean":"I lower my head and think of home."}]},{"type":"write","level":"line","items":["床前明月光","疑是地上霜","举头望明月","低头思故乡"],"note":"Copy each line in your notebook, saying it aloud as you write."},{"type":"practice","title":"Recite the poem","text":"Recite the whole poem. Then try it from memory!","lines":["床前明月光，","疑是地上霜。","举头望明月，","低头思故乡。"]},{"type":"quiz","title":"Quick quiz","items":[{"q":"Who wrote 《静夜思》?","options":["Du Fu (杜甫)","Confucius (孔子)","Li Bai (李白)","Lu Xun (鲁迅)"],"answer":2},{"q":"At first, what does the poet think the moonlight is?","options":["Snow falling on the mountains","Frost on the ground","A lamp by the bed","Water in the river"],"answer":1},{"q":"{{故乡}} means…","options":["old friend","far away","hometown","the night sky"],"answer":2},{"q":"Listen. Which line is this?","say":"举头望明月","options":["举头望明月","低头思故乡","床前明月光","疑是地上霜"],"answer":0},{"q":"Li Bai lived during which dynasty?","options":["Song","Ming","Qing","Tang"],"answer":3},{"q":"Which words rhyme in the poem?","options":["床, 月, 头","前, 是, 望","明, 举, 低","光, 霜, 乡"],"answer":3},{"q":"In everyday Chinese, {{思}} (to miss) is usually…","options":["看 (kàn)","想 (xiǎng)","说 (shuō)","听 (tīng)"],"answer":1}]}]},{"id":"u6-chengyu","icon":"成","title":"Chengyu & Everyday Sayings","subtitle":"Four-character idioms and sayings that make your Chinese shine.","minutes":15,"goals":["Know what a chengyu is","Use a few common chengyu and sayings","Learn two famous idiom stories"],"blocks":[{"type":"text","text":"A {{成语}} (chéngyǔ) is a fixed idiom, usually four characters long. Many come from old stories or classic books. Using one at the right moment always impresses Chinese speakers!"},{"type":"rule","name":"What makes a chengyu","color":"orange","desc":"Usually 4 characters, fixed word order, a meaning that is more than the sum of its parts.","examples":[{"t":"一举两得","tr":"yì jǔ liǎng dé"},{"t":"入乡随俗","tr":"rù xiāng suí sú"}],"how":"Learn the literal meaning AND the real meaning, plus when to use it."},{"type":"examples","items":[{"t":"一路平安","tr":"yí lù píng'ān","mean":"Have a safe trip!","note":"Literally: ‘the whole road, peace’. Say it to someone setting off."},{"t":"熟能生巧","tr":"shú néng shēng qiǎo","mean":"Practice makes perfect.","note":"Literally: ‘familiarity gives birth to skill’."},{"t":"入乡随俗","tr":"rù xiāng suí sú","mean":"When in Rome, do as the Romans do.","note":"Literally: ‘enter a village, follow its customs’."},{"t":"一举两得","tr":"yì jǔ liǎng dé","mean":"Kill two birds with one stone.","note":"Literally: ‘one action, two gains’."},{"t":"马马虎虎","tr":"mǎmǎhūhū","mean":"So-so; careless.","note":"Literally: ‘horse horse tiger tiger’."},{"t":"对牛弹琴","tr":"duì niú tán qín","mean":"To talk to the wrong audience.","note":"Literally: ‘play the zither to a cow’."},{"t":"半途而废","tr":"bàn tú ér fèi","mean":"To give up halfway.","note":"Literally: ‘stop halfway along the road’."},{"t":"马到成功","tr":"mǎ dào chéng gōng","mean":"Instant success! (a good-luck wish)","note":"Literally: ‘the horse arrives, success’."}],"title":"Useful chengyu"},{"type":"tip","kind":"fun","text":"**守株待兔** (shǒu zhū dài tù): A farmer saw a rabbit run into a tree stump and die. He stopped farming and waited by the stump every day for another rabbit. None came, and his fields went to weeds. It means waiting for luck instead of working.","title":"Story: waiting by the stump"},{"type":"tip","kind":"fun","text":"**画蛇添足** (huà shé tiān zú): Some friends raced to draw a snake to win a cup of wine. The fastest finished, then decided to add feet. Another man finished and took the wine: ‘Snakes don't have feet!’ It means spoiling something by adding what isn't needed.","title":"Story: drawing feet on a snake"},{"type":"examples","items":[{"t":"慢慢来","tr":"màn màn lái","mean":"Take your time; no rush."},{"t":"活到老，学到老","tr":"huó dào lǎo, xué dào lǎo","mean":"You're never too old to learn."},{"t":"百闻不如一见","tr":"bǎi wén bù rú yí jiàn","mean":"Seeing once beats hearing a hundred times."},{"t":"千里之行，始于足下","tr":"qiān lǐ zhī xíng, shǐ yú zú xià","mean":"A journey of a thousand li begins with a single step.","note":"From the {{道德经}} (Dào Dé Jīng). A {{里}} (lǐ) is a traditional unit of distance."},{"t":"三人行，必有我师","tr":"sān rén xíng, bì yǒu wǒ shī","mean":"Among any three people, one can teach me something.","note":"Adapted from the Analects of Confucius."}],"title":"Everyday sayings"},{"type":"sentence","t":"学汉语要慢慢来。","tr":"Xué Hànyǔ yào màn màn lái.","mean":"Learning Chinese takes time; go step by step.","words":[{"t":"学","mean":"learn"},{"t":"汉语","mean":"Chinese"},{"t":"要","mean":"need to"},{"t":"慢慢来","mean":"take it slowly"}]},{"type":"sentence","t":"熟能生巧，每天练习吧！","tr":"Shú néng shēng qiǎo, měitiān liànxí ba!","mean":"Practice makes perfect, so practise every day!","words":[{"t":"熟能生巧","mean":"practice makes perfect"},{"t":"每天","mean":"every day"},{"t":"练习","mean":"practise"},{"t":"吧","mean":"(let's)"}]},{"type":"sentence","t":"祝你一路平安！","tr":"Zhù nǐ yí lù píng'ān!","mean":"Have a safe trip!","words":[{"t":"祝","mean":"wish"},{"t":"你","mean":"you"},{"t":"一路平安","mean":"a safe journey"}]},{"type":"tip","kind":"warn","text":"Chengyu are powerful but easy to overuse. One well-chosen chengyu in a conversation is great; five in a row sounds like a textbook!"},{"type":"practice","title":"Say it aloud","text":"Read each chengyu and saying aloud. Say the meaning in English after each one.","lines":["一路平安","熟能生巧","入乡随俗","一举两得","马马虎虎","慢慢来","活到老，学到老"]},{"type":"quiz","title":"Quick quiz","items":[{"q":"How many characters does a typical chengyu have?","options":["Four","Two","Six","Eight"],"answer":0},{"q":"Which chengyu means “When in Rome, do as the Romans do”?","options":["一举两得","半途而废","入乡随俗","对牛弹琴"],"answer":2},{"q":"{{画蛇添足}} (drawing feet on a snake) describes…","options":["working hard until the job is done","being lucky","adding something useless","drawing well"],"answer":2},{"q":"Listen. What does this mean?","say":"熟能生巧","options":["Practice makes perfect","Have a safe trip","Take your time","Never too old to learn"],"answer":0},{"q":"A friend is leaving for the airport. What do you say?","options":["马马虎虎！","一路平安！","半途而废！","对牛弹琴！"],"answer":1},{"q":"{{守株待兔}} warns against…","options":["hunting rabbits in the forest","cutting down old trees","farming in winter","waiting for luck"],"answer":3},{"q":"{{马马虎虎}}, literally ‘horse horse tiger tiger’, means…","options":["so-so, careless","very brave","fast and strong","wild animals"],"answer":0}]}]},{"id":"u6-festivals","icon":"节","title":"Chinese Festivals","subtitle":"Spring Festival, Mid-Autumn and Dragon Boat: food, customs and greetings.","minutes":18,"goals":["Name the three big traditional festivals","Know their foods, customs and greetings","Understand puns behind festival traditions"],"blocks":[{"type":"text","text":"Traditional Chinese festivals follow the lunar calendar, so their dates change every year on the Western calendar. Each one has its own food, stories and greetings."},{"type":"table","head":["Festival","When","Food","Greeting"],"rows":[["{{春节}} Spring Festival","1st day of the 1st lunar month (late Jan to mid Feb)","{{饺子}}, fish, {{年糕}}","{{新年快乐！}} {{过年好！}}"],["{{中秋节}} Mid-Autumn Festival","15th day of the 8th lunar month (Sept or early Oct)","{{月饼}} mooncakes","{{中秋快乐！}}"],["{{端午节}} Dragon Boat Festival","5th day of the 5th lunar month (usually June)","{{粽子}} sticky rice in bamboo leaves","{{端午安康！}}"]],"title":"Three big festivals"},{"type":"vocab","title":"Festival words","items":[{"t":"春节","tr":"Chūn Jié","mean":"Spring Festival, Chinese New Year"},{"t":"除夕","tr":"Chúxī","mean":"New Year's Eve (lunar)"},{"t":"年夜饭","tr":"niányèfàn","mean":"New Year's Eve reunion dinner"},{"t":"红包","tr":"hóngbāo","mean":"red envelope (with money)"},{"t":"春联","tr":"chūnlián","mean":"New Year couplets (red door poems)"},{"t":"恭喜发财","tr":"gōngxǐ fācái","mean":"wishing you prosperity!"},{"t":"中秋节","tr":"Zhōngqiū Jié","mean":"Mid-Autumn Festival"},{"t":"月饼","tr":"yuèbing","mean":"mooncake"},{"t":"赏月","tr":"shǎng yuè","mean":"to admire the moon"},{"t":"端午节","tr":"Duānwǔ Jié","mean":"Dragon Boat Festival"},{"t":"粽子","tr":"zòngzi","mean":"sticky rice wrapped in bamboo leaves"},{"t":"龙舟","tr":"lóngzhōu","mean":"dragon boat"}]},{"type":"dialogue","title":"Going home for the New Year","lines":[{"who":"Mia","t":"春节你回老家吗？","tr":"Chūn Jié nǐ huí lǎojiā ma?","mean":"Are you going back to your hometown for Spring Festival?"},{"who":"Xiao Zhang","t":"回！我们全家一起吃年夜饭。","tr":"Huí! Wǒmen quán jiā yìqǐ chī niányèfàn.","mean":"Yes! My whole family has the reunion dinner together."},{"who":"Mia","t":"你们吃什么？","tr":"Nǐmen chī shénme?","mean":"What do you eat?"},{"who":"Xiao Zhang","t":"饺子、鱼，还有很多菜。年年有余嘛！","tr":"Jiǎozi, yú, hái yǒu hěn duō cài. Nián nián yǒu yú ma!","mean":"Dumplings, fish and lots of dishes. ‘Surplus every year’, you know!"},{"who":"Mia","t":"你会收到红包吗？","tr":"Nǐ huì shōudào hóngbāo ma?","mean":"Will you get red envelopes?"},{"who":"Xiao Zhang","t":"当然！奶奶每年都给我红包。","tr":"Dāngrán! Nǎinai měi nián dōu gěi wǒ hóngbāo.","mean":"Of course! Grandma gives me one every year."},{"who":"Mia","t":"那我先祝你新年快乐！","tr":"Nà wǒ xiān zhù nǐ xīnnián kuàilè!","mean":"Then let me wish you a happy New Year in advance!"},{"who":"Xiao Zhang","t":"谢谢！也祝你新年快乐！","tr":"Xièxie! Yě zhù nǐ xīnnián kuàilè!","mean":"Thanks! Happy New Year to you too!"}]},{"type":"tip","kind":"memory","text":"Fish ({{鱼}}, yú) sounds like {{余}} (yú, ‘surplus’), so {{年年有余}} means ‘may you have more than enough every year’. That's why fish is served at the New Year's Eve dinner."},{"type":"tip","kind":"culture","text":"You'll see {{福}} (fú, good fortune) hung upside down on doors. ‘Upside down’ is {{倒}} (dào), which sounds like {{到}} (dào, ‘to arrive’): good fortune has arrived!"},{"type":"tip","kind":"culture","text":"Red envelopes ({{红包}}) are given by older relatives to children, and by married adults to younger unmarried relatives. Amounts with 8 are popular and amounts with 4 are avoided. Many people now also send digital red envelopes on WeChat."},{"type":"sentence","t":"中秋节我们一起吃月饼、赏月。","tr":"Zhōngqiū Jié wǒmen yìqǐ chī yuèbing, shǎng yuè.","mean":"At Mid-Autumn we eat mooncakes and admire the moon together.","words":[{"t":"中秋节","mean":"Mid-Autumn Festival"},{"t":"我们","mean":"we"},{"t":"一起","mean":"together"},{"t":"吃","mean":"eat"},{"t":"月饼","mean":"mooncakes"},{"t":"赏月","mean":"admire the moon"}]},{"type":"tip","kind":"culture","text":"Mid-Autumn is a time for family reunion ({{团圆}}, tuányuán). The legend says the goddess {{嫦娥}} (Cháng'é) lives on the moon with a jade rabbit. China's moon probes are named Chang'e after her."},{"type":"sentence","t":"端午节有龙舟比赛。","tr":"Duānwǔ Jié yǒu lóngzhōu bǐsài.","mean":"There are dragon boat races at the Dragon Boat Festival.","words":[{"t":"端午节","mean":"Dragon Boat Festival"},{"t":"有","mean":"there are"},{"t":"龙舟","mean":"dragon boat"},{"t":"比赛","mean":"races"}]},{"type":"tip","kind":"culture","text":"The Dragon Boat Festival remembers the poet {{屈原}} (Qū Yuán), who drowned himself in the Miluo River about 2,300 years ago. Legend says people raced out in boats to find him. Because of this sad origin, many people prefer the greeting {{端午安康}} (‘peace and health’)."},{"type":"tip","kind":"fun","text":"The Spring Festival season ends with the Lantern Festival ({{元宵节}}, Yuánxiāo Jié) on the 15th day, with lanterns, riddles and sweet rice balls ({{汤圆}}, tāngyuán)."},{"type":"steps","title":"Role-play: Spring Festival greetings","items":[{"title":"Greet friends","t":"新年快乐！","tr":"Xīnnián kuàilè!","mean":"Happy New Year!"},{"title":"Greet older relatives","t":"过年好！","tr":"Guònián hǎo!","mean":"Happy New Year!","desc":"A warm, traditional greeting, often said to elders."},{"title":"Wish prosperity","t":"恭喜发财！","tr":"Gōngxǐ fācái!","mean":"Wishing you prosperity!","desc":"Children sometimes cheekily add {{红包拿来！}}: ‘now hand over the red envelope!’"},{"title":"Wish good health","t":"身体健康！","tr":"Shēntǐ jiànkāng!","mean":"Good health!"},{"title":"Wish surplus","t":"年年有余！","tr":"Nián nián yǒu yú!","mean":"Plenty every year!"}]},{"type":"practice","title":"Say it aloud","text":"Read each festival greeting aloud.","lines":["新年快乐！","过年好！","恭喜发财！","中秋快乐！","端午安康！","年年有余！"]},{"type":"quiz","title":"Quick quiz","items":[{"q":"When is the Spring Festival?","options":["Always on 1 January every year","In the middle of summer","Every October 1st","Late Jan to mid Feb"],"answer":3},{"q":"What do people eat at the Mid-Autumn Festival?","options":["粽子 rice in leaves","汤圆 sweet rice balls","月饼 mooncakes","饺子 dumplings"],"answer":2},{"q":"Listen. What is the greeting?","say":"新年快乐！","options":["Happy birthday","Happy New Year","Happy Mid-Autumn","Have a safe trip"],"answer":1},{"q":"Why is {{福}} hung upside down?","options":["It's an old printing mistake","To keep away the winter cold","A pun on “arrived”","So children can read it"],"answer":2},{"q":"The Dragon Boat Festival remembers…","options":["the moon goddess Chang'e","the poet Qu Yuan","the first emperor","Confucius"],"answer":1},{"q":"Why is fish served at the New Year's Eve dinner?","options":["It's the cheapest dish","Fish is the national animal","Children love fish most of all","Its name sounds like “surplus”"],"answer":3},{"q":"A {{红包}} is…","options":["a red envelope with money","a red paper lantern for the door","a New Year poem","a firecracker"],"answer":0}]}]},{"id":"u6-customs","icon":"福","title":"Culture Tips: Names, Gifts, Numbers & Table Manners","subtitle":"Everyday customs that help you make a great impression.","minutes":18,"goals":["Understand Chinese names and titles","Give and receive gifts politely","Know lucky and unlucky numbers","Follow basic table manners"],"blocks":[{"type":"text","text":"Good manners open doors everywhere. These tips cover the situations visitors meet most: names, gifts, numbers and meals. Customs vary by region and family, so watch what others do and follow along."},{"type":"text","text":"In Chinese names the **surname comes first**. In {{王小明}}, {{王}} (Wáng) is the surname and {{小明}} (Xiǎomíng) the given name. The most common surnames include {{王}}, {{李}}, {{张}}, {{刘}} and {{陈}}.","title":"Names"},{"type":"table","head":["Title","Pinyin","Use it for"],"rows":[["{{王先生}}","Wáng xiānsheng","Mr Wang"],["{{王女士}}","Wáng nǚshì","Ms Wang"],["{{王老师}}","Wáng lǎoshī","Teacher Wang (also polite for respected professionals)"],["{{小王}}","Xiǎo Wáng","a younger friend or colleague"],["{{老王}}","Lǎo Wáng","an older friend or colleague (friendly, not rude)"],["{{阿姨}} / {{叔叔}}","āyí / shūshu","auntie / uncle: any adult of your parents' age"]],"title":"Titles and forms of address"},{"type":"sentence","t":"您贵姓？","tr":"Nín guìxìng?","mean":"What's your surname? (very polite)","words":[{"t":"您","mean":"you (polite)"},{"t":"贵姓","mean":"honourable surname"}],"note":"Answer with {{我姓……}}, e.g. {{我姓李}} (My surname is Li)."},{"type":"text","text":"Bring a small gift when you visit someone's home: fruit, tea, sweets or something from your country. Give and receive gifts **with both hands**.","title":"Gifts"},{"type":"sentence","t":"一点儿小意思，请收下。","tr":"Yìdiǎnr xiǎo yìsi, qǐng shōuxià.","mean":"Just a little something, please accept it.","words":[{"t":"一点儿","mean":"a little"},{"t":"小意思","mean":"small token"},{"t":"请","mean":"please"},{"t":"收下","mean":"accept"}]},{"type":"tip","kind":"culture","text":"People may politely refuse a gift once or twice before accepting, so offer again kindly. Gifts are often not opened in front of the giver."},{"type":"tip","kind":"warn","text":"Traditionally avoided gifts: clocks ({{钟}}, sounds like ‘end of life’), umbrellas ({{伞}}, sounds like ‘separate’), pears to share ({{梨}} lí sounds like {{离}} lí, ‘to part’) and green hats (a joke about an unfaithful partner). Red and gold wrapping is festive; plain white or black is linked to funerals."},{"type":"examples","items":[{"t":"八","tr":"bā","mean":"8: sounds like {{发}} (fā, to prosper). The luckiest number!"},{"t":"六","tr":"liù","mean":"6: {{六六大顺}}, ‘everything goes smoothly’."},{"t":"九","tr":"jiǔ","mean":"9: sounds like {{久}} (jiǔ, long-lasting). Lucky for love and long life."},{"t":"四","tr":"sì","mean":"4: sounds like {{死}} (sǐ, death). Some buildings skip 4th floors."},{"t":"五二零","tr":"wǔ èr líng","mean":"520: sounds a bit like {{我爱你}} (I love you). 20 May is an online ‘love day’."}],"title":"Lucky and unlucky numbers"},{"type":"tip","kind":"fun","text":"The Beijing Olympics opened on 8 August 2008 at 8:08 p.m. Lucky eights everywhere!"},{"type":"text","text":"At a meal, wait for the host or the eldest person to start. The host often orders and may put food in your bowl as a kind gesture.","title":"Table manners"},{"type":"vocab","title":"At the table","items":[{"t":"筷子","tr":"kuàizi","mean":"chopsticks"},{"t":"干杯","tr":"gānbēi","mean":"cheers! (literally ‘dry the glass’)"},{"t":"敬酒","tr":"jìngjiǔ","mean":"to propose a toast"},{"t":"随意","tr":"suíyì","mean":"as you like (drink as much as you want)"},{"t":"请客","tr":"qǐngkè","mean":"to treat (pay for others)"}]},{"type":"sentence","t":"我敬您一杯！","tr":"Wǒ jìng nín yì bēi!","mean":"Let me drink a toast to you!","words":[{"t":"我","mean":"I"},{"t":"敬","mean":"respectfully toast"},{"t":"您","mean":"you (polite)"},{"t":"一杯","mean":"a glass"}]},{"type":"sentence","t":"大家慢慢吃。","tr":"Dàjiā mànmàn chī.","mean":"Enjoy your meal, everyone.","words":[{"t":"大家","mean":"everyone"},{"t":"慢慢","mean":"slowly"},{"t":"吃","mean":"eat"}],"note":"Say this if you finish and leave the table before others."},{"type":"tip","kind":"warn","text":"Never stand your chopsticks upright in a bowl of rice: it looks like incense sticks at a funeral. Don't tap your bowl with them or point them at people either."},{"type":"tip","kind":"culture","text":"When clinking glasses with an older person or a boss, hold your glass a little lower than theirs to show respect. If you don't want to drink it all, say {{随意}} and just take a sip."},{"type":"tip","kind":"culture","text":"Hosts traditionally order more than everyone can eat, to show generosity. Today many people also support the ‘Clean Plate’ campaign ({{光盘行动}}, guāngpán xíngdòng) against food waste, so finishing your rice is fine."},{"type":"steps","title":"Role-play: visiting a Chinese family","items":[{"title":"Give your gift","t":"一点儿小意思。","tr":"Yìdiǎnr xiǎo yìsi.","mean":"Just a little something.","desc":"Use both hands."},{"title":"Greet the parents","t":"叔叔好！阿姨好！","tr":"Shūshu hǎo! Āyí hǎo!","mean":"Hello, uncle! Hello, auntie!"},{"title":"Praise the food","t":"太好吃了！","tr":"Tài hǎochī le!","mean":"It's delicious!"},{"title":"Toast your host","t":"我敬您一杯！","tr":"Wǒ jìng nín yì bēi!","mean":"A toast to you!","desc":"Hold your glass a little lower than theirs."},{"title":"Thank them and leave","t":"谢谢款待，我先走了。","tr":"Xièxie kuǎndài, wǒ xiān zǒu le.","mean":"Thank you for your hospitality. I'll be going now."}]},{"type":"practice","title":"Say it aloud","text":"Read each line aloud.","lines":["您贵姓？","我姓李。","一点儿小意思，请收下。","我敬您一杯！","干杯！","大家慢慢吃。"]},{"type":"quiz","title":"Quick quiz","items":[{"q":"In the name {{王小明}}, which part is the surname?","options":["小明","明","王","小"],"answer":2},{"q":"Which number is considered unlucky?","options":["8","4","6","9"],"answer":1},{"q":"Why is 8 a lucky number?","options":["Its shape looks like a dragon","It's the emperor's age","It's the number of festivals","It sounds like “prosper”"],"answer":3},{"q":"What should you NOT do with chopsticks?","options":["Stand them up in your rice","Use them to pick up vegetables","Put them down on the chopstick rest","Hold them near the top"],"answer":0},{"q":"How do you give or receive a gift politely?","options":["With your left hand only","With both hands","Without looking at the person","Quickly and silently"],"answer":1},{"q":"Listen. What does it mean?","say":"干杯！","options":["Enjoy your meal!","Thank you!","Cheers!","Goodbye!"],"answer":2},{"q":"520 is popular online because it sounds like…","options":["“I'm hungry”","“Happy birthday”","“Goodbye”","“I love you”"],"answer":3},{"q":"Which gift is traditionally avoided?","options":["A clock","A basket of fruit","A box of tea","Chocolate"],"answer":0}]}]},{"id":"u6-review","icon":"复","title":"Final Review Lab","subtitle":"Bring everything together: conversation, reading, culture and the poem.","minutes":20,"goals":["Follow a longer conversation that mixes many topics","Check your listening and writing","Review culture, chengyu and the poem"],"blocks":[{"type":"text","text":"Congratulations on reaching the final lab! This lesson mixes everything from Units 5 and 6. Read, listen, write and test yourself. Don't worry about mistakes: {{慢慢来}}!"},{"type":"dialogue","title":"Plans for Mid-Autumn","lines":[{"who":"Xiaomei","t":"安娜，中秋节你有什么打算？","tr":"Ānnà, Zhōngqiū Jié nǐ yǒu shénme dǎsuan?","mean":"Anna, what are your plans for Mid-Autumn?"},{"who":"Anna","t":"还没想好。你呢？","tr":"Hái méi xiǎng hǎo. Nǐ ne?","mean":"I haven't decided yet. And you?"},{"who":"Xiaomei","t":"来我家吧！我妈妈会做很多菜。","tr":"Lái wǒ jiā ba! Wǒ māma huì zuò hěn duō cài.","mean":"Come to my place! My mum will cook lots of dishes."},{"who":"Anna","t":"太好了！我带什么礼物好呢？","tr":"Tài hǎo le! Wǒ dài shénme lǐwù hǎo ne?","mean":"Great! What gift should I bring?"},{"who":"Xiaomei","t":"带一盒月饼就行，别带钟啊！","tr":"Dài yì hé yuèbing jiù xíng, bié dài zhōng a!","mean":"A box of mooncakes is fine. Just don't bring a clock!"},{"who":"Anna","t":"哈哈，我知道！晚上我们一起赏月吧。","tr":"Hāhā, wǒ zhīdào! Wǎnshang wǒmen yìqǐ shǎng yuè ba.","mean":"Haha, I know! Let's admire the moon together in the evening."},{"who":"Xiaomei","t":"好啊。天气预报说那天是晴天。","tr":"Hǎo a. Tiānqì yùbào shuō nà tiān shì qíngtiān.","mean":"Sure. The forecast says it'll be sunny that day."},{"who":"Anna","t":"那我们可以一起念《静夜思》！","tr":"Nà wǒmen kěyǐ yìqǐ niàn “Jìng Yè Sī”!","mean":"Then we can recite “Quiet Night Thoughts” together!"}]},{"type":"sentence","t":"你周末想去哪儿玩？","tr":"Nǐ zhōumò xiǎng qù nǎr wán?","mean":"Where do you want to go this weekend?","words":[{"t":"你","mean":"you"},{"t":"周末","mean":"weekend"},{"t":"想","mean":"want"},{"t":"去","mean":"go"},{"t":"哪儿","mean":"where"},{"t":"玩","mean":"have fun"}],"title":"Sentence puzzle 1"},{"type":"sentence","t":"我在中国学了很多东西。","tr":"Wǒ zài Zhōngguó xué le hěn duō dōngxi.","mean":"I learned a lot in China.","words":[{"t":"我","mean":"I"},{"t":"在","mean":"in"},{"t":"中国","mean":"China"},{"t":"学了","mean":"learned"},{"t":"很多","mean":"a lot of"},{"t":"东西","mean":"things"}],"title":"Sentence puzzle 2"},{"type":"sentence","t":"请问，附近有好吃的饭馆吗？","tr":"Qǐngwèn, fùjìn yǒu hǎochī de fànguǎn ma?","mean":"Excuse me, is there a good restaurant nearby?","words":[{"t":"请问","mean":"excuse me"},{"t":"附近","mean":"nearby"},{"t":"有","mean":"is there"},{"t":"好吃的","mean":"tasty"},{"t":"饭馆","mean":"restaurant"},{"t":"吗","mean":"(question word)"}],"title":"Sentence puzzle 3"},{"type":"dictation","title":"Listen and write","items":[{"t":"多少钱？","tr":"Duōshao qián?","mean":"How much is it?"},{"t":"往左拐。","tr":"Wǎng zuǒ guǎi.","mean":"Turn left."},{"t":"我头疼。","tr":"Wǒ tóuténg.","mean":"I have a headache."},{"t":"你有空吗？","tr":"Nǐ yǒu kòng ma?","mean":"Are you free?"},{"t":"新年快乐！","tr":"Xīnnián kuàilè!","mean":"Happy New Year!"},{"t":"举头望明月。","tr":"Jǔ tóu wàng míng yuè.","mean":"I raise my head and gaze at the bright moon."}]},{"type":"steps","title":"Challenge: a day out in China","items":[{"title":"Ask the way","t":"请问，地铁站怎么走？","tr":"Qǐngwèn, dìtiězhàn zěnme zǒu?","mean":"Excuse me, how do I get to the subway station?"},{"title":"Take the subway","t":"去西单坐几号线？","tr":"Qù Xīdān zuò jǐ hào xiàn?","mean":"Which line goes to Xidan?"},{"title":"Go shopping","t":"太贵了，便宜一点儿吧！","tr":"Tài guì le, piányi yìdiǎnr ba!","mean":"Too expensive. Make it cheaper!"},{"title":"Order lunch","t":"来一碗牛肉面，不要太辣。","tr":"Lái yì wǎn niúròu miàn, bú yào tài là.","mean":"A bowl of beef noodles, not too spicy."},{"title":"Message a friend","t":"我们晚上见吧，不见不散！","tr":"Wǒmen wǎnshang jiàn ba, bú jiàn bú sàn!","mean":"Let's meet tonight. See you there!"}]},{"type":"selfcheck","title":"Can you do it?","items":["I can order food, ask about spice and pay the bill.","I can ask prices and bargain politely.","I can ask for and follow directions.","I can take a taxi or the subway.","I can make plans and say no politely.","I can tell a doctor what's wrong.","I can read a short story in characters.","I can recite 《静夜思》 from memory.","I can explain three festivals and a few customs."]},{"type":"practice","title":"Final read-aloud","text":"Read these favourite lines from the course aloud.","lines":["买单！","便宜一点儿吧。","不见不散！","多喝热水！","熟能生巧。","床前明月光，疑是地上霜。","举头望明月，低头思故乡。"]},{"type":"quiz","title":"Final quiz","items":[{"q":"You're at a restaurant and want the bill. You say…","options":["打包！","买单！","点菜！","干杯！"],"answer":1},{"q":"Listen. What is the shopper asking?","say":"便宜一点儿吧。","options":["It's too small","I'll take two","Do you have any other colours?","Make it a bit cheaper"],"answer":3},{"q":"{{往左拐}} means…","options":["turn left","turn right","go straight","get off"],"answer":0},{"q":"Which festival has dragon boat races?","options":["春节","中秋节","端午节","元宵节"],"answer":2},{"q":"Complete the poem: 举头望明月，……","options":["低头思故乡","疑是地上霜","床前明月光","低头看月亮"],"answer":0},{"q":"Which gift should you avoid?","options":["茶 (tea)","水果 (fruit)","钟 (a clock)","月饼 (mooncakes)"],"answer":2},{"q":"Listen. What does the speaker say?","say":"我对花生过敏。","options":["I like peanuts","I have a cold","Peanuts are cheap here","I'm allergic to peanuts"],"answer":3},{"q":"{{熟能生巧}} means…","options":["Take your time","Practice makes perfect","Safe journey","Never too old to learn anything"],"answer":1}]}]}]});
